SELECT
    T.TREATMENT_NAME,
    S.SEX_NAME,
    G.GENOTYPE_NAME,
    SUM(R.RESULT_VALUE) AS CUMULATIVE_RESULT_VALUE
FROM
    RESULTS R
INNER JOIN
    TREATMENTS T ON R.TREATMENT_ID = T.TREATMENT_ID
INNER JOIN
    GENOTYPES G ON R.GENOTYPE_ID = G.GENOTYPE_ID
INNER JOIN
    SEXES S ON R.SEX_ID = S.SEX_ID
GROUP BY
    T.TREATMENT_NAME,
    S.SEX_NAME,
    G.GENOTYPE_NAME
ORDER BY
    S.SEX_NAME,
    G.GENOTYPE_NAME;
SELECT T.TREATMENT_NAME, G.GENOTYPE_NAME, S.SEX_NAME, SUM(R.RESULT_VALUE) AS CUMULATIVE_RESULTS FROM RESULTS R JOIN TREATMENTS T ON R.TREATMENT_ID = T.TREATMENT_ID JOIN GENOTYPES G ON R.GENOTYPE_ID = G.GENOTYPE_ID JOIN SEXES S ON R.SEX_ID = S.SEX_ID GROUP BY T.TREATMENT_NAME, G.GENOTYPE_NAME, S.SEX_NAME ORDER BY S.SEX_NAME, G.GENOTYPE_NAME;

