SELECT T.TRUCK_ID, T.MAKE, T.MODEL, T.YEAR, T.LICENSE_PLATE, D.NAME AS DRIVER_NAME, D.STATUS AS DRIVER_STATUS, SUM(I.AMOUNT) AS TOTAL_INCOME, SUM(C.AMOUNT) AS TOTAL_CONTRIBUTIONS, SUM(K.DISTANCE) AS TOTAL_DISTANCE FROM TRUCKS T JOIN PRIMARY_FLEETS PF ON T.PRIMARY_FLEET_ID = PF.PRIMARY_FLEET_ID JOIN DRIVERS D ON T.DRIVER_ID = D.DRIVER_ID LEFT JOIN INCOME I ON T.TRUCK_ID = I.TRUCK_ID LEFT JOIN CONTRIBUTIONS C ON T.TRUCK_ID = C.TRUCK_ID LEFT JOIN KMS K ON T.TRUCK_ID = K.TRUCK_ID WHERE PF.NAME = 'ANGLO - DEDICATED' AND T.STATUS = 'ACTIVE' AND D.STATUS = 'ACTIVE' GROUP BY T.TRUCK_ID, T.MAKE, T.MODEL, T.YEAR, T.LICENSE_PLATE, D.NAME, D.STATUS ORDER BY TOTAL_INCOME DESC, TOTAL_CONTRIBUTIONS DESC, TOTAL_DISTANCE DESC;
