WITH MODEL_FORECAST_STATS AS ( SELECT FM.MODEL_ID, FM.MODEL_NAME, FM.MODEL_TYPE, FM.MODEL_VERSION, COUNT(FD.FORECAST_ID) AS TOTAL_FORECASTS, COUNT(CASE WHEN FD.FORECAST_TYPE = 'SHORT-TERM' THEN 1 END) AS SHORT_TERM_FORECASTS, COUNT(CASE WHEN FD.FORECAST_TYPE = 'LONG-TERM' THEN 1 END) AS LONG_TERM_FORECASTS, SUM(FD.PREDICTED_CASES) AS TOTAL_PREDICTED_CASES, SUM(FD.PREDICTED_HOSPITALIZATIONS) AS TOTAL_PREDICTED_HOSPITALIZATIONS, SUM(FD.PREDICTED_DEATHS) AS TOTAL_PREDICTED_DEATHS FROM FORECAST_MODELS FM LEFT JOIN FORECAST_DATA FD ON FM.MODEL_ID = FD.MODEL_ID GROUP BY FM.MODEL_ID, FM.MODEL_NAME, FM.MODEL_TYPE, FM.MODEL_VERSION ) SELECT MODEL_NAME, MODEL_TYPE, MODEL_VERSION, TOTAL_FORECASTS, SHORT_TERM_FORECASTS, LONG_TERM_FORECASTS, TOTAL_PREDICTED_CASES, TOTAL_PREDICTED_HOSPITALIZATIONS, TOTAL_PREDICTED_DEATHS FROM MODEL_FORECAST_STATS ORDER BY TOTAL_PREDICTED_CASES DESC LIMIT 10;
WITH MODEL_FORECAST_SUMMARY AS ( SELECT FD.MODEL_ID, FM.MODEL_NAME, FM.MODEL_TYPE, FM.MODEL_VERSION, COUNT(*) AS NUM_FORECASTS, SUM(CASE WHEN FD.FORECAST_TYPE = 'SHORT-TERM' THEN 1 ELSE 0 END) AS SHORT_TERM_FORECASTS, SUM(CASE WHEN FD.FORECAST_TYPE = 'LONG-TERM' THEN 1 ELSE 0 END) AS LONG_TERM_FORECASTS, SUM(FD.PREDICTED_CASES) AS TOTAL_PREDICTED_CASES, SUM(FD.PREDICTED_HOSPITALIZATIONS) AS TOTAL_PREDICTED_HOSPITALIZATIONS, SUM(FD.PREDICTED_DEATHS) AS TOTAL_PREDICTED_DEATHS FROM FORECAST_DATA FD INNER JOIN FORECAST_MODELS FM ON FD.MODEL_ID = FM.MODEL_ID GROUP BY FD.MODEL_ID, FM.MODEL_NAME, FM.MODEL_TYPE, FM.MODEL_VERSION ) SELECT MODEL_NAME, MODEL_TYPE, MODEL_VERSION, NUM_FORECASTS, SHORT_TERM_FORECASTS, LONG_TERM_FORECASTS, TOTAL_PREDICTED_CASES, TOTAL_PREDICTED_HOSPITALIZATIONS, TOTAL_PREDICTED_DEATHS FROM MODEL_FORECAST_SUMMARY ORDER BY TOTAL_PREDICTED_CASES DESC LIMIT 10;

