SELECT M.MODEL_NAME FROM MODEL M JOIN ( SELECT ER.MODEL_ID, AVG(ME.VALUE) AS AVG_METRIC_VALUE FROM EVALUATION_RUN ER JOIN METRIC ME ON ER.RUN_ID = ME.RUN_ID GROUP BY ER.MODEL_ID ) AS MODEL_AVERAGES ON M.MODEL_ID = MODEL_AVERAGES.MODEL_ID WHERE MODEL_AVERAGES.AVG_METRIC_VALUE > ( SELECT AVG(AVG_METRIC_VALUE) FROM ( SELECT AVG(ME.VALUE) AS AVG_METRIC_VALUE FROM EVALUATION_RUN ER JOIN METRIC ME ON ER.RUN_ID = ME.RUN_ID GROUP BY ER.MODEL_ID ) ) ORDER BY MODEL_AVERAGES.AVG_METRIC_VALUE DESC LIMIT 1;
WITH MODELAVGMETRICSCTE AS ( SELECT M.MODEL_NAME, AVG(MET.VALUE) AS AVERAGE_VALUE FROM METRIC MET JOIN EVALUATION_RUN ER ON MET.RUN_ID = ER.RUN_ID JOIN MODEL M ON ER.MODEL_ID = M.MODEL_ID GROUP BY M.MODEL_NAME ), OVERALLAVGMETRIC AS ( SELECT AVG(AVERAGE_VALUE) AS OVERALL_AVERAGE FROM MODELAVGMETRICSCTE ) SELECT MAM.MODEL_NAME FROM MODELAVGMETRICSCTE MAM JOIN OVERALLAVGMETRIC OAM ON 1=1 WHERE MAM.AVERAGE_VALUE > OAM.OVERALL_AVERAGE ORDER BY MAM.AVERAGE_VALUE DESC LIMIT 1;

