WITH OBSCOUNTS AS ( SELECT DEPLOYMENT_ID, COUNT(OBSERVATION_ID) AS OBS_COUNT FROM OBSERVATIONS GROUP BY DEPLOYMENT_ID ), ACCCOUNTS AS ( SELECT RESEARCHER_ID, COUNT(ACCESS_ID) AS ACC_COUNT FROM ACCESS_LOGS GROUP BY RESEARCHER_ID ), DEPCOUNTS AS ( SELECT RESEARCHER_ID, COUNT(DEPLOYMENT_ID) AS DEP_COUNT FROM DEPLOYMENTS GROUP BY RESEARCHER_ID ) SELECT D.DEPLOYMENT_ID, COALESCE(OC.OBS_COUNT, 0) AS OBSERVATION_COUNT, COALESCE(AC.ACC_COUNT, 0) AS ACCESS_COUNT, COALESCE(DC.DEP_COUNT, 0) AS DEPLOYMENT_COUNT FROM DEPLOYMENTS D LEFT JOIN OBSCOUNTS OC ON D.DEPLOYMENT_ID = OC.DEPLOYMENT_ID LEFT JOIN ACCCOUNTS AC ON D.RESEARCHER_ID = AC.RESEARCHER_ID LEFT JOIN DEPCOUNTS DC ON D.RESEARCHER_ID = DC.RESEARCHER_ID ORDER BY D.DEPLOYMENT_ID;
WITH OBSERVATIONCOUNTS AS (
    SELECT
        DEPLOYMENT_ID,
        COUNT(OBSERVATION_ID) AS OBSERVATION_COUNT
    FROM OBSERVATIONS
    GROUP BY DEPLOYMENT_ID
),
ACCESSCOUNTS AS (
    SELECT
        RESEARCHER_ID,
        COUNT(ACCESS_ID) AS ACCESS_COUNT
    FROM ACCESS_LOGS
    GROUP BY RESEARCHER_ID
),
DEPLOYMENTCOUNTS AS (
    SELECT
        RESEARCHER_ID,
        COUNT(DEPLOYMENT_ID) AS DEPLOYMENT_COUNT
    FROM DEPLOYMENTS
    GROUP BY RESEARCHER_ID
)
SELECT
    D.DEPLOYMENT_ID,
    OC.OBSERVATION_COUNT,
    AC.ACCESS_COUNT,
    DC.DEPLOYMENT_COUNT
FROM DEPLOYMENTS D
JOIN OBSERVATIONCOUNTS OC ON D.DEPLOYMENT_ID = OC.DEPLOYMENT_ID
JOIN ACCESSCOUNTS AC ON D.RESEARCHER_ID = AC.RESEARCHER_ID
JOIN DEPLOYMENTCOUNTS DC ON D.RESEARCHER_ID = DC.RESEARCHER_ID
ORDER BY D.DEPLOYMENT_ID;

