WITH ACTIVITYPARTICIPANTS AS ( SELECT R.ACTIVITY_ID, COUNT(R.PARTICIPANT_ID) AS PARTICIPANT_COUNT FROM REGISTRATIONS R GROUP BY R.ACTIVITY_ID ), ACTIVITYFEEDBACK AS ( SELECT F.ACTIVITY_ID, AVG(F.RATING) AS AVERAGE_RATING, COUNT(F.FEEDBACK_ID) AS FEEDBACK_COUNT FROM FEEDBACK F GROUP BY F.ACTIVITY_ID ) SELECT A.ACTIVITY_NAME, AP.PARTICIPANT_COUNT FROM ACTIVITIES A INNER JOIN ACTIVITYPARTICIPANTS AP ON A.ACTIVITY_ID = AP.ACTIVITY_ID INNER JOIN ACTIVITYFEEDBACK AF ON A.ACTIVITY_ID = AF.ACTIVITY_ID ORDER BY AF.AVERAGE_RATING DESC, AF.FEEDBACK_COUNT DESC, AP.PARTICIPANT_COUNT DESC LIMIT 10;

