WITH ITEMSALES AS ( SELECT ITEM_ID, SUM(QUANTITY_SOLD) AS TOTAL_SALES_QUANTITY, SUM(TOTAL_PRICE) AS TOTAL_SALES_VALUE FROM SALES GROUP BY ITEM_ID ), ITEMFEEDBACK AS ( SELECT ITEM_ID, AVG(SATISFACTION_RATING) AS AVERAGE_SATISFACTION_RATING FROM CUSTOMER_FEEDBACK GROUP BY ITEM_ID ), ITEMINVENTORY AS ( SELECT ITEM_ID, SUM(QUANTITY_IN_STOCK) AS CURRENT_STOCK_QUANTITY FROM INVENTORY GROUP BY ITEM_ID ) SELECT CI.NAME AS ITEM_NAME, ISALES.TOTAL_SALES_QUANTITY, ISALES.TOTAL_SALES_VALUE, IFEEDBACK.AVERAGE_SATISFACTION_RATING, IINVENTORY.CURRENT_STOCK_QUANTITY FROM ITEMSALES ISALES INNER JOIN ITEMFEEDBACK IFEEDBACK ON ISALES.ITEM_ID = IFEEDBACK.ITEM_ID INNER JOIN ITEMINVENTORY IINVENTORY ON ISALES.ITEM_ID = IINVENTORY.ITEM_ID INNER JOIN CLOTHING_ITEMS CI ON ISALES.ITEM_ID = CI.ITEM_ID WHERE ISALES.TOTAL_SALES_QUANTITY >= 10 ORDER BY ISALES.TOTAL_SALES_QUANTITY DESC;
WITH SALESSUMMARY AS ( SELECT S.ITEM_ID, SUM(S.QUANTITY_SOLD) AS TOTAL_QUANTITY_SOLD, SUM(S.TOTAL_PRICE) AS TOTAL_SALES FROM SALES S GROUP BY S.ITEM_ID HAVING SUM(S.QUANTITY_SOLD) >= 10 ), CUSTOMERFEEDBACKSUMMARY AS ( SELECT F.ITEM_ID, AVG(F.SATISFACTION_RATING) AS AVG_SATISFACTION_RATING FROM CUSTOMER_FEEDBACK F GROUP BY F.ITEM_ID ), INVENTORYSUMMARY AS ( SELECT I.ITEM_ID, SUM(I.QUANTITY_IN_STOCK) AS TOTAL_QUANTITY_IN_STOCK FROM INVENTORY I GROUP BY I.ITEM_ID ) SELECT CI.NAME AS ITEM_NAME, SS.TOTAL_QUANTITY_SOLD, SS.TOTAL_SALES, CFS.AVG_SATISFACTION_RATING, ISUM.TOTAL_QUANTITY_IN_STOCK FROM SALESSUMMARY SS JOIN CLOTHING_ITEMS CI ON SS.ITEM_ID = CI.ITEM_ID LEFT JOIN CUSTOMERFEEDBACKSUMMARY CFS ON SS.ITEM_ID = CFS.ITEM_ID LEFT JOIN INVENTORYSUMMARY ISUM ON SS.ITEM_ID = ISUM.ITEM_ID ORDER BY SS.TOTAL_QUANTITY_SOLD DESC;

