SELECT U.USER_ID, T.TOKEN_SYMBOL, CASE WHEN I.INVESTMENT_AMOUNT > V.TVL THEN 'HIGH RISK' ELSE 'LOW RISK' END AS INVESTMENTRISK, CASE WHEN V.ALLOWED_TOKEN = T.TOKEN_SYMBOL THEN 'ALLOWED' ELSE 'NOT ALLOWED' END AS TOKENSTATUS, P.RISK_TOLERANCE, P.INVESTMENT_GOAL FROM USERS U JOIN RISK_PROFILES P ON U.USER_ID = P.USER_ID JOIN INVESTMENTS I ON U.USER_ID = I.USER_ID JOIN TOKENS T ON I.TOKEN_ID = T.TOKEN_ID JOIN VAULTS V ON I.VAULT_ID = V.VAULT_ID ORDER BY U.USER_ID;
WITH INVESTMENT_DETAILS AS ( SELECT I.USER_ID, T.TOKEN_SYMBOL, I.INVESTMENT_AMOUNT, V.TVL, V.ALLOWED_TOKEN FROM INVESTMENTS I INNER JOIN TOKENS T ON I.TOKEN_ID = T.TOKEN_ID INNER JOIN VAULTS V ON I.VAULT_ID = V.VAULT_ID ), RISK_AND_STATUS AS ( SELECT USER_ID, TOKEN_SYMBOL, CASE WHEN INVESTMENT_AMOUNT > TVL THEN 'HIGH RISK' ELSE 'LOW RISK' END AS INVESTMENT_RISK, CASE WHEN TOKEN_SYMBOL = ALLOWED_TOKEN THEN 'ALLOWED' ELSE 'NOT ALLOWED' END AS TOKEN_STATUS FROM INVESTMENT_DETAILS ) SELECT RAS.USER_ID, RAS.TOKEN_SYMBOL, RAS.INVESTMENT_RISK, RAS.TOKEN_STATUS, R.RISK_TOLERANCE, R.INVESTMENT_GOAL FROM RISK_AND_STATUS RAS INNER JOIN RISK_PROFILES R ON RAS.USER_ID = R.USER_ID ORDER BY RAS.USER_ID;

