WITH TOTALPROJECTS AS ( SELECT COUNTRY, COUNT(*) AS TOTAL_PROJECTS FROM PROJECTS GROUP BY COUNTRY ), SUCCESSFULPROJECTS AS ( SELECT P.COUNTRY, COUNT(*) AS SUCCESSFUL_PROJECTS FROM PROJECTS P JOIN PROJECT_OUTCOMES PO ON P.PROJECT_ID = PO.PROJECT_ID AND PO.OUTCOME = 'SUCCESSFUL' GROUP BY P.COUNTRY ), SUCCESSRATES AS ( SELECT T.COUNTRY, COALESCE(S.SUCCESSFUL_PROJECTS, 0) AS SUCCESSFUL_PROJECTS, T.TOTAL_PROJECTS, ROUND((COALESCE(S.SUCCESSFUL_PROJECTS, 0) * 100.0 / T.TOTAL_PROJECTS), 2) AS SUCCESS_RATE FROM TOTALPROJECTS T LEFT JOIN SUCCESSFULPROJECTS S ON T.COUNTRY = S.COUNTRY ) SELECT COUNTRY, SUCCESS_RATE FROM SUCCESSRATES ORDER BY SUCCESS_RATE DESC;

