SELECT E.EXPERIMENT_NAME FROM EXPERIMENTS E JOIN PERFORMANCE_METRICS PM ON E.EXPERIMENT_ID = PM.EXPERIMENT_ID GROUP BY E.EXPERIMENT_ID HAVING AVG(PM.BLEU_SCORE) = ( SELECT MAX(AVG_BLEU) FROM ( SELECT AVG(PM2.BLEU_SCORE) AS AVG_BLEU FROM EXPERIMENTS E2 JOIN PERFORMANCE_METRICS PM2 ON E2.EXPERIMENT_ID = PM2.EXPERIMENT_ID GROUP BY E2.EXPERIMENT_ID ) ) AND MAX(PM.SPARSITY) = ( SELECT MIN(MAX_SPARSITY) FROM ( SELECT MAX(PM3.SPARSITY) AS MAX_SPARSITY FROM EXPERIMENTS E3 JOIN PERFORMANCE_METRICS PM3 ON E3.EXPERIMENT_ID = PM3.EXPERIMENT_ID GROUP BY E3.EXPERIMENT_ID HAVING AVG(PM3.BLEU_SCORE) = ( SELECT MAX(AVG_BLEU) FROM ( SELECT AVG(PM4.BLEU_SCORE) AS AVG_BLEU FROM EXPERIMENTS E4 JOIN PERFORMANCE_METRICS PM4 ON E4.EXPERIMENT_ID = PM4.EXPERIMENT_ID GROUP BY E4.EXPERIMENT_ID ) ) ) ) LIMIT 1;
WITH AVERAGEBLEUSCORES AS ( SELECT EXPERIMENT_ID, AVG(BLEU_SCORE) AS AVG_BLEU_SCORE FROM PERFORMANCE_METRICS GROUP BY EXPERIMENT_ID ), MAXSPARSITY AS ( SELECT EXPERIMENT_ID, MAX(SPARSITY) AS MAX_SPARSITY FROM PERFORMANCE_METRICS GROUP BY EXPERIMENT_ID ) SELECT E.EXPERIMENT_NAME FROM EXPERIMENTS E JOIN AVERAGEBLEUSCORES ABS ON E.EXPERIMENT_ID = ABS.EXPERIMENT_ID JOIN MAXSPARSITY MS ON E.EXPERIMENT_ID = MS.EXPERIMENT_ID ORDER BY ABS.AVG_BLEU_SCORE DESC, MS.MAX_SPARSITY ASC LIMIT 1;

