SELECT I.IMAGE_NAME, CR.COMPRESSION_RATIO, CR.PSNR, CA.ALGORITHM_NAME, COUNT(AL.ACCESS_ID) AS ACCESS_COUNT, U.USER_NAME, U.ROLE FROM COMPRESSION_RESULTS CR INNER JOIN COMPRESSION_SETTINGS CS ON CR.SETTING_ID = CS.SETTING_ID INNER JOIN COMPRESSION_ALGORITHMS CA ON CS.ALGORITHM_ID = CA.ALGORITHM_ID INNER JOIN IMAGES I ON CS.IMAGE_ID = I.IMAGE_ID INNER JOIN USERS U ON I.UPLOADED_BY = U.USER_ID LEFT JOIN ACCESS_LOGS AL ON I.IMAGE_ID = AL.IMAGE_ID GROUP BY I.IMAGE_NAME, CR.COMPRESSION_RATIO, CR.PSNR, CA.ALGORITHM_NAME, U.USER_NAME, U.ROLE ORDER BY CR.COMPRESSION_RATIO DESC, CR.PSNR DESC, COUNT(AL.ACCESS_ID) DESC;
WITH ACCESSCOUNTS AS ( SELECT IMAGE_ID, COUNT(ACCESS_ID) AS ACCESS_COUNT FROM ACCESS_LOGS GROUP BY IMAGE_ID ) SELECT I.IMAGE_NAME, CR.COMPRESSION_RATIO, CR.PSNR, CA.ALGORITHM_NAME, COALESCE(IAC.ACCESS_COUNT, 0) AS ACCESS_COUNT, U.USER_NAME, U.ROLE FROM IMAGES I INNER JOIN COMPRESSION_RESULTS CR ON I.IMAGE_ID = CR.RESULT_ID INNER JOIN COMPRESSION_ALGORITHMS CA ON CR.COMPRESSION_ALGORITHM = CA.ALGORITHM_NAME LEFT JOIN ACCESSCOUNTS IAC ON I.IMAGE_ID = IAC.IMAGE_ID INNER JOIN USERS U ON I.UPLOADED_BY = U.USER_ID ORDER BY CR.COMPRESSION_RATIO DESC, CR.PSNR DESC, IAC.ACCESS_COUNT DESC;

