WITH CATEGORYDOCUMENTCOUNTS AS ( SELECT PC.CATEGORY_NAME, COUNT(PD.DOCUMENT_ID) AS TOTAL_DOCUMENTS FROM PRODUCT_CATEGORIES PC LEFT JOIN PRODUCT_DOCUMENTS PD ON PC.CATEGORY_ID = PD.PRODUCT_ID GROUP BY PC.CATEGORY_NAME ), CATEGORYSTORAGESUMS AS ( SELECT PC.CATEGORY_NAME, SUM(PD.FILE_SIZE) AS TOTAL_STORAGE FROM PRODUCT_CATEGORIES PC LEFT JOIN PRODUCT_DOCUMENTS PD ON PC.CATEGORY_ID = PD.PRODUCT_ID GROUP BY PC.CATEGORY_NAME ) SELECT CDC.CATEGORY_NAME, CDC.TOTAL_DOCUMENTS, CSS.TOTAL_STORAGE FROM CATEGORYDOCUMENTCOUNTS CDC JOIN CATEGORYSTORAGESUMS CSS ON CDC.CATEGORY_NAME = CSS.CATEGORY_NAME ORDER BY CDC.CATEGORY_NAME;
WITH PRODUCTCATEGORYLINK AS ( SELECT PC.CATEGORY_ID, PC.CATEGORY_NAME, PD.PRODUCT_ID FROM PRODUCT_DOCUMENTS PD JOIN PRODUCT_CATEGORIES PC ON PD.PRODUCT_ID = PC.CATEGORY_ID ), PRODUCTDOCUMENTSTATS AS ( SELECT PCL.PRODUCT_ID, PCL.CATEGORY_ID, PCL.CATEGORY_NAME, COUNT(PD.DOCUMENT_ID) AS DOCUMENT_COUNT, SUM(PD.FILE_SIZE) AS TOTAL_FILE_SIZE FROM PRODUCTCATEGORYLINK PCL JOIN PRODUCT_DOCUMENTS PD ON PCL.PRODUCT_ID = PD.PRODUCT_ID GROUP BY PCL.PRODUCT_ID, PCL.CATEGORY_ID, PCL.CATEGORY_NAME ), CATEGORYDOCUMENTSTATS AS ( SELECT CATEGORY_ID, CATEGORY_NAME, SUM(DOCUMENT_COUNT) AS TOTAL_DOCUMENT_COUNT, SUM(TOTAL_FILE_SIZE) AS TOTAL_CATEGORY_SIZE FROM PRODUCTDOCUMENTSTATS GROUP BY CATEGORY_ID, CATEGORY_NAME ) SELECT CDS.CATEGORY_NAME AS "CATEGORY", CDS.TOTAL_DOCUMENT_COUNT AS "TOTAL DOCUMENTS", CDS.TOTAL_CATEGORY_SIZE AS "TOTAL STORAGE (MB)" FROM CATEGORYDOCUMENTSTATS CDS ORDER BY CDS.CATEGORY_NAME;

