SELECT 
    C.CANDIDATE_NAME,
    P.PRECINCT_NAME,
    SUM(V.VOTES) AS TOTAL_VOTES,
    AVG(V.VOTE_PERCENTAGE) AS AVG_VOTE_PERCENTAGE,
    P.VOTER_TURNOUT_RATE
FROM 
    VOTE_RESULTS V
JOIN 
    CANDIDATES C ON V.CANDIDATE_ID = C.CANDIDATE_ID
JOIN 
    PRECINCTS P ON V.PRECINCT_ID = P.PRECINCT_ID
GROUP BY 
    C.CANDIDATE_NAME, P.PRECINCT_NAME, P.VOTER_TURNOUT_RATE
ORDER BY 
    C.CANDIDATE_NAME, P.PRECINCT_NAME;
WITH CANDIDATEVOTES AS ( SELECT VR.PRECINCT_ID, VR.CANDIDATE_ID, SUM(VR.VOTES) AS TOTAL_VOTES, AVG(VR.VOTE_PERCENTAGE) AS AVG_VOTE_PERCENTAGE FROM VOTE_RESULTS VR GROUP BY VR.PRECINCT_ID, VR.CANDIDATE_ID ), PRECINCTTURNOUT AS ( SELECT P.PRECINCT_ID, P.PRECINCT_NAME, P.VOTER_TURNOUT_RATE FROM PRECINCTS P ) SELECT C.CANDIDATE_NAME, PT.PRECINCT_NAME, CV.TOTAL_VOTES, CV.AVG_VOTE_PERCENTAGE, PT.VOTER_TURNOUT_RATE FROM CANDIDATEVOTES CV JOIN CANDIDATES C ON CV.CANDIDATE_ID = C.CANDIDATE_ID JOIN PRECINCTTURNOUT PT ON CV.PRECINCT_ID = PT.PRECINCT_ID ORDER BY C.CANDIDATE_NAME, PT.PRECINCT_NAME;

