WITH INVALIDRECORDCOUNTS AS ( SELECT SD.SENSOR_ID, DIC.USER_ID, COUNT(*) AS INVALID_COUNT FROM SENSOR_DATA SD INNER JOIN DATA_INTEGRITY_CHECKS DIC ON SD.RECORD_ID = DIC.RECORD_ID WHERE DIC.IS_VALID = 0 GROUP BY SD.SENSOR_ID, DIC.USER_ID ) SELECT S.SENSOR_NAME, S.TYPE, U.USERNAME, IRC.INVALID_COUNT FROM INVALIDRECORDCOUNTS IRC INNER JOIN SENSORS S ON IRC.SENSOR_ID = S.SENSOR_ID INNER JOIN USERS U ON IRC.USER_ID = U.USER_ID ORDER BY IRC.INVALID_COUNT DESC;

