WITH ACCEPTEDCONTRIBUTIONS AS ( SELECT C.USER_ID, C.MODULE_ID, COUNT(C.CONTRIBUTION_ID) AS ACCEPTED_CONTRIBUTIONS FROM CONTRIBUTIONS C INNER JOIN USER_MODULE_ASSOCIATIONS UMA ON C.USER_ID = UMA.USER_ID AND C.MODULE_ID = UMA.MODULE_ID WHERE C.STATUS = 'ACCEPTED' GROUP BY C.USER_ID, C.MODULE_ID ), AVERAGECONTRIBUTIONS AS ( SELECT MODULE_ID, AVG(ACCEPTED_CONTRIBUTIONS) AS AVERAGE_CONTRIBUTIONS FROM ACCEPTEDCONTRIBUTIONS GROUP BY MODULE_ID ) SELECT COUNT(DISTINCT AC.USER_ID) AS USER_COUNT FROM ACCEPTEDCONTRIBUTIONS AC JOIN AVERAGECONTRIBUTIONS AVC ON AC.MODULE_ID = AVC.MODULE_ID WHERE AC.ACCEPTED_CONTRIBUTIONS > AVC.AVERAGE_CONTRIBUTIONS;
WITH ACCEPTED_CONTRIBUTIONS_PER_MODULE AS ( SELECT M.MODULE_ID, AVG(CASE WHEN C.STATUS = 'ACCEPTED' THEN 1 ELSE 0 END) AS AVERAGE_ACCEPTED_CONTRIBUTIONS FROM CONTRIBUTIONS C JOIN MODULES M ON C.MODULE_ID = M.MODULE_ID GROUP BY M.MODULE_ID ), ACCEPTED_CONTRIBUTIONS_PER_USER AS ( SELECT C.USER_ID, SUM(CASE WHEN C.STATUS = 'ACCEPTED' THEN 1 ELSE 0 END) AS ACCEPTED_CONTRIBUTIONS FROM CONTRIBUTIONS C GROUP BY C.USER_ID ), FILTERED_USERS AS ( SELECT AC.USER_ID FROM ACCEPTED_CONTRIBUTIONS_PER_USER AC JOIN CONTRIBUTIONS C ON AC.USER_ID = C.USER_ID JOIN ACCEPTED_CONTRIBUTIONS_PER_MODULE AM ON C.MODULE_ID = AM.MODULE_ID GROUP BY AC.USER_ID HAVING SUM(CASE WHEN C.STATUS = 'ACCEPTED' THEN 1 ELSE 0 END) > AVG(AM.AVERAGE_ACCEPTED_CONTRIBUTIONS) ) SELECT COUNT(DISTINCT USER_ID) AS TOTAL_USERS FROM FILTERED_USERS;

