WITH FUNCTIONUSAGE AS ( SELECT UL.FUNCTION_ID, COUNT(*) AS USAGE_COUNT FROM USAGE_LOGS UL GROUP BY UL.FUNCTION_ID ), TOPFUNCTIONS AS ( SELECT FU.FUNCTION_ID, F.FUNCTION_NAME, FU.USAGE_COUNT FROM FUNCTIONUSAGE FU INNER JOIN FUNCTIONS F ON FU.FUNCTION_ID = F.FUNCTION_ID ORDER BY FU.USAGE_COUNT DESC LIMIT 10 ) SELECT TF.FUNCTION_NAME, U.USER_NAME, COUNT(UL.FUNCTION_ID) AS USER_USAGE_COUNT FROM TOPFUNCTIONS TF INNER JOIN USAGE_LOGS UL ON TF.FUNCTION_ID = UL.FUNCTION_ID INNER JOIN USERS U ON UL.USER_ID = U.USER_ID GROUP BY TF.FUNCTION_NAME, U.USER_NAME ORDER BY TF.FUNCTION_NAME, USER_USAGE_COUNT DESC;
WITH TOPFUNCTIONS AS ( SELECT FUNCTION_ID, COUNT(LOG_ID) AS USAGE_COUNT FROM USAGE_LOGS GROUP BY FUNCTION_ID ORDER BY USAGE_COUNT DESC LIMIT 10 ), USERUSAGE AS ( SELECT UL.FUNCTION_ID, UL.USER_ID, COUNT(UL.LOG_ID) AS USER_USAGE_COUNT FROM USAGE_LOGS UL JOIN TOPFUNCTIONS TF ON UL.FUNCTION_ID = TF.FUNCTION_ID GROUP BY UL.FUNCTION_ID, UL.USER_ID ) SELECT F.FUNCTION_NAME, U.USER_NAME, UU.USER_USAGE_COUNT FROM USERUSAGE UU JOIN FUNCTIONS F ON UU.FUNCTION_ID = F.FUNCTION_ID JOIN USERS U ON UU.USER_ID = U.USER_ID ORDER BY F.FUNCTION_NAME, UU.USER_USAGE_COUNT DESC;

