WITH AGGREGATEDDATA AS ( SELECT FR.COMPANY_ID, FR.REPORT_DATE, SUM(CASE WHEN FC.CATEGORY_NAME = 'SALES' THEN FD.AMOUNT ELSE 0 END) AS TOTAL_SALES, SUM(CASE WHEN FC.CATEGORY_TYPE = 'EXPENSE' THEN FD.AMOUNT ELSE 0 END) AS TOTAL_EXPENSES, SUM(CASE WHEN FC.CATEGORY_TYPE = 'INCOME' AND FC.CATEGORY_NAME != 'SALES' THEN FD.AMOUNT ELSE 0 END) AS TOTAL_OTHER_INCOME, SUM(CASE WHEN FC.CATEGORY_NAME = 'DEPRECIATION' THEN FD.AMOUNT ELSE 0 END) AS TOTAL_DEPRECIATION, SUM(CASE WHEN FC.CATEGORY_NAME = 'INTEREST' THEN FD.AMOUNT ELSE 0 END) AS TOTAL_INTEREST FROM FINANCIAL_REPORTS FR INNER JOIN FINANCIAL_DATA FD ON FR.REPORT_ID = FD.REPORT_ID INNER JOIN FINANCIAL_CATEGORIES FC ON FD.CATEGORY_ID = FC.CATEGORY_ID GROUP BY FR.COMPANY_ID, FR.REPORT_DATE ), PERFORMANCESCORES AS ( SELECT FP.REPORT_ID, CASE WHEN FP.SALES_PERFORMANCE = 'EXCEEDED' THEN 1 WHEN FP.SALES_PERFORMANCE = 'MET' THEN 0 ELSE -1 END AS SALES_PERFORMANCE_SCORE, CASE WHEN FP.EXPENSES_PERFORMANCE = 'EXCEEDED' THEN -1 WHEN FP.EXPENSES_PERFORMANCE = 'MET' THEN 0 ELSE 1 END AS EXPENSES_PERFORMANCE_SCORE, CASE WHEN FP.PROFIT_PERFORMANCE = 'EXCEEDED' THEN 1 WHEN FP.PROFIT_PERFORMANCE = 'MET' THEN 0 ELSE -1 END AS PROFIT_PERFORMANCE_SCORE FROM FINANCIAL_PERFORMANCE FP ), EXTERNALTRENDS AS ( SELECT ED.DATE, AVG(ED.DATA_VALUE) AS AVG_EXTERNAL_TREND FROM EXTERNAL_DATA ED GROUP BY ED.DATE ) SELECT C.COMPANY_NAME, C.CITY, C.COUNTRY, C.INDUSTRY, AD.REPORT_DATE, AD.TOTAL_SALES, AD.TOTAL_EXPENSES, AD.TOTAL_OTHER_INCOME, AD.TOTAL_DEPRECIATION, AD.TOTAL_INTEREST, PS.SALES_PERFORMANCE_SCORE, PS.EXPENSES_PERFORMANCE_SCORE, PS.PROFIT_PERFORMANCE_SCORE, COALESCE(ET.AVG_EXTERNAL_TREND, 0) AS AVG_EXTERNAL_TREND, (AD.TOTAL_SALES - AD.TOTAL_EXPENSES) AS NET_PROFIT, (AD.TOTAL_SALES - AD.TOTAL_EXPENSES - AD.TOTAL_DEPRECIATION - AD.TOTAL_INTEREST) AS OPERATING_INCOME FROM AGGREGATEDDATA AD INNER JOIN FINANCIAL_REPORTS FR ON AD.COMPANY_ID = FR.COMPANY_ID AND AD.REPORT_DATE = FR.REPORT_DATE INNER JOIN COMPANIES C ON AD.COMPANY_ID = C.COMPANY_ID LEFT JOIN PERFORMANCESCORES PS ON PS.REPORT_ID = FR.REPORT_ID LEFT JOIN EXTERNALTRENDS ET ON ET.DATE = AD.REPORT_DATE ORDER BY C.COMPANY_NAME, AD.REPORT_DATE;
WITH FINANCIALSUMMARY AS ( SELECT R.COMPANY_ID, C.COMPANY_NAME, C.CITY, C.COUNTRY, C.INDUSTRY, R.REPORT_DATE, SUM(R.SALES) AS TOTAL_SALES, SUM(R.EXPENSES) AS TOTAL_EXPENSES, SUM(R.OTHER_INCOME) AS TOTAL_OTHER_INCOME, SUM(R.DEPRECIATION) AS TOTAL_DEPRECIATION, SUM(R.INTEREST) AS TOTAL_INTEREST, AVG(CASE WHEN P.SALES_PERFORMANCE = 'EXCEEDED' THEN 1 ELSE 0 END) AS SALES_PERFORMANCE_SCORE, AVG(CASE WHEN P.EXPENSES_PERFORMANCE = 'EXCEEDED' THEN 1 ELSE 0 END) AS EXPENSES_PERFORMANCE_SCORE, AVG(CASE WHEN P.PROFIT_PERFORMANCE = 'EXCEEDED' THEN 1 ELSE 0 END) AS PROFIT_PERFORMANCE_SCORE FROM FINANCIAL_REPORTS R JOIN COMPANIES C ON R.COMPANY_ID = C.COMPANY_ID LEFT JOIN FINANCIAL_PERFORMANCE P ON R.REPORT_ID = P.REPORT_ID GROUP BY R.COMPANY_ID, C.COMPANY_NAME, C.CITY, C.COUNTRY, C.INDUSTRY, R.REPORT_DATE ), EXTERNALTRENDS AS ( SELECT E.DATE, AVG(E.DATA_VALUE) AS AVERAGE_EXTERNAL_TREND FROM EXTERNAL_DATA E GROUP BY E.DATE ) SELECT FS.COMPANY_NAME, FS.CITY, FS.COUNTRY, FS.INDUSTRY, FS.REPORT_DATE, FS.TOTAL_SALES, FS.TOTAL_EXPENSES, FS.TOTAL_OTHER_INCOME, FS.TOTAL_DEPRECIATION, FS.TOTAL_INTEREST, FS.SALES_PERFORMANCE_SCORE, FS.EXPENSES_PERFORMANCE_SCORE, FS.PROFIT_PERFORMANCE_SCORE, ET.AVERAGE_EXTERNAL_TREND, (FS.TOTAL_SALES - FS.TOTAL_EXPENSES - FS.TOTAL_DEPRECIATION - FS.TOTAL_INTEREST) AS NET_PROFIT, (FS.TOTAL_SALES - FS.TOTAL_EXPENSES) AS OPERATING_INCOME FROM FINANCIALSUMMARY FS LEFT JOIN EXTERNALTRENDS ET ON FS.REPORT_DATE = ET.DATE ORDER BY FS.COMPANY_NAME, FS.REPORT_DATE;

