WITH NODENOVELTY AS ( SELECT TURN, AVG(NOVELTY_SCORE) AS AVG_NODE_NOVELTY FROM NODE_NOVELTY_SCORES WHERE NETWORK_ID = 0 GROUP BY TURN ), LINKNOVELTY AS ( SELECT TURN, AVG(NOVELTY_SCORE) AS AVG_LINK_NOVELTY FROM LINK_NOVELTY_SCORES WHERE NETWORK_ID = 0 GROUP BY TURN ), COMBINEDNOVELTY AS ( SELECT COALESCE(NN.TURN, LN.TURN) AS TURN, COALESCE(NN.AVG_NODE_NOVELTY, 0) AS AVG_NODE_NOVELTY, COALESCE(LN.AVG_LINK_NOVELTY, 0) AS AVG_LINK_NOVELTY, (COALESCE(NN.AVG_NODE_NOVELTY, 0) + COALESCE(LN.AVG_LINK_NOVELTY, 0)) AS TOTAL_NOVELTY FROM NODENOVELTY NN FULL OUTER JOIN LINKNOVELTY LN ON NN.TURN = LN.TURN ) SELECT MAX(TOTAL_NOVELTY) AS HIGHEST_TOTAL_NOVELTY FROM COMBINEDNOVELTY;
WITH NODESCORES AS ( SELECT NETWORK_ID, TURN, AVG(NOVELTY_SCORE) AS AVG_NODE_NOVELTY FROM NODE_NOVELTY_SCORES WHERE NETWORK_ID = 0 GROUP BY NETWORK_ID, TURN ), LINKSCORES AS ( SELECT NETWORK_ID, TURN, AVG(NOVELTY_SCORE) AS AVG_LINK_NOVELTY FROM LINK_NOVELTY_SCORES WHERE NETWORK_ID = 0 GROUP BY NETWORK_ID, TURN ) SELECT MAX(NS.AVG_NODE_NOVELTY + LS.AVG_LINK_NOVELTY) AS HIGHEST_COMBINED_NOVELTY_SCORE FROM NODESCORES NS JOIN LINKSCORES LS ON NS.NETWORK_ID = LS.NETWORK_ID AND NS.TURN = LS.TURN;

