    SELECT 
      SHOW_ID, 
      SUM(VIEWER_COUNT) AS TOTAL_VIEWER_COUNT
    FROM 
      VIEWERSHIP
    GROUP BY 
      SHOW_ID
  ),

  SHOWDETAILS AS (
    SELECT 
      S.SHOW_ID, 
      S.TITLE, 
      N.NETWORK_NAME
    FROM 
