SELECT P.NAME AS BASE_POKEMON_NAME, P2.NAME AS EVOLVED_POKEMON_NAME, PE.EVOLUTION_STAGE, PT1.TYPE_NAME AS ATTACKING_TYPE, PT2.TYPE_NAME AS DEFENDING_TYPE, TE.EFFECTIVENESS AS EFFECTIVENESS, U.USER_NAME AS ACCESSED_BY, AL.ACCESS_DATE FROM POKEMON_EVOLUTION PE JOIN POKEMONS P ON PE.BASE_POKEMON_ID = P.POKEMON_ID JOIN POKEMONS P2 ON PE.EVOLVED_POKEMON_ID = P2.POKEMON_ID JOIN TYPE_EFFECTIVENESS TE ON P.PRIMARY_TYPE_ID = TE.DEFENDING_TYPE_ID JOIN POKEMON_TYPES PT1 ON TE.ATTACKING_TYPE_ID = PT1.TYPE_ID JOIN POKEMON_TYPES PT2 ON TE.DEFENDING_TYPE_ID = PT2.TYPE_ID JOIN ACCESS_LOGS AL ON P.POKEMON_ID = AL.POKEMON_ID JOIN USERS U ON AL.USER_ID = U.USER_ID ORDER BY P.NAME, PE.EVOLUTION_STAGE, AL.ACCESS_DATE;
WITH BASEEVOLVEDPOKEMONS AS ( SELECT P1.POKEMON_ID AS BASE_POKEMON_ID, P2.POKEMON_ID AS EVOLVED_POKEMON_ID, P1.NAME AS BASE_POKEMON_NAME, P2.NAME AS EVOLVED_POKEMON_NAME, PE.EVOLUTION_STAGE FROM POKEMONS P1 INNER JOIN POKEMON_EVOLUTION PE ON P1.POKEMON_ID = PE.BASE_POKEMON_ID INNER JOIN POKEMONS P2 ON PE.EVOLVED_POKEMON_ID = P2.POKEMON_ID ), TYPEEFFECTIVENESS AS ( SELECT TE.ATTACKING_TYPE_ID, PT.TYPE_NAME AS ATTACKING_TYPE_NAME, TE.DEFENDING_TYPE_ID, PT2.TYPE_NAME AS DEFENDING_TYPE_NAME, TE.EFFECTIVENESS FROM TYPE_EFFECTIVENESS TE INNER JOIN POKEMON_TYPES PT ON TE.ATTACKING_TYPE_ID = PT.TYPE_ID INNER JOIN POKEMON_TYPES PT2 ON TE.DEFENDING_TYPE_ID = PT2.TYPE_ID ), POKÉMONACCESSLOGS AS ( SELECT P.POKEMON_ID, U.USER_NAME, AL.ACCESS_DATE FROM POKEMONS P INNER JOIN ACCESS_LOGS AL ON P.POKEMON_ID = AL.POKEMON_ID INNER JOIN USERS U ON AL.USER_ID = U.USER_ID ) SELECT B.BASE_POKEMON_NAME, B.EVOLVED_POKEMON_NAME, B.EVOLUTION_STAGE, TE.ATTACKING_TYPE_NAME, TE.DEFENDING_TYPE_NAME, TE.EFFECTIVENESS, PAL.USER_NAME, PAL.ACCESS_DATE FROM BASEEVOLVEDPOKEMONS B LEFT JOIN TYPEEFFECTIVENESS TE ON B.BASE_POKEMON_ID = TE.DEFENDING_TYPE_ID LEFT JOIN POKÉMONACCESSLOGS PAL ON B.BASE_POKEMON_ID = PAL.POKEMON_ID ORDER BY B.BASE_POKEMON_NAME, B.EVOLUTION_STAGE, PAL.ACCESS_DATE;

