WITH LATESTVERSIONS AS (
    SELECT
        C.COMPONENT_ID,
        C.DEVICE_NAME,
        C.DESCRIPTION,
        CV.VERSION
    FROM COMPONENTS C
    INNER JOIN COMPONENT_COMPONENT_TYPES CCT ON C.COMPONENT_ID = CCT.COMPONENT_ID
    INNER JOIN COMPONENT_TYPES CT ON CCT.TYPE_ID = CT.TYPE_ID
    INNER JOIN COMPONENT_VERSIONS CV ON C.COMPONENT_ID = CV.COMPONENT_ID
    WHERE CT.TYPE_NAME = 'OPERATIONAL AMPLIFIER'
    AND CV.VERSION = (
        SELECT MAX(VERSION)
        FROM COMPONENT_VERSIONS
        WHERE COMPONENT_ID = C.COMPONENT_ID
    )
)
SELECT
    DEVICE_NAME,
    DESCRIPTION
FROM LATESTVERSIONS
ORDER BY DEVICE_NAME, DESCRIPTION;
WITH LATESTVERSIONS AS ( SELECT COMPONENT_ID, MAX(VERSION) AS MAX_VERSION FROM COMPONENT_VERSIONS GROUP BY COMPONENT_ID ) SELECT C.DEVICE_NAME, C.DESCRIPTION FROM COMPONENTS C JOIN COMPONENT_VERSIONS CV ON C.COMPONENT_ID = CV.COMPONENT_ID JOIN LATESTVERSIONS LV ON C.COMPONENT_ID = LV.COMPONENT_ID AND CV.VERSION = LV.MAX_VERSION JOIN COMPONENT_COMPONENT_TYPES CCT ON C.COMPONENT_ID = CCT.COMPONENT_ID JOIN COMPONENT_TYPES CT ON CCT.TYPE_ID = CT.TYPE_ID WHERE CT.TYPE_NAME = 'OA' ORDER BY C.DEVICE_NAME, C.DESCRIPTION;

