WITH MUNICIPALITYVOTES AS ( SELECT M.MUNICIPALITY_ID, M.MUNICIPALITY_NAME, M.REGISTERED_VOTERS, R.VOTES, (R.VOTES * 1.0 / M.REGISTERED_VOTERS) * 100 AS VOTE_PERCENTAGE FROM MUNICIPALITIES M JOIN RESULTS R ON M.MUNICIPALITY_ID = R.MUNICIPALITY_ID WHERE M.REGISTERED_VOTERS > 0 ), TOPMUNICIPALITY AS ( SELECT MUNICIPALITY_ID, MUNICIPALITY_NAME, VOTE_PERCENTAGE FROM MUNICIPALITYVOTES ORDER BY VOTE_PERCENTAGE DESC LIMIT 1 ) SELECT COUNT(DISTINCT C.CANDIDATE_ID) AS CANDIDATE_COUNT_IN_TOP_MUNICIPALITY_DISTRICT FROM TOPMUNICIPALITY TM JOIN RESULTS R ON TM.MUNICIPALITY_ID = R.MUNICIPALITY_ID JOIN DISTRICTS D ON R.DISTRICT_ID = D.DISTRICT_ID JOIN CANDIDATES C ON D.DISTRICT_ID = C.DISTRICT_ID;
WITH HIGHEST_TURNOUT_MUNICIPALITY AS (
    SELECT R.DISTRICT_ID
    FROM MUNICIPALITIES M
    JOIN RESULTS R ON M.MUNICIPALITY_ID = R.MUNICIPALITY_ID
    WHERE M.REGISTERED_VOTERS >= 1
    ORDER BY R.PERCENTAGE DESC
    LIMIT 1
),
CANDIDATES_IN_HIGHEST_TURNOUT_DISTRICT AS (
    SELECT C.CANDIDATE_ID
    FROM CANDIDATES C
    WHERE C.DISTRICT_ID = (SELECT DISTRICT_ID FROM HIGHEST_TURNOUT_MUNICIPALITY)
)
SELECT COUNT(*) AS CANDIDATE_COUNT
FROM CANDIDATES_IN_HIGHEST_TURNOUT_DISTRICT;

