WITH FILTEREDQUESTIONS AS ( SELECT Q.DATA_POINT_ID, RT.RESPONSE_TIME FROM QUESTIONS Q JOIN ACCEPTED_ANSWERS AA ON Q.QUESTION_ID = AA.ANSWER_ID JOIN RESPONSE_TIMES RT ON Q.QUESTION_ID = RT.QUESTION_ID ), CATEGORYAVERAGERESPONSETIMES AS ( SELECT C.CATEGORY_NAME, AVG(FQ.RESPONSE_TIME) AS AVG_RESPONSE_TIME FROM FILTEREDQUESTIONS FQ JOIN DATA_POINTS DP ON FQ.DATA_POINT_ID = DP.ID JOIN CATEGORIES C ON DP.CATEGORY_ID = C.CATEGORY_ID GROUP BY C.CATEGORY_NAME ) SELECT CATEGORY_NAME, AVG_RESPONSE_TIME FROM CATEGORYAVERAGERESPONSETIMES ORDER BY AVG_RESPONSE_TIME DESC LIMIT 10;
WITH QAS AS ( SELECT Q.QUESTION_ID, Q.DATA_POINT_ID, AA.ACCEPTED_DATE FROM QUESTIONS Q INNER JOIN ANSWERS A ON Q.DATA_POINT_ID = A.DATA_POINT_ID INNER JOIN ACCEPTED_ANSWERS AA ON A.ANSWER_ID = AA.ANSWER_ID ), QASWITHRTS AS ( SELECT QAS.QUESTION_ID, QAS.DATA_POINT_ID, QAS.ACCEPTED_DATE, RT.RESPONSE_TIME FROM QAS QAS INNER JOIN RESPONSE_TIMES RT ON QAS.QUESTION_ID = RT.QUESTION_ID ), QASWITHRTSANDCATEGORIES AS ( SELECT QAWRTS.QUESTION_ID, QAWRTS.DATA_POINT_ID, QAWRTS.ACCEPTED_DATE, QAWRTS.RESPONSE_TIME, C.CATEGORY_NAME FROM QASWITHRTS QAWRTS INNER JOIN DATA_POINTS DP ON QAWRTS.DATA_POINT_ID = DP.ID INNER JOIN CATEGORIES C ON DP.CATEGORY_ID = C.CATEGORY_ID ), AVGRTSBYCATEGORY AS ( SELECT CATEGORY_NAME, AVG(RESPONSE_TIME) AS AVERAGE_RESPONSE_TIME FROM QASWITHRTSANDCATEGORIES GROUP BY CATEGORY_NAME ) SELECT CATEGORY_NAME, AVERAGE_RESPONSE_TIME FROM AVGRTSBYCATEGORY ORDER BY AVERAGE_RESPONSE_TIME DESC LIMIT 10;

