WITH PUBLIC_SECTOR_CONSUMPTION AS ( SELECT Y.YEAR_VALUE, TEC.TOTAL_CONSUMPTION FROM YEARS Y JOIN TOTAL_ENERGY_CONSUMPTION TEC ON TEC.YEAR_ID = Y.YEAR_ID JOIN ENERGY_CONSUMPTION EC ON EC.YEAR_ID = Y.YEAR_ID JOIN SECTORS S ON EC.SECTOR_ID = S.SECTOR_ID WHERE S.SECTOR_CATEGORY = 'PUBLIC' ) SELECT YEAR_VALUE, AVG(TOTAL_CONSUMPTION) AS AVERAGE_TOTAL_ENERGY_CONSUMPTION FROM PUBLIC_SECTOR_CONSUMPTION GROUP BY YEAR_VALUE HAVING AVG(TOTAL_CONSUMPTION) > 1000 ORDER BY YEAR_VALUE ASC;
WITH PUBLIC_SECTORS AS ( SELECT S.SECTOR_ID, S.SECTOR_NAME FROM SECTORS S WHERE S.SECTOR_CATEGORY = 'PUBLIC' ), AVERAGE_CONSUMPTION AS ( SELECT Y.YEAR_VALUE, AVG(TEC.TOTAL_CONSUMPTION) AS AVG_CONSUMPTION FROM YEARS Y JOIN TOTAL_ENERGY_CONSUMPTION TEC ON TEC.YEAR_ID = Y.YEAR_ID WHERE EXISTS ( SELECT 1 FROM ENERGY_CONSUMPTION EC JOIN PUBLIC_SECTORS PS ON PS.SECTOR_ID = EC.SECTOR_ID WHERE EC.YEAR_ID = Y.YEAR_ID ) GROUP BY Y.YEAR_VALUE ) SELECT AC.YEAR_VALUE, AC.AVG_CONSUMPTION AS AVERAGE_TOTAL_ENERGY_CONSUMPTION FROM AVERAGE_CONSUMPTION AC WHERE AC.AVG_CONSUMPTION > 1000 ORDER BY AC.YEAR_VALUE ASC;

