SELECT E.DEPARTMENT, SUM(CASE WHEN C.MENTAL_CONSEQUENCE = 'YES' THEN 1 ELSE 0 END) AS MENTAL_CONSEQUENCE_COUNT, SUM(CASE WHEN C.PHYSICAL_CONSEQUENCE = 'YES' THEN 1 ELSE 0 END) AS PHYSICAL_CONSEQUENCE_COUNT FROM EMPLOYEES E JOIN CONSEQUENCES C ON E.EMPLOYEE_ID = C.EMPLOYEE_ID GROUP BY E.DEPARTMENT ORDER BY E.DEPARTMENT;
WITH MENTAL_CONSEQUENCE_COUNTS AS ( SELECT E.DEPARTMENT, COUNT(*) AS MENTAL_CONSEQUENCE_COUNT FROM EMPLOYEES E JOIN CONSEQUENCES C ON E.EMPLOYEE_ID = C.EMPLOYEE_ID WHERE C.MENTAL_CONSEQUENCE = 'YES' GROUP BY E.DEPARTMENT ), PHYSICAL_CONSEQUENCE_COUNTS AS ( SELECT E.DEPARTMENT, COUNT(*) AS PHYSICAL_CONSEQUENCE_COUNT FROM EMPLOYEES E JOIN CONSEQUENCES C ON E.EMPLOYEE_ID = C.EMPLOYEE_ID WHERE C.PHYSICAL_CONSEQUENCE = 'YES' GROUP BY E.DEPARTMENT ) SELECT COALESCE(MC.DEPARTMENT, PC.DEPARTMENT) AS DEPARTMENT, COALESCE(MC.MENTAL_CONSEQUENCE_COUNT, 0) AS MENTAL_CONSEQUENCE_COUNT, COALESCE(PC.PHYSICAL_CONSEQUENCE_COUNT, 0) AS PHYSICAL_CONSEQUENCE_COUNT FROM MENTAL_CONSEQUENCE_COUNTS MC FULL OUTER JOIN PHYSICAL_CONSEQUENCE_COUNTS PC ON MC.DEPARTMENT = PC.DEPARTMENT ORDER BY DEPARTMENT;

