SELECT COUNT(*) AS UNIQUE_SKU_COUNT FROM ( SELECT DISTINCT P.SKU FROM PRODUCTS P JOIN INVENTORY_LEVELS I ON P.SKU = I.SKU JOIN WAREHOUSE_OPERATIONS W ON P.SKU = W.SKU WHERE P.CATEGORY = 'ELECTRONICS' AND I.QUANTITY > 50 GROUP BY P.SKU HAVING SUM(W.OPERATION_COST) > 1000 ) AS FILTERED_SKUS;
WITH ELECTRONICSINVENTORY AS ( SELECT I.SKU, I.QUANTITY FROM INVENTORY_LEVELS I JOIN PRODUCTS P ON I.SKU = P.SKU WHERE P.CATEGORY = 'ELECTRONICS' ), ELECTRONICSCOSTS AS ( SELECT P.SKU, SUM(W.OPERATION_COST) AS TOTAL_COST FROM WAREHOUSE_OPERATIONS W JOIN PRODUCTS P ON W.SKU = P.SKU WHERE P.CATEGORY = 'ELECTRONICS' GROUP BY P.SKU ) SELECT COUNT(DISTINCT EI.SKU) AS UNIQUE_SKU_COUNT FROM ELECTRONICSINVENTORY EI JOIN ELECTRONICSCOSTS EC ON EI.SKU = EC.SKU WHERE EC.TOTAL_COST > 1000 AND EI.QUANTITY > 50;

