WITH CAPTAINTEAMS AS ( SELECT TF.CAPTAIN_ID, TM.PARTICIPANT_ID AS TEAM_MEMBER_ID FROM TEAMS TF JOIN TEAM_MEMBERS TM ON TF.TEAM_ID = TM.TEAM_ID ), TEAMAVERAGESCORES AS ( SELECT CT.CAPTAIN_ID, AVG(S.SCORE) AS AVG_SCORE FROM CAPTAINTEAMS CT JOIN SCORES S ON CT.TEAM_MEMBER_ID = S.PARTICIPANT_ID GROUP BY CT.CAPTAIN_ID ), TOPTEAM AS ( SELECT CAPTAIN_ID FROM TEAMAVERAGESCORES ORDER BY AVG_SCORE DESC LIMIT 1 ), TOPSCORER AS ( SELECT S.PARTICIPANT_ID, MAX(S.SCORE) AS MAX_SCORE FROM SCORES S JOIN CAPTAINTEAMS CT ON S.PARTICIPANT_ID = CT.TEAM_MEMBER_ID WHERE CT.CAPTAIN_ID IN (SELECT CAPTAIN_ID FROM TOPTEAM) GROUP BY S.PARTICIPANT_ID ) SELECT P.NAME FROM PARTICIPANTS P JOIN TOPSCORER TS ON P.PARTICIPANT_ID = TS.PARTICIPANT_ID JOIN ( SELECT CAPTAIN_ID, TEAM_MEMBER_ID FROM CAPTAINTEAMS WHERE CAPTAIN_ID IN (SELECT CAPTAIN_ID FROM TOPTEAM) ) CT ON P.PARTICIPANT_ID = CT.TEAM_MEMBER_ID ORDER BY TS.MAX_SCORE DESC LIMIT 1;
