SELECT P.PRODUCT_ID, P.PRODUCT_NAME, PC.CATEGORY_NAME, SUM(PWM.QUANTITY) AS TOTAL_INVENTORY FROM PRODUCTS P JOIN PRODUCT_CATEGORY_MAPPING PCM ON P.PRODUCT_ID = PCM.PRODUCT_ID JOIN PRODUCT_CATEGORIES PC ON PCM.CATEGORY_ID = PC.CATEGORY_ID JOIN PRODUCT_WAREHOUSE_MAPPING PWM ON P.PRODUCT_ID = PWM.PRODUCT_ID WHERE PCM.IS_PRIMARY = 1 GROUP BY P.PRODUCT_ID, PC.CATEGORY_NAME;
WITH PRODUCTCATEGORIES AS (
    SELECT PCM.PRODUCT_ID, PCM.CATEGORY_ID, PCM.IS_PRIMARY, PC.CATEGORY_NAME
    FROM PRODUCT_CATEGORY_MAPPING PCM
    INNER JOIN PRODUCT_CATEGORIES PC ON PCM.CATEGORY_ID = PC.CATEGORY_ID
    WHERE PCM.IS_PRIMARY = 1
),
PRODUCTINVENTORY AS (
    SELECT PWM.PRODUCT_ID, SUM(PWM.QUANTITY) AS TOTAL_INVENTORY
    FROM PRODUCT_WAREHOUSE_MAPPING PWM
    GROUP BY PWM.PRODUCT_ID
)
SELECT 
    P.PRODUCT_ID,
    P.PRODUCT_NAME,
    PC.CATEGORY_NAME,
    PI.TOTAL_INVENTORY
FROM PRODUCTS P
INNER JOIN PRODUCTCATEGORIES PC ON P.PRODUCT_ID = PC.PRODUCT_ID
INNER JOIN PRODUCTINVENTORY PI ON P.PRODUCT_ID = PI.PRODUCT_ID;

