SELECT A.CITY, AVG(G.ACCURACY) AS AVG_ACCURACY, COUNT(E.ERROR_REPORT_ID) AS TOTAL_ERRORS FROM ADDRESSES A JOIN GEOLOCATION_DATA G ON A.ADDRESS_ID = G.ADDRESS_ID JOIN ADDRESS_QUALITY_METRICS Q ON A.ADDRESS_ID = Q.ADDRESS_ID LEFT JOIN ADDRESS_ERROR_REPORTS E ON A.ADDRESS_ID = E.ADDRESS_ID WHERE Q.IS_VERIFIED = 1 GROUP BY A.CITY ORDER BY AVG_ACCURACY DESC, TOTAL_ERRORS DESC;
WITH VERIFIEDADDRESSES AS ( SELECT A.ADDRESS_ID, A.CITY FROM ADDRESSES A INNER JOIN ADDRESS_QUALITY_METRICS AQ ON A.ADDRESS_ID = AQ.ADDRESS_ID WHERE AQ.IS_VERIFIED = 1 ), CITYACCURACY AS ( SELECT VA.CITY, AVG(GD.ACCURACY) AS AVG_ACCURACY FROM VERIFIEDADDRESSES VA INNER JOIN GEOLOCATION_DATA GD ON VA.ADDRESS_ID = GD.ADDRESS_ID GROUP BY VA.CITY ), CITYERRORS AS ( SELECT A.CITY, COUNT(AE.ERROR_REPORT_ID) AS TOTAL_ERRORS FROM ADDRESSES A INNER JOIN ADDRESS_ERROR_REPORTS AE ON A.ADDRESS_ID = AE.ADDRESS_ID INNER JOIN ADDRESS_QUALITY_METRICS AQ ON A.ADDRESS_ID = AQ.ADDRESS_ID WHERE AQ.IS_VERIFIED = 1 GROUP BY A.CITY ), COMBINEDDATA AS ( SELECT CA.CITY, CA.AVG_ACCURACY, COALESCE(CE.TOTAL_ERRORS, 0) AS TOTAL_ERRORS FROM CITYACCURACY CA LEFT JOIN CITYERRORS CE ON CA.CITY = CE.CITY ) SELECT CITY, AVG_ACCURACY, TOTAL_ERRORS FROM COMBINEDDATA ORDER BY AVG_ACCURACY DESC, TOTAL_ERRORS DESC;

