SELECT E.EXPERIMENT_NAME, P.GENDER, AVG(R.RESPONSE_TIME) AS AVG_EXPERIMENT_TIME, SUM(CASE WHEN R.ACCURACY = 1 THEN 1 ELSE 0 END) / COUNT(CASE WHEN R.ACCURACY IS NOT NULL THEN R.RESPONSE_ID ELSE NULL END) AS AVG_ACCURACY_RATE FROM EXPERIMENTS E JOIN TRIALS T ON E.EXPERIMENT_ID = T.EXPERIMENT_ID JOIN RESPONSES R ON T.TRIAL_ID = R.TRIAL_ID JOIN PARTICIPANTS P ON R.PARTICIPANT_ID = P.PARTICIPANT_ID GROUP BY E.EXPERIMENT_NAME, P.GENDER;
WITH EXPERIMENTTIMES AS ( SELECT T.EXPERIMENT_ID, R.PARTICIPANT_ID, SUM(R.RESPONSE_TIME) AS TOTAL_EXPERIMENT_TIME FROM TRIALS T INNER JOIN RESPONSES R ON T.TRIAL_ID = R.TRIAL_ID GROUP BY T.EXPERIMENT_ID, R.PARTICIPANT_ID ), ACCURACYRATES AS ( SELECT T.EXPERIMENT_ID, R.PARTICIPANT_ID, AVG(R.ACCURACY) AS ACCURACY_RATE FROM TRIALS T INNER JOIN RESPONSES R ON T.TRIAL_ID = R.TRIAL_ID GROUP BY T.EXPERIMENT_ID, R.PARTICIPANT_ID ), PARTICIPANTCOUNTS AS ( SELECT E.EXPERIMENT_ID, E.EXPERIMENT_NAME, P.GENDER, COUNT(DISTINCT P.PARTICIPANT_ID) AS PARTICIPANT_COUNT FROM EXPERIMENTS E INNER JOIN TRIALS T ON E.EXPERIMENT_ID = T.EXPERIMENT_ID INNER JOIN RESPONSES R ON T.TRIAL_ID = R.TRIAL_ID INNER JOIN PARTICIPANTS P ON R.PARTICIPANT_ID = P.PARTICIPANT_ID GROUP BY E.EXPERIMENT_ID, E.EXPERIMENT_NAME, P.GENDER ) SELECT PC.EXPERIMENT_NAME, PC.GENDER, AVG(ET.TOTAL_EXPERIMENT_TIME) / PC.PARTICIPANT_COUNT AS AVERAGE_EXPERIMENT_TIME, AVG(AR.ACCURACY_RATE) AS AVERAGE_ACCURACY_RATE FROM PARTICIPANTCOUNTS PC INNER JOIN EXPERIMENTTIMES ET ON PC.EXPERIMENT_ID = ET.EXPERIMENT_ID INNER JOIN ACCURACYRATES AR ON PC.EXPERIMENT_ID = AR.EXPERIMENT_ID AND PC.GENDER = ( SELECT P.GENDER FROM PARTICIPANTS P WHERE P.PARTICIPANT_ID = AR.PARTICIPANT_ID ) GROUP BY PC.EXPERIMENT_NAME, PC.GENDER ORDER BY PC.EXPERIMENT_NAME, PC.GENDER;

