  SELECT 
    T.USER_ID, 
    COUNT(DISTINCT TH.HASHTAG_ID) AS HASHTAG_COUNT
  FROM 
    TWEETS T
  JOIN 
    TWEET_HASHTAGS TH ON T.TWEET_ID = TH.TWEET_ID
  GROUP BY 
    T.USER_ID
)

SELECT 
  U.USER_NAME, 
  UHC.HASHTAG_COUNT
FROM 
  USERHASHTAGCOUNT UHC
JOIN 
  USERS U ON UHC.USER_ID = U.USER_ID
ORDER BY 
  UHC.HASHTAG_COUNT DESC
LIMIT 5;

