SELECT E.DESCRIPTION AS EXPERIMENT_DESCRIPTION, M.MODEL_NAME AS MODEL_NAME FROM EXPERIMENTS E INNER JOIN MODELS M ON E.MODEL_ID = M.MODEL_ID INNER JOIN HYPERPARAMETERS HP ON E.EXPERIMENT_ID = HP.EXPERIMENT_ID INNER JOIN RESULTS R ON HP.HYPERPARAMETER_ID = R.HYPERPARAMETER_ID INNER JOIN DATA_AUGMENTATION_RESULTS DAR ON R.RESULT_ID = DAR.RESULT_ID INNER JOIN RESULTS_USER RU ON R.RESULT_ID = RU.RESULT_ID INNER JOIN EXPERIMENT_USER EU ON E.EXPERIMENT_ID = EU.EXPERIMENT_ID WHERE E.EXPERIMENT_ID = 1 AND DAR.THRESHOLD_MAX_AUGMENTATION > 0.6 AND R.HIGHEST_VAL_ACC > 0.7 AND EU.ROLE = 'OWNER' AND RU.ROLE = 'COLLABORATOR' ORDER BY R.HIGHEST_VAL_ACC DESC;
SELECT E.DESCRIPTION, M.MODEL_NAME FROM EXPERIMENTS E JOIN MODELS M ON E.MODEL_ID = M.MODEL_ID JOIN EXPERIMENT_USER EU ON E.EXPERIMENT_ID = EU.EXPERIMENT_ID JOIN USERS U1 ON EU.USER_ID = U1.USER_ID JOIN HYPERPARAMETERS H ON E.EXPERIMENT_ID = H.EXPERIMENT_ID JOIN RESULTS R ON H.HYPERPARAMETER_ID = R.HYPERPARAMETER_ID LEFT JOIN DATA_AUGMENTATION_RESULTS DAR ON R.RESULT_ID = DAR.RESULT_ID JOIN RESULTS_USER RU ON R.RESULT_ID = RU.RESULT_ID JOIN USERS U2 ON RU.USER_ID = U2.USER_ID WHERE E.EXPERIMENT_ID = 1 AND DAR.THRESHOLD_MAX_AUGMENTATION > 0.6 AND R.HIGHEST_VAL_ACC > 0.7 AND EU.ROLE = 'OWNER' AND RU.ROLE = 'COLLABORATOR' ORDER BY R.HIGHEST_VAL_ACC DESC;

