WITH MARKETDATA2022 AS ( SELECT SYMBOL, AVG(CLOSE) AS AVG_CLOSE, MAX(DATA_QUALITY_SCORE) AS MAX_QUALITY_SCORE FROM MARKET_DATA WHERE DATE BETWEEN '2022-01-01' AND '2022-12-31' GROUP BY SYMBOL ), FILTEREDINSTRUMENTS AS ( SELECT MD2022.SYMBOL, MD2022.AVG_CLOSE, FI.NAME FROM MARKETDATA2022 MD2022 JOIN FINANCIAL_INSTRUMENTS FI ON MD2022.SYMBOL = FI.SYMBOL WHERE MD2022.MAX_QUALITY_SCORE > 0.9 ), RANKEDINSTRUMENTS AS ( SELECT FI.NAME, AVG(MD.AVG_CLOSE) AS AVG_CLOSE FROM FILTEREDINSTRUMENTS FI JOIN MARKETDATA2022 MD ON FI.SYMBOL = MD.SYMBOL GROUP BY FI.NAME ORDER BY AVG_CLOSE DESC LIMIT 10 ) SELECT NAME FROM RANKEDINSTRUMENTS;

