WITH OPENMATTERS AS ( SELECT M.MATTER_ID, M.FIRM_NAME, M.MATTER_TYPE, M.CLIENT_ID, M.MATTER_DESCRIPTION FROM MATTERS M JOIN INVOICES I ON M.MATTER_ID = I.MATTER_ID WHERE M.MATTER_STATUS = 'OPEN' AND I.INVOICE_STATUS = 'UNPAID' ), MATTERCOST AS ( SELECT I.MATTER_ID, SUM(I.TOTAL) AS TOTAL_MATTER_COST FROM INVOICES I GROUP BY I.MATTER_ID ), MATTERHOURS AS ( SELECT A.MATTER_ID, SUM(A.ACTIVITY_DURATION / 60.0) AS TOTAL_HOURS FROM ACTIVITIES A GROUP BY A.MATTER_ID ) SELECT OM.MATTER_ID, OM.FIRM_NAME, OM.MATTER_TYPE, OM.CLIENT_ID, OM.MATTER_DESCRIPTION, MC.TOTAL_MATTER_COST, MH.TOTAL_HOURS, (MC.TOTAL_MATTER_COST * MH.TOTAL_HOURS) AS TOTAL_COST FROM OPENMATTERS OM JOIN MATTERCOST MC ON OM.MATTER_ID = MC.MATTER_ID JOIN MATTERHOURS MH ON OM.MATTER_ID = MH.MATTER_ID;
WITH OPENMATTERS AS ( SELECT M.MATTER_ID, M.FIRM_NAME, M.MATTER_TYPE, M.CLIENT_ID, M.MATTER_DESCRIPTION FROM MATTERS M JOIN INVOICES I ON M.MATTER_ID = I.MATTER_ID WHERE M.MATTER_STATUS = 'OPEN' AND I.INVOICE_STATUS = 'UNPAID' ), MATTERTOTALS AS ( SELECT A.MATTER_ID, SUM(A.ACTIVITY_DURATION / 60.0) AS TOTAL_HOURS, SUM(I.TOTAL) AS TOTAL_MATTER_COST FROM ACTIVITIES A JOIN INVOICES I ON A.MATTER_ID = I.MATTER_ID GROUP BY A.MATTER_ID ) SELECT OM.MATTER_ID, OM.FIRM_NAME, OM.MATTER_TYPE, OM.CLIENT_ID, OM.MATTER_DESCRIPTION, MT.TOTAL_MATTER_COST, MT.TOTAL_HOURS, MT.TOTAL_MATTER_COST * MT.TOTAL_HOURS AS TOTAL_COST FROM OPENMATTERS OM JOIN MATTERTOTALS MT ON OM.MATTER_ID = MT.MATTER_ID;

