SELECT MAX(T.TOTAL_NOVELTY) FROM ( SELECT COALESCE(N.TURN, L.TURN) AS TURN, COALESCE(N.AVG_NODE_SCORE, 0) + COALESCE(L.AVG_LINK_SCORE, 0) AS TOTAL_NOVELTY FROM ( SELECT TURN, AVG(NOVELTY_SCORE) AS AVG_NODE_SCORE FROM NODE_NOVELTY_SCORES WHERE NETWORK_ID = 0 GROUP BY TURN ) N FULL OUTER JOIN ( SELECT TURN, AVG(NOVELTY_SCORE) AS AVG_LINK_SCORE FROM LINK_NOVELTY_SCORES WHERE NETWORK_ID = 0 GROUP BY TURN ) L ON N.TURN = L.TURN WHERE N.TURN IS NOT NULL OR L.TURN IS NOT NULL ) T;
WITH NODEAVERAGES AS ( SELECT TURN, AVG(NOVELTY_SCORE) AS NODE_AVG_SCORE FROM NODE_NOVELTY_SCORES WHERE NETWORK_ID = 0 GROUP BY TURN ), LINKAVERAGES AS ( SELECT TURN, AVG(NOVELTY_SCORE) AS LINK_AVG_SCORE FROM LINK_NOVELTY_SCORES WHERE NETWORK_ID = 0 GROUP BY TURN ), COMBINEDAVERAGES AS ( SELECT COALESCE(NA.TURN, LA.TURN) AS TURN, COALESCE(NA.NODE_AVG_SCORE, 0) + COALESCE(LA.LINK_AVG_SCORE, 0) AS COMBINED_AVG_SCORE FROM NODEAVERAGES NA FULL OUTER JOIN LINKAVERAGES LA ON NA.TURN = LA.TURN ) SELECT MAX(COMBINED_AVG_SCORE) FROM COMBINEDAVERAGES;

