WITH SENSORDATA AS ( SELECT L.LOCATION_NAME, AVG(ED.PM_2_5_LEVEL) AS AVG_PM_2_5, AVG(ED.TEMPERATURE_K) AS AVG_TEMPERATURE_K, AVG(ED.HUMIDITY) AS AVG_HUMIDITY FROM ENVIRONMENTAL_DATA ED JOIN SENSORS S ON ED.SENSOR_ID = S.SENSOR_ID JOIN LOCATIONS L ON S.LOCATION_ID = L.LOCATION_ID WHERE ED.TIMESTAMP >= '2016-01-01' AND ED.TIMESTAMP < '2016-02-01' GROUP BY L.LOCATION_NAME ), ALERTSSUMMARY AS ( SELECT L.LOCATION_NAME, COUNT(A.ALERT_ID) AS UNRESOLVED_ALERTS FROM ALERTS A JOIN ENVIRONMENTAL_DATA ED ON A.DATA_ID = ED.DATA_ID JOIN SENSORS S ON ED.SENSOR_ID = S.SENSOR_ID JOIN LOCATIONS L ON S.LOCATION_ID = L.LOCATION_ID WHERE A.RESOLVED = 0 AND A.ALERT_TIMESTAMP >= '2016-01-01' AND A.ALERT_TIMESTAMP < '2016-02-01' GROUP BY L.LOCATION_NAME ), MAINTENANCESUMMARY AS ( SELECT L.LOCATION_NAME, MAX(SM.MAINTENANCE_DATE) AS LAST_MAINTENANCE_DATE FROM SENSOR_MAINTENANCE SM JOIN SENSORS S ON SM.SENSOR_ID = S.SENSOR_ID JOIN LOCATIONS L ON S.LOCATION_ID = L.LOCATION_ID WHERE SM.MAINTENANCE_DATE >= '2016-01-01' AND SM.MAINTENANCE_DATE < '2016-02-01' GROUP BY L.LOCATION_NAME ) SELECT SD.LOCATION_NAME, SD.AVG_PM_2_5, SD.AVG_TEMPERATURE_K, SD.AVG_HUMIDITY, COALESCE(ASUM.UNRESOLVED_ALERTS, 0) AS UNRESOLVED_ALERTS, COALESCE(MSUM.LAST_MAINTENANCE_DATE, 'NO MAINTENANCE') AS LAST_MAINTENANCE_DATE FROM SENSORDATA SD LEFT JOIN ALERTSSUMMARY ASUM ON SD.LOCATION_NAME = ASUM.LOCATION_NAME LEFT JOIN MAINTENANCESUMMARY MSUM ON SD.LOCATION_NAME = MSUM.LOCATION_NAME ORDER BY SD.AVG_PM_2_5 DESC LIMIT 10;
WITH TOPLOCATIONS AS ( SELECT L.LOCATION_ID, L.LOCATION_NAME, AVG(ED.PM_2_5_LEVEL) AS AVG_PM_2_5, AVG(ED.TEMPERATURE_K) AS AVG_TEMPERATURE_K, AVG(ED.HUMIDITY) AS AVG_HUMIDITY FROM ENVIRONMENTAL_DATA ED JOIN SENSORS S ON ED.SENSOR_ID = S.SENSOR_ID JOIN LOCATIONS L ON S.LOCATION_ID = L.LOCATION_ID WHERE ED.TIMESTAMP BETWEEN '2016-01-01' AND '2016-01-31' GROUP BY L.LOCATION_ID, L.LOCATION_NAME ORDER BY AVG_PM_2_5 DESC LIMIT 10 ), ALERTCOUNTS AS ( SELECT L.LOCATION_ID, COUNT(A.ALERT_ID) AS UNRESOLVED_ALERTS FROM ALERTS A JOIN ENVIRONMENTAL_DATA ED ON A.DATA_ID = ED.DATA_ID JOIN SENSORS S ON ED.SENSOR_ID = S.SENSOR_ID JOIN LOCATIONS L ON S.LOCATION_ID = L.LOCATION_ID WHERE A.RESOLVED = 0 AND ED.TIMESTAMP BETWEEN '2016-01-01' AND '2016-01-31' GROUP BY L.LOCATION_ID ), MAINTENANCEDATES AS ( SELECT L.LOCATION_ID, MAX(SM.MAINTENANCE_DATE) AS LAST_MAINTENANCE FROM SENSOR_MAINTENANCE SM JOIN SENSORS S ON SM.SENSOR_ID = S.SENSOR_ID JOIN LOCATIONS L ON S.LOCATION_ID = L.LOCATION_ID GROUP BY L.LOCATION_ID ) SELECT TL.LOCATION_NAME, TL.AVG_PM_2_5, TL.AVG_TEMPERATURE_K, TL.AVG_HUMIDITY, COALESCE(AC.UNRESOLVED_ALERTS, 0) AS UNRESOLVED_ALERTS, MD.LAST_MAINTENANCE FROM TOPLOCATIONS TL LEFT JOIN ALERTCOUNTS AC ON TL.LOCATION_ID = AC.LOCATION_ID LEFT JOIN MAINTENANCEDATES MD ON TL.LOCATION_ID = MD.LOCATION_ID ORDER BY TL.AVG_PM_2_5 DESC;

