WITH EVALUATIONSCORES AS ( SELECT TECH_ID, SUM(WEIGHTED_SUM) AS TOTAL_WEIGHTED_SUM, SUM(SCORE) AS TOTAL_SCORE FROM EVALUATION_RESULTS GROUP BY TECH_ID ), FINALSCORECALCULATIONS AS ( SELECT TECH_ID, (TOTAL_WEIGHTED_SUM / TOTAL_SCORE) * 100 AS FINAL_SCORE FROM EVALUATIONSCORES ) SELECT T.TECH_ID, T.TECH_NAME, T.CATEGORY_ID, T.COMPANY_ID, FSC.FINAL_SCORE FROM TECHNOLOGIES T JOIN FINALSCORECALCULATIONS FSC ON T.TECH_ID = FSC.TECH_ID ORDER BY FSC.FINAL_SCORE DESC;
WITH TOTALSCORES AS ( SELECT TECH_ID, SUM(SCORE) AS TOTAL_SCORE FROM EVALUATION_RESULTS GROUP BY TECH_ID ), WEIGHTEDSCORES AS ( SELECT T.TECH_ID, SUM(IW.WEIGHT * IRS.SCORE) AS TOTAL_WEIGHTED_SCORE FROM TECHNOLOGIES T JOIN IR_SCORES IRS ON T.TECH_ID = IRS.TECH_ID JOIN IR_WEIGHTS IW ON IRS.IR_ID = IW.IR_ID GROUP BY T.TECH_ID ), FINALSCORES AS ( SELECT TS.TECH_ID, TS.TOTAL_SCORE, WS.TOTAL_WEIGHTED_SCORE, (WS.TOTAL_WEIGHTED_SCORE / TS.TOTAL_SCORE) * 100 AS FINAL_SCORE FROM TOTALSCORES TS JOIN WEIGHTEDSCORES WS ON TS.TECH_ID = WS.TECH_ID ) SELECT T.TECH_NAME, T.TECH_ID, T.CATEGORY_ID, T.COMPANY_ID, FS.FINAL_SCORE FROM TECHNOLOGIES T JOIN FINALSCORES FS ON T.TECH_ID = FS.TECH_ID ORDER BY FS.FINAL_SCORE DESC;

