SELECT T.TOURNAMENT_ID, P.PLAYER_ID, P.PLAYER_NAME, SUM(R.TOTAL) AS TOTAL_SCORE FROM TOURNAMENTS T JOIN PAIRS PA ON T.TOURNAMENT_ID = PA.TOURNAMENT_ID JOIN PLAYERS P ON (P.PLAYER_ID = PA.PLAYER1_ID OR P.PLAYER_ID = PA.PLAYER2_ID) JOIN RESULTS R ON R.PAIR_ID = PA.PAIR_ID GROUP BY T.TOURNAMENT_ID, P.PLAYER_ID, P.PLAYER_NAME ORDER BY T.TOURNAMENT_ID, P.PLAYER_ID;
WITH PLAYER_TOURNAMENT_SCORES AS ( SELECT R.TOURNAMENT_ID, PA.PLAYER1_ID AS PLAYER_ID, P.PLAYER_NAME, R.TOTAL FROM RESULTS R JOIN PAIRS PA ON R.PAIR_ID = PA.PAIR_ID JOIN PLAYERS P ON P.PLAYER_ID = PA.PLAYER1_ID UNION ALL SELECT R.TOURNAMENT_ID, PA.PLAYER2_ID AS PLAYER_ID, P.PLAYER_NAME, R.TOTAL FROM RESULTS R JOIN PAIRS PA ON R.PAIR_ID = PA.PAIR_ID JOIN PLAYERS P ON P.PLAYER_ID = PA.PLAYER2_ID ) SELECT TOURNAMENT_ID, PLAYER_ID, PLAYER_NAME, SUM(TOTAL) AS TOTAL_SCORE FROM PLAYER_TOURNAMENT_SCORES GROUP BY TOURNAMENT_ID, PLAYER_ID, PLAYER_NAME;

