SELECT WS.STATION_ID, WS.STATION_NAME, (COUNT(CASE WHEN T.TEMPERATURE_NAME = 'HOT' THEN 1 END) * 100.0 / COUNT(*)) AS HOT_PERCENTAGE, (COUNT(CASE WHEN T.TEMPERATURE_NAME = 'MILD' THEN 1 END) * 100.0 / COUNT(*)) AS MILD_PERCENTAGE, (COUNT(CASE WHEN T.TEMPERATURE_NAME = 'COOL' THEN 1 END) * 100.0 / COUNT(*)) AS COOL_PERCENTAGE FROM WEATHER_STATIONS WS INNER JOIN WEATHER_DATA WD ON WS.STATION_ID = WD.STATION_ID INNER JOIN TEMPERATURES T ON WD.TEMPERATURE = T.TEMPERATURE_NAME GROUP BY WS.STATION_ID, WS.STATION_NAME ORDER BY HOT_PERCENTAGE DESC;
WITH TEMPERATURECOUNTS AS ( SELECT WD.STATION_ID, COUNT(CASE WHEN WD.TEMPERATURE = 'HOT' THEN 1 END) AS HOT_COUNT, COUNT(CASE WHEN WD.TEMPERATURE = 'MILD' THEN 1 END) AS MILD_COUNT, COUNT(CASE WHEN WD.TEMPERATURE = 'COOL' THEN 1 END) AS COOL_COUNT, COUNT(*) AS TOTAL_COUNT FROM WEATHER_DATA WD GROUP BY WD.STATION_ID ), STATIONTEMPERATURES AS ( SELECT TC.STATION_ID, WS.STATION_NAME, (TC.HOT_COUNT * 1.0 / TC.TOTAL_COUNT) AS PERCENT_HOT, (TC.MILD_COUNT * 1.0 / TC.TOTAL_COUNT) AS PERCENT_MILD, (TC.COOL_COUNT * 1.0 / TC.TOTAL_COUNT) AS PERCENT_COOL FROM TEMPERATURECOUNTS TC JOIN WEATHER_STATIONS WS ON TC.STATION_ID = WS.STATION_ID ) SELECT ST.STATION_ID, ST.STATION_NAME, ST.PERCENT_HOT, ST.PERCENT_MILD, ST.PERCENT_COOL FROM STATIONTEMPERATURES ST ORDER BY ST.PERCENT_HOT DESC;

