SELECT
    M.MODEL_NAME,
    COUNT(TS.SESSION_ID) AS SESSION_COUNT,
    AVG(TS.TRAINING_DURATION) AS AVG_TRAINING_DURATION,
    AVG(PL.ROC_AUC) AS AVG_AUC,
    AVG(PL.ACCURACY) AS AVG_ACCURACY
FROM
    MODELS M
JOIN
    TRAINING_SESSIONS TS ON M.MODEL_ID = TS.MODEL_ID
JOIN
    PERFORMANCE_LOGS PL ON TS.SESSION_ID = PL.SESSION_ID
GROUP BY
    M.MODEL_ID, M.MODEL_NAME
ORDER BY
    M.MODEL_NAME;
WITH MODEL_TRAINING_STATS AS ( SELECT M.MODEL_ID, M.MODEL_NAME, COUNT(TS.SESSION_ID) AS SESSION_COUNT, AVG(TS.TRAINING_DURATION) AS AVG_TRAINING_DURATION FROM MODELS M JOIN TRAINING_SESSIONS TS ON M.MODEL_ID = TS.MODEL_ID GROUP BY M.MODEL_ID, M.MODEL_NAME ), PERFORMANCE_AVERAGES AS ( SELECT TS.MODEL_ID, AVG(PL.ROC_AUC) AS AVG_AUC, AVG(PL.ACCURACY) AS AVG_ACCURACY FROM TRAINING_SESSIONS TS JOIN PERFORMANCE_LOGS PL ON TS.SESSION_ID = PL.SESSION_ID GROUP BY TS.MODEL_ID ) SELECT MTS.MODEL_NAME, MTS.SESSION_COUNT, MTS.AVG_TRAINING_DURATION, PA.AVG_AUC, PA.AVG_ACCURACY FROM MODEL_TRAINING_STATS MTS JOIN PERFORMANCE_AVERAGES PA ON MTS.MODEL_ID = PA.MODEL_ID ORDER BY MTS.MODEL_NAME;

