WITH PRODUCTREVENUE AS ( SELECT PRODUCT_ID, SUM(REVENUE) AS TOTAL_REVENUE FROM SALES_ANALYTICS GROUP BY PRODUCT_ID ), PRODUCTSHIPPING AS ( SELECT PRODUCT_ID, SUM(SHIPPING_COST) AS TOTAL_SHIPPING_COST FROM ORDER_SHIPPING OSH INNER JOIN ORDER_ITEMS OI ON OSH.ORDER_ID = OI.ORDER_ID GROUP BY PRODUCT_ID ) SELECT PR.PRODUCT_ID, PR.TOTAL_REVENUE, PS.TOTAL_SHIPPING_COST, (PR.TOTAL_REVENUE - PS.TOTAL_SHIPPING_COST) AS NET_REVENUE FROM PRODUCTREVENUE PR INNER JOIN PRODUCTSHIPPING PS ON PR.PRODUCT_ID = PS.PRODUCT_ID ORDER BY PR.PRODUCT_ID;
WITH PRODUCTREVENUE AS ( SELECT SA.PRODUCT_ID, SUM(SA.REVENUE) AS TOTAL_REVENUE FROM SALES_ANALYTICS SA GROUP BY SA.PRODUCT_ID ), SHIPPINGCOSTBYPRODUCT AS ( SELECT OI.PRODUCT_ID, SUM(OS.SHIPPING_COST) AS TOTAL_SHIPPING_COST FROM ORDER_SHIPPING OS JOIN ORDER_ITEMS OI ON OS.ORDER_ID = OI.ORDER_ID GROUP BY OI.PRODUCT_ID ) SELECT PR.PRODUCT_ID, PR.TOTAL_REVENUE, IFNULL(SC.TOTAL_SHIPPING_COST, 0) AS TOTAL_SHIPPING_COST, PR.TOTAL_REVENUE - IFNULL(SC.TOTAL_SHIPPING_COST, 0) AS NET_REVENUE FROM PRODUCTREVENUE PR LEFT JOIN SHIPPINGCOSTBYPRODUCT SC ON PR.PRODUCT_ID = SC.PRODUCT_ID ORDER BY PR.PRODUCT_ID;

