SELECT ATHLETES.NAME, (SELECT COUNT(*) FROM PERFORMANCES WHERE PERFORMANCES.ATHLETE_ID = ATHLETES.ATHLETE_ID) + (SELECT COUNT(*) FROM IMPROVEMENTS WHERE IMPROVEMENTS.ATHLETE_ID = ATHLETES.ATHLETE_ID) AS TOTAL_ACTIVITIES, (SELECT AVG(PERFORMANCE_VALUE) FROM PERFORMANCES WHERE PERFORMANCES.ATHLETE_ID = ATHLETES.ATHLETE_ID) - (SELECT AVG(IMPROVEMENT_VALUE) FROM IMPROVEMENTS WHERE IMPROVEMENTS.ATHLETE_ID = ATHLETES.ATHLETE_ID) AS NET_PERFORMANCE FROM ATHLETES ORDER BY TOTAL_ACTIVITIES DESC, NET_PERFORMANCE DESC;
WITH ACTIVITYCOUNTS AS ( SELECT A.ATHLETE_ID, A.NAME, COUNT(P.PERFORMANCE_ID) AS PERFORMANCE_COUNT, COUNT(I.IMPROVEMENT_ID) AS IMPROVEMENT_COUNT FROM ATHLETES A LEFT JOIN PERFORMANCES P ON A.ATHLETE_ID = P.ATHLETE_ID LEFT JOIN IMPROVEMENTS I ON A.ATHLETE_ID = I.ATHLETE_ID GROUP BY A.ATHLETE_ID, A.NAME ), PERFORMANCEAVERAGES AS ( SELECT A.ATHLETE_ID, AVG(P.PERFORMANCE_VALUE) AS AVG_PERFORMANCE FROM ATHLETES A LEFT JOIN PERFORMANCES P ON A.ATHLETE_ID = P.ATHLETE_ID GROUP BY A.ATHLETE_ID ), IMPROVEMENTAVERAGES AS ( SELECT A.ATHLETE_ID, AVG(I.IMPROVEMENT_VALUE) AS AVG_IMPROVEMENT FROM ATHLETES A LEFT JOIN IMPROVEMENTS I ON A.ATHLETE_ID = I.ATHLETE_ID GROUP BY A.ATHLETE_ID ), TOTALACTIVITIES AS ( SELECT AC.ATHLETE_ID, AC.NAME, AC.PERFORMANCE_COUNT + AC.IMPROVEMENT_COUNT AS TOTAL_ACTIVITIES, COALESCE(PA.AVG_PERFORMANCE, 0) AS AVG_PERFORMANCE, COALESCE(IA.AVG_IMPROVEMENT, 0) AS AVG_IMPROVEMENT FROM ACTIVITYCOUNTS AC LEFT JOIN PERFORMANCEAVERAGES PA ON AC.ATHLETE_ID = PA.ATHLETE_ID LEFT JOIN IMPROVEMENTAVERAGES IA ON AC.ATHLETE_ID = IA.ATHLETE_ID ) SELECT NAME, TOTAL_ACTIVITIES, (AVG_PERFORMANCE - AVG_IMPROVEMENT) AS NET_PERFORMANCE FROM TOTALACTIVITIES ORDER BY TOTAL_ACTIVITIES DESC, NET_PERFORMANCE DESC;

