SELECT P.PRODUCT_ID, P.PRODUCT_NAME, P.MODEL, P.PRICE, P.STATUS, P.EAN_UPC, P.SKU, C.CATEGORY_NAME, S.SUPPLIER_NAME, SP.SUPPLY_PRICE, SP.LEAD_TIME, SUM(WS.QUANTITY) AS TOTAL_QUANTITY, MAX(WS.LAST_UPDATED) AS LAST_UPDATED FROM PRODUCTS P INNER JOIN CATEGORIES C ON P.CATEGORY_ID = C.CATEGORY_ID INNER JOIN SUPPLIERS S ON P.SUPPLIER_ID = S.SUPPLIER_ID LEFT JOIN SUPPLIER_PRODUCTS SP ON P.PRODUCT_ID = SP.PRODUCT_ID LEFT JOIN WAREHOUSE_STOCK WS ON P.PRODUCT_ID = WS.PRODUCT_ID GROUP BY P.PRODUCT_ID ORDER BY P.PRODUCT_ID, LAST_UPDATED DESC;
WITH PRODUCTSTOCK AS ( SELECT WS.PRODUCT_ID, SUM(WS.QUANTITY) AS TOTAL_QUANTITY, MAX(WS.LAST_UPDATED) AS LAST_UPDATED FROM WAREHOUSE_STOCK WS GROUP BY WS.PRODUCT_ID ) SELECT P.PRODUCT_ID, P.PRODUCT_NAME, P.MODEL, P.PRICE, P.STATUS, P.EAN_UPC, P.SKU, C.CATEGORY_NAME, S.SUPPLIER_NAME, SP.SUPPLY_PRICE, SP.LEAD_TIME, PS.TOTAL_QUANTITY, PS.LAST_UPDATED FROM PRODUCTS P INNER JOIN CATEGORIES C ON P.CATEGORY_ID = C.CATEGORY_ID INNER JOIN SUPPLIER_PRODUCTS SP ON P.PRODUCT_ID = SP.PRODUCT_ID INNER JOIN SUPPLIERS S ON SP.SUPPLIER_ID = S.SUPPLIER_ID INNER JOIN PRODUCTSTOCK PS ON P.PRODUCT_ID = PS.PRODUCT_ID ORDER BY P.PRODUCT_ID, PS.LAST_UPDATED DESC;

