WITH DOMAINTOPICFILTER AS ( SELECT A.ARTICLE_ID, A.TITLE, A.DOMAIN_ID, A.TOPIC_ID FROM ARTICLES A JOIN DOMAINS D ON A.DOMAIN_ID = D.DOMAIN_ID JOIN TOPICS T ON A.TOPIC_ID = T.TOPIC_ID WHERE D.DOMAIN_NAME = 'WIKINEWS' AND T.TOPIC_NAME = 'RESEARCH' ), AVGRATINGWIKINEWSRESEARCH AS ( SELECT AVG(R.RATING) AS AVG_RATING FROM DOMAINTOPICFILTER DTF JOIN RATINGS R ON DTF.ARTICLE_ID = R.ARTICLE_ID ), ARTICLERATINGS AS ( SELECT A.ARTICLE_ID, A.TITLE, AVG(R.RATING) AS AVG_RATING FROM ARTICLES A JOIN RATINGS R ON A.ARTICLE_ID = R.ARTICLE_ID GROUP BY A.ARTICLE_ID, A.TITLE ) SELECT AR.TITLE FROM ARTICLERATINGS AR WHERE AR.AVG_RATING > (SELECT AVG_RATING FROM AVGRATINGWIKINEWSRESEARCH) ORDER BY AR.AVG_RATING DESC;

