WITH RESEARCHERSTATS AS ( SELECT E.RESEARCHER_ID, R.RESEARCHER_NAME, COUNT(E.EXPERIMENT_ID) AS EXPERIMENT_COUNT, SUM(E.PARTICIPANT_COUNT) AS TOTAL_PARTICIPANT_COUNT, SUM(T.DURATION) AS TOTAL_TRIAL_DURATION FROM EXPERIMENTS E JOIN RESEARCHERS R ON E.RESEARCHER_ID = R.RESEARCHER_ID JOIN TRIALS T ON E.EXPERIMENT_ID = T.EXPERIMENT_ID GROUP BY E.RESEARCHER_ID, R.RESEARCHER_NAME ), TOPRESEARCHER AS ( SELECT RESEARCHER_ID, RESEARCHER_NAME FROM RESEARCHERSTATS WHERE TOTAL_PARTICIPANT_COUNT > 100 AND TOTAL_TRIAL_DURATION > 1000 ORDER BY EXPERIMENT_COUNT DESC LIMIT 1 ) SELECT TR.RESEARCHER_NAME FROM TOPRESEARCHER TR JOIN EXPERIMENTS E ON TR.RESEARCHER_ID = E.RESEARCHER_ID WHERE E.STATUS = 'ONGOING';
WITH RESEARCHER_STATS AS ( SELECT E.RESEARCHER_ID, COUNT(*) AS EXPERIMENT_COUNT, SUM(E.PARTICIPANT_COUNT) AS TOTAL_PARTICIPANTS, SUM(T.DURATION) AS TOTAL_DURATION FROM EXPERIMENTS E JOIN TRIALS T ON E.EXPERIMENT_ID = T.EXPERIMENT_ID GROUP BY E.RESEARCHER_ID ), TOP_RESEARCHER AS ( SELECT RESEARCHER_ID FROM RESEARCHER_STATS ORDER BY EXPERIMENT_COUNT DESC LIMIT 1 ), QUALIFIED_RESEARCHERS AS ( SELECT RS.RESEARCHER_ID FROM RESEARCHER_STATS RS WHERE RS.TOTAL_PARTICIPANTS > 100 AND RS.TOTAL_DURATION > 1000 ) SELECT R.RESEARCHER_NAME FROM RESEARCHERS R JOIN TOP_RESEARCHER TR ON R.RESEARCHER_ID = TR.RESEARCHER_ID JOIN QUALIFIED_RESEARCHERS QR ON R.RESEARCHER_ID = QR.RESEARCHER_ID JOIN ( SELECT DISTINCT RESEARCHER_ID FROM EXPERIMENTS WHERE STATUS = 'ONGOING' ) ONGOING ON R.RESEARCHER_ID = ONGOING.RESEARCHER_ID;

