SELECT P.PANEL_ID, P.KEY, P.HEADER, P.DISABLED, P.FORCE_RENDER, P.SHOW_ARROW, P.VERSION, P.LAZY_RENDER, P.RENDER_IMMEDIATELY, P.HIDE_HEADER, P.CUSTOM_CSS, T.TESTER_NAME, F.RATING, D.DEPENDENT_PANEL_ID, D.DEPENDENCY_TYPE, PV.VERSION_NUMBER, PV.CHANGE_DATE, PV.CHANGE_DESCRIPTION FROM PANELS P INNER JOIN PANEL_VERSIONS PV ON P.PANEL_ID = PV.PANEL_ID LEFT JOIN TESTERS T ON PV.CHANGED_BY = T.TESTER_ID LEFT JOIN FEEDBACK F ON P.PANEL_ID = F.PANEL_ID LEFT JOIN PANEL_DEPENDENCIES D ON P.PANEL_ID = D.PANEL_ID WHERE PV.CHANGE_DATE = ( SELECT MAX(CHANGE_DATE) FROM PANEL_VERSIONS PV2 WHERE PV2.PANEL_ID = PV.PANEL_ID ) ORDER BY P.PANEL_ID;
WITH LATESTPANELVERSION AS ( SELECT P.PANEL_ID, P.KEY, P.HEADER, P.DISABLED, P.FORCE_RENDER, P.SHOW_ARROW, P.VERSION AS PANEL_VERSION, P.LAZY_RENDER, P.RENDER_IMMEDIATELY, P.HIDE_HEADER, P.CUSTOM_CSS, PV.VERSION_NUMBER, PV.CHANGE_DESCRIPTION, PV.CHANGE_DATE, U.USERNAME AS CHANGED_BY FROM PANELS P INNER JOIN PANEL_VERSIONS PV ON P.PANEL_ID = PV.PANEL_ID INNER JOIN USERS U ON PV.CHANGED_BY = U.USER_ID WHERE (PV.PANEL_ID, PV.CHANGE_DATE) IN ( SELECT PANEL_ID, MAX(CHANGE_DATE) FROM PANEL_VERSIONS GROUP BY PANEL_ID ) ) SELECT LPV.PANEL_ID, LPV.KEY, LPV.HEADER, LPV.DISABLED, LPV.FORCE_RENDER, LPV.SHOW_ARROW, LPV.PANEL_VERSION, LPV.LAZY_RENDER, LPV.RENDER_IMMEDIATELY, LPV.HIDE_HEADER, LPV.CUSTOM_CSS, LPV.VERSION_NUMBER, LPV.CHANGE_DESCRIPTION, LPV.CHANGE_DATE, LPV.CHANGED_BY, F.RATING AS FEEDBACK_RATING, PD.DEPENDENT_PANEL_ID, PD.DEPENDENCY_TYPE FROM LATESTPANELVERSION LPV LEFT JOIN FEEDBACK F ON LPV.PANEL_ID = F.PANEL_ID LEFT JOIN PANEL_DEPENDENCIES PD ON LPV.PANEL_ID = PD.PANEL_ID ORDER BY LPV.PANEL_ID;

