WITH LATESTDATA AS ( SELECT D.BUOY_ID, MAX(D.DATE_TIME) AS LATEST_DATE_TIME FROM DATASETS D GROUP BY D.BUOY_ID ), LATESTWINDDATA AS ( SELECT W.DATASET_ID, W.AVERAGE_SPEED, W.GUST_SPEED, D.DATE_TIME FROM WIND_DATA W JOIN DATASETS D ON W.DATASET_ID = D.DATASET_ID JOIN LATESTDATA LD ON D.BUOY_ID = LD.BUOY_ID AND D.DATE_TIME = LD.LATEST_DATE_TIME ) SELECT B.BUOY_ID, B.LOCATION, B.LATITUDE, B.LONGITUDE, B.DEPLOYMENT_DATE, WD.AVERAGE_SPEED, WD.GUST_SPEED FROM LATESTWINDDATA WD JOIN DATASETS D ON WD.DATASET_ID = D.DATASET_ID JOIN BUOYS B ON D.BUOY_ID = B.BUOY_ID ORDER BY B.BUOY_ID;
WITH LATESTWINDDATA AS (
    SELECT 
        D.BUOY_ID,
        MAX(D.DATE_TIME) AS LATEST_DATE_TIME
    FROM DATASETS D
    JOIN WIND_DATA W ON D.DATASET_ID = W.DATASET_ID
    GROUP BY D.BUOY_ID
)
SELECT 
    B.BUOY_ID,
    B.LOCATION,
    B.LATITUDE,
    B.LONGITUDE,
    B.DEPLOYMENT_DATE,
    W.AVERAGE_SPEED,
    W.GUST_SPEED
FROM LATESTWINDDATA LWD
JOIN DATASETS D ON LWD.BUOY_ID = D.BUOY_ID AND LWD.LATEST_DATE_TIME = D.DATE_TIME
JOIN WIND_DATA W ON D.DATASET_ID = W.DATASET_ID
JOIN BUOYS B ON D.BUOY_ID = B.BUOY_ID
ORDER BY B.BUOY_ID;

