WITH DRAWING_AGGREGATES AS ( SELECT CATEGORY, COUNT(DRAWING_ID) AS NUM_DRAWINGS, AVG(FILE_SIZE) AS AVG_SIZE FROM DRAWINGS GROUP BY CATEGORY ), DEPARTMENT_CATEGORIES AS ( SELECT DISTINCT DEPARTMENT_NAME AS CATEGORY FROM DEPARTMENTS ) SELECT DA.CATEGORY, DA.NUM_DRAWINGS, DA.AVG_SIZE, CASE WHEN DC.CATEGORY IS NOT NULL THEN 'YES' ELSE 'NO' END AS OVERLAP_WITH_DEPARTMENT FROM DRAWING_AGGREGATES DA LEFT JOIN DEPARTMENT_CATEGORIES DC ON DA.CATEGORY = DC.CATEGORY;

