SELECT 
    G.TITLE
FROM 
    GAMES G
JOIN 
    REVIEWS R ON G.GAME_ID = R.GAME_ID
JOIN 
    ANALYTICS A ON R.REVIEW_ID = A.REVIEW_ID
GROUP BY 
    G.GAME_ID, G.TITLE
HAVING 
    AVG(R.RATING) > 8 AND AVG(R.RECOMMENDATION) > 3
ORDER BY 
    SUM(A.VIEWS) DESC;
WITH GAMESTATS AS ( SELECT R.GAME_ID, G.TITLE, AVG(R.RATING) AS AVERAGE_RATING, AVG(REC.SCORE) AS AVERAGE_RECOMMENDATION_SCORE, SUM(A.VIEWS) AS TOTAL_VIEWS FROM REVIEWS R JOIN GAMES G ON R.GAME_ID = G.GAME_ID LEFT JOIN RECOMMENDATIONS REC ON R.GAME_ID = REC.GAME_ID LEFT JOIN ANALYTICS A ON R.REVIEW_ID = A.REVIEW_ID GROUP BY R.GAME_ID, G.TITLE ) SELECT TITLE FROM GAMESTATS WHERE AVERAGE_RATING > 8 AND AVERAGE_RECOMMENDATION_SCORE > 3 ORDER BY TOTAL_VIEWS DESC;

