WITH GAMECOUNTS AS ( SELECT T.TEAM_ID, T.TEAM_NAME, COUNT(G.GAME_ID) AS TOTAL_GAMES, SUM(CASE WHEN G.HOME_TEAM_ID = T.TEAM_ID AND G.HOME_TEAM_SCORE > G.AWAY_TEAM_SCORE THEN 1 WHEN G.AWAY_TEAM_ID = T.TEAM_ID AND G.AWAY_TEAM_SCORE > G.HOME_TEAM_SCORE THEN 1 ELSE 0 END) AS TOTAL_WINS, SUM(CASE WHEN G.HOME_TEAM_ID = T.TEAM_ID AND G.HOME_TEAM_SCORE < G.AWAY_TEAM_SCORE THEN 1 WHEN G.AWAY_TEAM_ID = T.TEAM_ID AND G.AWAY_TEAM_SCORE < G.HOME_TEAM_SCORE THEN 1 ELSE 0 END) AS TOTAL_LOSSES, AVG(G.ATTENDANCE) AS AVG_ATTENDANCE FROM TEAMS T LEFT JOIN GAMES G ON T.TEAM_ID = G.HOME_TEAM_ID OR T.TEAM_ID = G.AWAY_TEAM_ID GROUP BY T.TEAM_ID, T.TEAM_NAME ), AVERAGESCORES AS ( SELECT G.HOME_TEAM_ID AS TEAM_ID, AVG(G.HOME_TEAM_SCORE) AS AVG_HOME_SCORE, AVG(G.AWAY_TEAM_SCORE) AS AVG_AWAY_SCORE FROM GAMES G GROUP BY G.HOME_TEAM_ID ), COACHEXPERIENCE AS ( SELECT T.TEAM_ID, AVG(C.EXPERIENCE_YEARS) AS AVG_COACH_EXPERIENCE FROM TEAMS T JOIN COACHES C ON T.COACH_ID = C.COACH_ID GROUP BY T.TEAM_ID ) SELECT GC.TEAM_NAME, GC.TOTAL_GAMES, GC.TOTAL_WINS, GC.TOTAL_LOSSES, GC.AVG_ATTENDANCE, COALESCE(ASR.AVG_HOME_SCORE, 0) AS AVG_HOME_SCORE, COALESCE(ASR.AVG_AWAY_SCORE, 0) AS AVG_AWAY_SCORE, COALESCE(CE.AVG_COACH_EXPERIENCE, 0) AS AVG_COACH_EXPERIENCE FROM GAMECOUNTS GC LEFT JOIN AVERAGESCORES ASR ON GC.TEAM_ID = ASR.TEAM_ID LEFT JOIN COACHEXPERIENCE CE ON GC.TEAM_ID = CE.TEAM_ID ORDER BY GC.TOTAL_WINS DESC, GC.TOTAL_LOSSES ASC, GC.AVG_ATTENDANCE DESC;
WITH TEAMSTATS AS ( SELECT T.TEAM_ID, T.TEAM_NAME, COUNT(G.GAME_ID) AS TOTAL_GAMES, SUM(CASE WHEN G.HOME_TEAM_ID = T.TEAM_ID AND G.HOME_TEAM_SCORE > G.AWAY_TEAM_SCORE THEN 1 WHEN G.AWAY_TEAM_ID = T.TEAM_ID AND G.AWAY_TEAM_SCORE > G.HOME_TEAM_SCORE THEN 1 ELSE 0 END) AS TOTAL_WINS, SUM(CASE WHEN G.HOME_TEAM_ID = T.TEAM_ID AND G.HOME_TEAM_SCORE < G.AWAY_TEAM_SCORE THEN 1 WHEN G.AWAY_TEAM_ID = T.TEAM_ID AND G.AWAY_TEAM_SCORE < G.HOME_TEAM_SCORE THEN 1 ELSE 0 END) AS TOTAL_LOSSES, AVG(CASE WHEN G.HOME_TEAM_ID = T.TEAM_ID OR G.AWAY_TEAM_ID = T.TEAM_ID THEN G.ATTENDANCE ELSE NULL END) AS AVERAGE_ATTENDANCE, AVG(CASE WHEN G.HOME_TEAM_ID = T.TEAM_ID THEN G.HOME_TEAM_SCORE ELSE NULL END) AS AVERAGE_HOME_SCORE, AVG(CASE WHEN G.AWAY_TEAM_ID = T.TEAM_ID THEN G.AWAY_TEAM_SCORE ELSE NULL END) AS AVERAGE_AWAY_SCORE, AVG(C.EXPERIENCE_YEARS) AS AVERAGE_COACH_EXPERIENCE FROM TEAMS T LEFT JOIN GAMES G ON T.TEAM_ID IN (G.HOME_TEAM_ID, G.AWAY_TEAM_ID) LEFT JOIN COACHES C ON T.COACH_ID = C.COACH_ID GROUP BY T.TEAM_ID, T.TEAM_NAME ) SELECT TEAM_NAME, TOTAL_GAMES, TOTAL_WINS, TOTAL_LOSSES, AVERAGE_ATTENDANCE, AVERAGE_HOME_SCORE, AVERAGE_AWAY_SCORE, AVERAGE_COACH_EXPERIENCE FROM TEAMSTATS ORDER BY TOTAL_WINS DESC, TOTAL_LOSSES ASC, AVERAGE_ATTENDANCE DESC;

