WITH FIRE_FLAVOR AS ( SELECT C.CHARACTER_ID, C.IDENTIFIER FROM CHARACTERS C JOIN CHARACTER_FLAVORS CF ON C.CHARACTER_ID = CF.CHARACTER_ID JOIN FLAVORS F ON CF.FLAVOR_ID = F.FLAVOR_ID WHERE F.FLAVOR_NAME = 'FIRE' ), FIRE_AND_ICE_FLAVOR AS ( SELECT C.CHARACTER_ID, C.IDENTIFIER FROM CHARACTERS C JOIN CHARACTER_FLAVORS CF1 ON C.CHARACTER_ID = CF1.CHARACTER_ID JOIN FLAVORS F1 ON CF1.FLAVOR_ID = F1.FLAVOR_ID JOIN CHARACTER_FLAVORS CF2 ON C.CHARACTER_ID = CF2.CHARACTER_ID JOIN FLAVORS F2 ON CF2.FLAVOR_ID = F2.FLAVOR_ID WHERE F1.FLAVOR_NAME = 'FIRE' AND F2.FLAVOR_NAME = 'ICE' ), ONLY_FIRE_FLAVOR AS ( SELECT FF.CHARACTER_ID, FF.IDENTIFIER FROM FIRE_FLAVOR FF WHERE FF.CHARACTER_ID NOT IN ( SELECT FC.CHARACTER_ID FROM FIRE_AND_ICE_FLAVOR FC ) ) SELECT * FROM FIRE_AND_ICE_FLAVOR UNION SELECT * FROM ONLY_FIRE_FLAVOR;

