WITH SUBJECTDATA AS ( SELECT S.SUBJECT_ID, S.NAME, S.GENDER, S.ETHNICITY FROM SUBJECTS S ), SIGNALDATA AS ( SELECT R.RECORDING_ID, ST.SIGNAL_TYPE_NAME FROM RECORDINGS R JOIN SIGNAL_TYPES ST ON R.SIGNAL_TYPE_ID = ST.SIGNAL_TYPE_ID ), PREDICTIONDATA AS ( SELECT MP.RECORDING_ID, AVG(MP.PREDICTION_VALUE) AS AVG_PREDICTION_VALUE, COUNT(MP.PREDICTION_VALUE) AS PREDICTION_COUNT FROM MODEL_PREDICTIONS MP GROUP BY MP.RECORDING_ID ) SELECT SD.NAME, SD.GENDER, SD.ETHNICITY, SDG.SIGNAL_TYPE_NAME, PD.AVG_PREDICTION_VALUE, PD.PREDICTION_COUNT FROM SUBJECTDATA SD JOIN SIGNALDATA SDG ON SD.SUBJECT_ID = SDG.RECORDING_ID JOIN PREDICTIONDATA PD ON SDG.RECORDING_ID = PD.RECORDING_ID ORDER BY SD.NAME, SDG.SIGNAL_TYPE_NAME;
WITH SUBJECT_SIGNAL_DATA AS ( SELECT S.SUBJECT_ID, S.NAME, S.GENDER, S.ETHNICITY, ST.SIGNAL_TYPE_ID, ST.SIGNAL_TYPE_NAME, MP.PREDICTION_VALUE FROM SUBJECTS S JOIN RECORDINGS R ON S.SUBJECT_ID = R.SUBJECT_ID JOIN SIGNAL_TYPES ST ON R.SIGNAL_TYPE_ID = ST.SIGNAL_TYPE_ID JOIN MODEL_PREDICTIONS MP ON R.RECORDING_ID = MP.RECORDING_ID ), AGGREGATED_DATA AS ( SELECT SUBJECT_ID, NAME, GENDER, ETHNICITY, SIGNAL_TYPE_ID, SIGNAL_TYPE_NAME, AVG(PREDICTION_VALUE) AS AVG_PREDICTION_VALUE, COUNT(PREDICTION_VALUE) AS PREDICTION_COUNT FROM SUBJECT_SIGNAL_DATA GROUP BY SUBJECT_ID, SIGNAL_TYPE_ID ) SELECT NAME, GENDER, ETHNICITY, SIGNAL_TYPE_NAME, AVG_PREDICTION_VALUE, PREDICTION_COUNT FROM AGGREGATED_DATA ORDER BY NAME, SIGNAL_TYPE_NAME;

