SELECT U.USER_NAME, COUNT(*) AS POTENTIAL_FRAUD_COUNT FROM USERS U JOIN ( SELECT T.USER_ID, T.TRANSACTION_ID FROM TRANSACTIONS T WHERE T.TOTAL_AMOUNT > ( SELECT AVG(T2.TOTAL_AMOUNT) * 10 FROM TRANSACTIONS T2 WHERE T2.USER_ID = T.USER_ID ) ) FT ON U.USER_ID = FT.USER_ID WHERE U.ROLE IN ('TRADER', 'ANALYST') GROUP BY U.USER_ID, U.USER_NAME ORDER BY POTENTIAL_FRAUD_COUNT DESC;
WITH USERAVERAGE AS ( SELECT USER_ID, AVG(TOTAL_AMOUNT) AS AVG_AMOUNT FROM TRANSACTIONS GROUP BY USER_ID ) SELECT U.USER_NAME, SUM(CASE WHEN ABS(T.TOTAL_AMOUNT) > 10 * ABS(UA.AVG_AMOUNT) THEN 1 ELSE 0 END) AS POTENTIAL_FRAUD_COUNT FROM TRANSACTIONS T INNER JOIN USERS U ON T.USER_ID = U.USER_ID INNER JOIN USERAVERAGE UA ON T.USER_ID = UA.USER_ID WHERE U.ROLE IN ('TRADER', 'ANALYST') GROUP BY U.USER_NAME ORDER BY POTENTIAL_FRAUD_COUNT DESC;

