WITH USERFEEDBACK AS ( SELECT U.USER_NAME, UF.FEEDBACK_TEXT, R.REVIEW_ID, R.PRODUCT_ID FROM USERS U INNER JOIN USER_FEEDBACK UF ON U.USER_ID = UF.USER_ID INNER JOIN REVIEWS R ON UF.REVIEW_ID = R.REVIEW_ID INNER JOIN TIME_PERIODS TP ON R.REVIEW_DATE BETWEEN TP.START_DATE AND TP.END_DATE WHERE TP.PERIOD_ID = 0 ), PRODUCTAVERAGERATING AS ( SELECT P.PRODUCT_ID, AVG(R.RATING) AS AVERAGE_RATING FROM PRODUCTS P INNER JOIN REVIEWS R ON P.PRODUCT_ID = R.REVIEW_ID WHERE P.CATEGORY_ID = 0 GROUP BY P.PRODUCT_ID ), REVIEWSENTIMENT AS ( SELECT RS.REVIEW_ID, RS.SENTIMENT_SCORE FROM SENTIMENT_SCORES RS ) SELECT UF.USER_NAME, UF.FEEDBACK_TEXT, PAR.AVERAGE_RATING, RS.SENTIMENT_SCORE FROM USERFEEDBACK UF INNER JOIN PRODUCTAVERAGERATING PAR ON UF.PRODUCT_ID = PAR.PRODUCT_ID INNER JOIN REVIEWSENTIMENT RS ON UF.REVIEW_ID = RS.REVIEW_ID;
WITH AVG_RATING AS ( SELECT R.PRODUCT_ID, AVG(R.RATING) AS AVERAGE_RATING FROM REVIEWS AS R WHERE R.PRODUCT_ID IN ( SELECT P.PRODUCT_ID FROM PRODUCTS AS P JOIN PRODUCT_CATEGORIES AS PC ON P.CATEGORY_ID = PC.CATEGORY_ID WHERE PC.CATEGORY_ID = 0 ) GROUP BY R.PRODUCT_ID ) SELECT U.USER_NAME, F.FEEDBACK_TEXT, AR.AVERAGE_RATING, S.SENTIMENT_SCORE FROM USERS AS U JOIN USER_FEEDBACK AS F ON U.USER_ID = F.USER_ID JOIN REVIEWS AS R ON F.REVIEW_ID = R.REVIEW_ID JOIN AVG_RATING AS AR ON R.PRODUCT_ID = AR.PRODUCT_ID JOIN TIME_PERIODS AS TP ON R.REVIEW_DATE BETWEEN TP.START_DATE AND TP.END_DATE JOIN SENTIMENT_SCORES AS S ON R.REVIEW_ID = S.REVIEW_ID JOIN PRODUCTS AS P ON R.PRODUCT_ID = P.PRODUCT_ID JOIN PRODUCT_CATEGORIES AS PC ON P.CATEGORY_ID = PC.CATEGORY_ID WHERE TP.PERIOD_ID = 0 AND PC.CATEGORY_ID = 0;

