WITH USERVOTECOUNTS AS ( SELECT V.USER_ID, COUNT(V.VOTE_ID) AS VOTE_COUNT FROM VOTES V GROUP BY V.USER_ID ), TOPVOTINGUSERS AS ( SELECT USER_ID, VOTE_COUNT FROM USERVOTECOUNTS ORDER BY VOTE_COUNT DESC LIMIT 5 ), USERPOLLCOUNTS AS ( SELECT P.USER_ID, COUNT(P.POLL_ID) AS POLL_COUNT FROM POLLS P GROUP BY P.USER_ID ) SELECT U.USER_NAME, TU.VOTE_COUNT AS TOTAL_VOTES, COALESCE(UPC.POLL_COUNT, 0) AS TOTAL_POLLS FROM TOPVOTINGUSERS TU JOIN USERS U ON TU.USER_ID = U.USER_ID LEFT JOIN USERPOLLCOUNTS UPC ON TU.USER_ID = UPC.USER_ID ORDER BY TU.VOTE_COUNT DESC;
WITH USERVOTES AS ( SELECT U.USER_ID, U.USER_NAME, COUNT(V.VOTE_ID) AS TOTAL_VOTES FROM USERS U INNER JOIN VOTES V ON U.USER_ID = V.USER_ID GROUP BY U.USER_ID, U.USER_NAME ), USERPOLLS AS ( SELECT U.USER_ID, COUNT(P.POLL_ID) AS TOTAL_POLLS FROM USERS U INNER JOIN POLLS P ON U.USER_ID = P.USER_ID GROUP BY U.USER_ID ) SELECT UV.USER_NAME, UV.TOTAL_VOTES, UP.TOTAL_POLLS FROM USERVOTES UV INNER JOIN USERPOLLS UP ON UV.USER_ID = UP.USER_ID ORDER BY UV.TOTAL_VOTES DESC LIMIT 5;

