SELECT 
    U.USER_NAME AS USER_NAME,
    COUNT(I.ISSUE_ID) AS TOTAL_ISSUES,
    SUM(CASE WHEN I.STATUS = 'RESOLVED' THEN 1 ELSE 0 END) AS RESOLVED_ISSUES,
    CASE 
        WHEN AVG(CASE WHEN I.PRIORITY = 'HIGH' THEN 1.0
                      WHEN I.PRIORITY = 'MEDIUM' THEN 2.0
                      WHEN I.PRIORITY = 'LOW' THEN 3.0
                      ELSE 0 END) <= 1.5 THEN 'HIGH'
        WHEN AVG(CASE WHEN I.PRIORITY = 'HIGH' THEN 1.0
                      WHEN I.PRIORITY = 'MEDIUM' THEN 2.0
                      WHEN I.PRIORITY = 'LOW' THEN 3.0
                      ELSE 0 END) <= 2.5 THEN 'MEDIUM'
        ELSE 'LOW'
    END AS AVERAGE_PRIORITY_LABEL
FROM 
    ISSUES I
JOIN 
    USERS U ON I.OWNER = U.USER_NAME
GROUP BY 
    U.USER_NAME
ORDER BY 
    TOTAL_ISSUES DESC;
WITH USER_ISSUE_STATS AS ( SELECT U.USER_NAME, COUNT(I.ISSUE_ID) AS TOTAL_ISSUES, SUM(CASE WHEN I.STATUS = 'RESOLVED' THEN 1 ELSE 0 END) AS RESOLVED_ISSUES, AVG(CASE WHEN I.PRIORITY = 'HIGH' THEN 1.0 WHEN I.PRIORITY = 'MEDIUM' THEN 2.0 WHEN I.PRIORITY = 'LOW' THEN 3.0 ELSE 0 END) AS AVG_PRIORITY_VALUE FROM USERS U JOIN ISSUES I ON U.USER_NAME = I.OWNER GROUP BY U.USER_NAME ) SELECT USER_NAME, TOTAL_ISSUES, RESOLVED_ISSUES, CASE WHEN AVG_PRIORITY_VALUE <= 1.5 THEN 'HIGH' WHEN AVG_PRIORITY_VALUE <= 2.5 THEN 'MEDIUM' ELSE 'LOW' END AS AVERAGE_PRIORITY_LABEL FROM USER_ISSUE_STATS ORDER BY TOTAL_ISSUES DESC;

