SELECT 
  E.EXPERIMENT_NAME,
  COUNT(P.PARTICIPANT_ID) AS PARTICIPANT_COUNT,
  AVG(R.RT) AS AVERAGE_RESPONSE_TIME
FROM EXPERIMENTS E
JOIN PARTICIPANTS P ON E.EXPERIMENT_ID = P.EXPERIMENT_ID
JOIN RESPONSES R ON P.PARTICIPANT_ID = R.PARTICIPANT_ID
GROUP BY E.EXPERIMENT_NAME
ORDER BY PARTICIPANT_COUNT DESC;
WITH EXPERIMENT_DATA AS ( SELECT E.EXPERIMENT_ID, E.EXPERIMENT_NAME, COUNT(P.PARTICIPANT_ID) AS PARTICIPANT_COUNT FROM EXPERIMENTS E JOIN PARTICIPANTS P ON E.EXPERIMENT_ID = P.EXPERIMENT_ID GROUP BY E.EXPERIMENT_ID, E.EXPERIMENT_NAME ), RESPONSE_DATA AS ( SELECT P.EXPERIMENT_ID, AVG(R.RT) AS AVERAGE_RESPONSE_TIME FROM PARTICIPANTS P JOIN RESPONSES R ON P.PARTICIPANT_ID = R.PARTICIPANT_ID GROUP BY P.EXPERIMENT_ID ) SELECT ED.EXPERIMENT_NAME, ED.PARTICIPANT_COUNT, RD.AVERAGE_RESPONSE_TIME FROM EXPERIMENT_DATA ED JOIN RESPONSE_DATA RD ON ED.EXPERIMENT_ID = RD.EXPERIMENT_ID ORDER BY ED.PARTICIPANT_COUNT DESC;

