SELECT DISTINCT B.BUILDING_ID, B.BUILDING_NAME FROM BUILDINGS B JOIN MAINTENANCE_SCHEDULES MS ON B.BUILDING_ID = MS.BUILDING_ID JOIN ENERGY_CONSUMPTION EC ON B.BUILDING_ID = EC.BUILDING_ID WHERE MS.MAINTENANCE_TYPE = 'HVAC' AND EC.CONSUMPTION_UNIT = 'KWH' AND EC.CONSUMPTION_VALUE > 2000;
WITH HVAC_BUILDINGS AS ( SELECT DISTINCT B.BUILDING_ID, B.BUILDING_NAME FROM BUILDINGS B INNER JOIN MAINTENANCE_SCHEDULES MS ON B.BUILDING_ID = MS.BUILDING_ID INNER JOIN MAINTENANCE_TYPES MT ON MS.MAINTENANCE_TYPE = MT.TYPE_ID WHERE MT.TYPE_NAME = 'HVAC' ), HIGH_ENERGY_BUILDINGS AS ( SELECT DISTINCT B.BUILDING_ID, B.BUILDING_NAME FROM BUILDINGS B INNER JOIN ENERGY_CONSUMPTION EC ON B.BUILDING_ID = EC.BUILDING_ID WHERE EC.CONSUMPTION_VALUE > 2000 AND EC.CONSUMPTION_UNIT = 'KWH' ) SELECT HB.BUILDING_ID, HB.BUILDING_NAME FROM HVAC_BUILDINGS HB INNER JOIN HIGH_ENERGY_BUILDINGS HEB ON HB.BUILDING_ID = HEB.BUILDING_ID;

