WITH FASHIONPRODUCTS AS ( SELECT P.PRODUCT_ID, P.PRODUCT_NAME, SUM(OI.QUANTITY * OI.UNIT_PRICE) AS TOTAL_SALES FROM ORDER_ITEMS OI JOIN PRODUCTS P ON OI.PRODUCT_ID = P.PRODUCT_ID JOIN CATEGORIES C ON P.CATEGORY_ID = C.CATEGORY_ID WHERE C.CATEGORY_NAME = 'FASHION' GROUP BY P.PRODUCT_ID, P.PRODUCT_NAME ) SELECT PRODUCT_ID, PRODUCT_NAME, TOTAL_SALES FROM FASHIONPRODUCTS ORDER BY TOTAL_SALES DESC LIMIT 1;

