WITH LATESTRELEASES AS ( SELECT CATEGORY, MAX(REL_DATE) AS LATEST_REL_DATE FROM RELEASES GROUP BY CATEGORY ), LATESTRELEASEDETAILS AS ( SELECT R.CATEGORY, R.RELEASE_ID, R.REL_DATE, R.FILENAME, R.CREATED_BY FROM RELEASES R INNER JOIN LATESTRELEASES LR ON R.CATEGORY = LR.CATEGORY AND R.REL_DATE = LR.LATEST_REL_DATE ), ACCESSSUMMARY AS ( SELECT A.RELEASE_ID, COUNT(F.FILE_ID) AS FILE_COUNT, SUM(F.FILE_SIZE) AS TOTAL_FILE_SIZE, COUNT(DISTINCT A.USER_ID) AS UNIQUE_USERS, MAX(A.ACCESS_DATE) AS LATEST_ACCESS_DATE FROM ACCESS_LOGS A LEFT JOIN FILES F ON A.RELEASE_ID = F.RELEASE_ID GROUP BY A.RELEASE_ID ), CHANGESCOUNT AS ( SELECT C.RELEASE_ID, COUNT(C.CHANGE_ID) AS TOTAL_CHANGES FROM CHANGE_LOGS C GROUP BY C.RELEASE_ID ) SELECT LRD.CATEGORY, LRD.RELEASE_ID, LRD.REL_DATE, LRD.FILENAME, ASUM.FILE_COUNT, ASUM.TOTAL_FILE_SIZE, ASUM.UNIQUE_USERS, ASUM.LATEST_ACCESS_DATE, U.USERNAME AS CREATED_BY, COALESCE(CC.TOTAL_CHANGES, 0) AS TOTAL_CHANGES, LRD.REL_DATE AS CREATED_DATE FROM LATESTRELEASEDETAILS LRD LEFT JOIN ACCESSSUMMARY ASUM ON LRD.RELEASE_ID = ASUM.RELEASE_ID INNER JOIN USERS U ON LRD.CREATED_BY = U.USER_ID LEFT JOIN CHANGESCOUNT CC ON LRD.RELEASE_ID = CC.RELEASE_ID ORDER BY LRD.CATEGORY, LRD.REL_DATE DESC;
WITH LATESTRELEASES AS ( SELECT R.CATEGORY, R.RELEASE_ID, R.REL_DATE, R.FILENAME, R.CREATED_BY, R.CREATED_DATE FROM RELEASES R INNER JOIN ( SELECT CATEGORY, MAX(REL_DATE) AS MAX_DATE FROM RELEASES GROUP BY CATEGORY ) R_MAX ON R.CATEGORY = R_MAX.CATEGORY AND R.REL_DATE = R_MAX.MAX_DATE ), FILESTATS AS ( SELECT F.RELEASE_ID, COUNT(F.FILE_ID) AS FILE_COUNT, SUM(F.FILE_SIZE) AS TOTAL_FILE_SIZE FROM FILES F GROUP BY F.RELEASE_ID ), USERACCESS AS ( SELECT A.RELEASE_ID, COUNT(DISTINCT A.USER_ID) AS UNIQUE_USERS, MAX(A.ACCESS_DATE) AS LATEST_ACCESS_DATE FROM ACCESS_LOGS A GROUP BY A.RELEASE_ID ), CHANGESTATS AS ( SELECT C.RELEASE_ID, COUNT(C.CHANGE_ID) AS TOTAL_CHANGES FROM CHANGE_LOGS C GROUP BY C.RELEASE_ID ), CREATORINFO AS ( SELECT U.USER_ID, U.USERNAME FROM USERS U ) SELECT LR.CATEGORY, LR.RELEASE_ID, LR.REL_DATE, LR.FILENAME, FS.FILE_COUNT, FS.TOTAL_FILE_SIZE, UA.UNIQUE_USERS, UA.LATEST_ACCESS_DATE, CI.USERNAME AS CREATED_BY, CS.TOTAL_CHANGES, LR.CREATED_DATE FROM LATESTRELEASES LR LEFT JOIN FILESTATS FS ON LR.RELEASE_ID = FS.RELEASE_ID LEFT JOIN USERACCESS UA ON LR.RELEASE_ID = UA.RELEASE_ID LEFT JOIN CHANGESTATS CS ON LR.RELEASE_ID = CS.RELEASE_ID LEFT JOIN CREATORINFO CI ON LR.CREATED_BY = CI.USER_ID ORDER BY LR.CATEGORY, LR.REL_DATE DESC;

