WITH AVERAGEPRESSURE AS ( SELECT P.OBSERVATION_ID, AVG(P.MEAN_PRESSURE_HPA) AS AVG_PRESSURE FROM PRESSURE_DATA P GROUP BY P.OBSERVATION_ID ORDER BY AVG_PRESSURE DESC LIMIT 1 ), REQUIREDDATA AS ( SELECT PA.MAX_PRESSURE_HPA, VD.MIN_VISIBILITY_KM, TD.MAX_TEMP_C, WD.MAX_WIND_SPEED_KMH, HD.MEAN_HUMIDITY FROM PRESSURE_DATA PA JOIN VISIBILITY_DATA VD ON PA.OBSERVATION_ID = VD.OBSERVATION_ID JOIN TEMPERATURE_DATA TD ON PA.OBSERVATION_ID = TD.OBSERVATION_ID JOIN WIND_DATA WD ON PA.OBSERVATION_ID = WD.OBSERVATION_ID JOIN HUMIDITY_DATA HD ON PA.OBSERVATION_ID = HD.OBSERVATION_ID WHERE PA.OBSERVATION_ID = (SELECT OBSERVATION_ID FROM AVERAGEPRESSURE) ) SELECT MAX_PRESSURE_HPA AS MAXPRESSURE, MIN_VISIBILITY_KM AS MINVISIBILITY, MAX_TEMP_C AS MAXTEMPERATURE, MAX_WIND_SPEED_KMH AS MAXWINDSPEED, MEAN_HUMIDITY AS AVGHUMIDITY FROM REQUIREDDATA;
WITH AVG_PRESSURE AS ( SELECT OBSERVATION_ID, MEAN_PRESSURE_HPA FROM PRESSURE_DATA ORDER BY MEAN_PRESSURE_HPA DESC LIMIT 1 ), OBSERVATION_DATA AS ( SELECT P.MAX_PRESSURE_HPA, V.MIN_VISIBILITY_KM, T.MAX_TEMP_C, W.MAX_WIND_SPEED_KMH, H.MEAN_HUMIDITY FROM PRESSURE_DATA P JOIN VISIBILITY_DATA V ON P.OBSERVATION_ID = V.OBSERVATION_ID JOIN TEMPERATURE_DATA T ON P.OBSERVATION_ID = T.OBSERVATION_ID JOIN WIND_DATA W ON P.OBSERVATION_ID = W.OBSERVATION_ID JOIN HUMIDITY_DATA H ON P.OBSERVATION_ID = H.OBSERVATION_ID WHERE P.OBSERVATION_ID = (SELECT OBSERVATION_ID FROM AVG_PRESSURE) ) SELECT MAX(MAX_PRESSURE_HPA) AS MAX_PRESSURE, MIN(MIN_VISIBILITY_KM) AS MIN_VISIBILITY, MAX(MAX_TEMP_C) AS MAX_TEMPERATURE, MAX(MAX_WIND_SPEED_KMH) AS MAX_WIND_SPEED, AVG(MEAN_HUMIDITY) AS AVG_HUMIDITY FROM OBSERVATION_DATA;

