SELECT E.EXPERIMENT_ID, (SELECT AVG(R.REWARD_VALUE) FROM AGENTS A INNER JOIN ACTIONS AC ON A.AGENT_ID = AC.AGENT_ID INNER JOIN REWARDS R ON AC.ACTION_ID = R.ACTION_ID WHERE A.EXPERIMENT_ID = E.EXPERIMENT_ID) * (SELECT COUNT(AC.ACTION_ID) FROM AGENTS A INNER JOIN ACTIONS AC ON A.AGENT_ID = AC.AGENT_ID WHERE A.EXPERIMENT_ID = E.EXPERIMENT_ID) / (SELECT COUNT(AGENT_ID) FROM AGENTS A WHERE A.EXPERIMENT_ID = E.EXPERIMENT_ID) AS PERFORMANCE_METRIC FROM EXPERIMENTS E WHERE EXISTS ( SELECT 1 FROM AGENTS A INNER JOIN ACTIONS AC ON A.AGENT_ID = AC.AGENT_ID WHERE A.EXPERIMENT_ID = E.EXPERIMENT_ID );
WITH AGENTREWARDS AS (
    SELECT
        A.EXPERIMENT_ID,
        AVG(R.REWARD_VALUE) AS AVG_REWARD
    FROM
        AGENTS A
    INNER JOIN
        ACTIONS AC ON A.AGENT_ID = AC.AGENT_ID
    INNER JOIN
        REWARDS R ON AC.ACTION_ID = R.ACTION_ID
    GROUP BY
        A.EXPERIMENT_ID
),
EXPERIMENTMETRICS AS (
    SELECT
        A.EXPERIMENT_ID,
        COUNT(A.AGENT_ID) AS AGENT_COUNT,
        SUM(AC.ACTION_ID) AS TOTAL_ACTIONS,
        AR.AVG_REWARD
    FROM
        AGENTS A
    INNER JOIN
        ACTIONS AC ON A.AGENT_ID = AC.AGENT_ID
    INNER JOIN
        AGENTREWARDS AR ON A.EXPERIMENT_ID = AR.EXPERIMENT_ID
    GROUP BY
        A.EXPERIMENT_ID, AR.AVG_REWARD
)
SELECT
    EM.EXPERIMENT_ID,
    ((EM.AVG_REWARD * EM.TOTAL_ACTIONS) / EM.AGENT_COUNT) AS PERFORMANCE_METRIC
FROM
    EXPERIMENTMETRICS EM;

