SELECT T1.USER_ID, (SELECT AVG(DURATION) FROM TRIPS T3 WHERE T3.IS_PEAK_TIME = 1 AND T3.USER_ID = T1.USER_ID) - (SELECT AVG(DURATION) FROM TRIPS T4 WHERE T4.USER_ID = T1.USER_ID) AS DURATION_DIFF, (SELECT AVG(ROUTE_DISTANCE) FROM TRIPS T5 WHERE T5.IS_PEAK_TIME = 1 AND T5.USER_ID = T1.USER_ID) - (SELECT AVG(ROUTE_DISTANCE) FROM TRIPS T6 WHERE T6.USER_ID = T1.USER_ID) AS DISTANCE_DIFF FROM TRIPS T1 GROUP BY T1.USER_ID ORDER BY DURATION_DIFF DESC, DISTANCE_DIFF DESC;
WITH PEAKHOURTRIPS AS ( SELECT USER_ID, AVG(DURATION) AS AVG_PEAK_DURATION, AVG(ROUTE_DISTANCE) AS AVG_PEAK_DISTANCE FROM TRIPS WHERE IS_PEAK_TIME = 1 GROUP BY USER_ID ), ALLTRIPS AS ( SELECT USER_ID, AVG(DURATION) AS AVG_ALL_DURATION, AVG(ROUTE_DISTANCE) AS AVG_ALL_DISTANCE FROM TRIPS GROUP BY USER_ID ) SELECT PHT.USER_ID, PHT.AVG_PEAK_DURATION - ATR.AVG_ALL_DURATION AS DURATION_DIFFERENCE, PHT.AVG_PEAK_DISTANCE - ATR.AVG_ALL_DISTANCE AS DISTANCE_DIFFERENCE FROM PEAKHOURTRIPS PHT JOIN ALLTRIPS ATR ON PHT.USER_ID = ATR.USER_ID ORDER BY DURATION_DIFFERENCE DESC, DISTANCE_DIFFERENCE DESC;

