WITH TOPSELLINGPLANS AS ( SELECT P.PLAN_ID FROM LICENSES L JOIN PRICING_PLANS P ON L.PLAN_ID = P.PLAN_ID GROUP BY P.PLAN_ID ORDER BY COUNT(L.LICENSE_ID) DESC LIMIT 3 ), CUSTOMERSPENDING AS ( SELECT C.NAME, SUM(P.PRICE) AS TOTAL_SPENT FROM LICENSES L JOIN PRICING_PLANS P ON L.PLAN_ID = P.PLAN_ID JOIN CUSTOMERS C ON L.CUSTOMER_ID = C.CUSTOMER_ID WHERE P.PLAN_ID IN (SELECT PLAN_ID FROM TOPSELLINGPLANS) GROUP BY C.NAME ) SELECT C.NAME AS CUSTOMER_NAME, SUM(P.PRICE) AS CUSTOMER_TOTAL_SPENT FROM LICENSES L JOIN PRICING_PLANS P ON L.PLAN_ID = P.PLAN_ID JOIN CUSTOMERS C ON L.CUSTOMER_ID = C.CUSTOMER_ID WHERE P.PLAN_ID IN (SELECT PLAN_ID FROM TOPSELLINGPLANS) GROUP BY C.NAME ORDER BY SUM(P.PRICE) DESC;

