SELECT U.USER_ID, U.USERNAME, COUNT(T.TASK_ID) AS TOTAL_TASKS FROM USERS U JOIN TASKS T ON U.USER_ID = T.ASSIGNEE_ID JOIN ( SELECT TASK_ID FROM ACTIVITY_LOGS GROUP BY TASK_ID HAVING SUM(CASE WHEN ACTION = 'UPDATE' THEN 1 ELSE 0 END) > 0 AND SUM(CASE WHEN ACTION = 'DELETE' THEN 1 ELSE 0 END) = 0 ) FILTERED_LOGS ON T.TASK_ID = FILTERED_LOGS.TASK_ID WHERE U.ROLE_ID = 1 GROUP BY U.USER_ID, U.USERNAME ORDER BY TOTAL_TASKS DESC;
WITH ADMINUSERS AS ( SELECT U.USER_ID, U.USERNAME FROM USERS U WHERE U.ROLE_ID = 1 ), TASKUPDATES AS ( SELECT T.TASK_ID, COUNT(CASE WHEN AL.ACTION = 'UPDATE' THEN 1 END) AS UPDATE_COUNT, COUNT(CASE WHEN AL.ACTION = 'DELETE' THEN 1 END) AS DELETE_COUNT FROM TASKS T LEFT JOIN ACTIVITY_LOGS AL ON T.TASK_ID = AL.TASK_ID GROUP BY T.TASK_ID ), ASSIGNEDTASKS AS ( SELECT AU.USER_ID, AU.USERNAME, T.TASK_ID FROM ADMINUSERS AU INNER JOIN TASKS T ON AU.USER_ID = T.ASSIGNEE_ID ) SELECT AT.USER_ID, AT.USERNAME, COUNT(AT.TASK_ID) AS TOTAL_TASKS FROM ASSIGNEDTASKS AT INNER JOIN TASKUPDATES TU ON AT.TASK_ID = TU.TASK_ID WHERE TU.UPDATE_COUNT > 0 AND TU.DELETE_COUNT = 0 GROUP BY AT.USER_ID, AT.USERNAME ORDER BY TOTAL_TASKS DESC;

