SELECT 
    V.VEHICLE_TYPE,
    COUNT(T.TRIP_ID) AS TOTAL_TRIPS,
    AVG(C.AVERAGE_WAIT_TIME) AS AVERAGE_WAIT_TIME
FROM 
    VEHICLES V
JOIN 
    TRIPS T ON V.VEHICLE_ID = T.VEHICLE_ID
JOIN 
    COVERAGE_AREAS C ON V.VEHICLE_TYPE = C.TRANSPORTATION_MODE
GROUP BY 
    V.VEHICLE_TYPE
ORDER BY 
    V.VEHICLE_TYPE;
WITH VEHICLE_TRIP_COUNTS AS ( SELECT V.VEHICLE_TYPE, COUNT(T.TRIP_ID) AS TOTAL_TRIPS FROM VEHICLES V JOIN TRIPS T ON V.VEHICLE_ID = T.VEHICLE_ID GROUP BY V.VEHICLE_TYPE ), WAIT_TIME_AVERAGES AS ( SELECT V.VEHICLE_TYPE, AVG(C.AVERAGE_WAIT_TIME) AS AVERAGE_WAIT_TIME FROM VEHICLES V JOIN COVERAGE_AREAS C ON V.VEHICLE_TYPE = C.TRANSPORTATION_MODE GROUP BY V.VEHICLE_TYPE ) SELECT VTC.VEHICLE_TYPE, VTC.TOTAL_TRIPS, WTA.AVERAGE_WAIT_TIME FROM VEHICLE_TRIP_COUNTS VTC JOIN WAIT_TIME_AVERAGES WTA ON VTC.VEHICLE_TYPE = WTA.VEHICLE_TYPE ORDER BY VTC.VEHICLE_TYPE;

