SELECT S.STYLE_NAME, M.MEASUREMENT_NAME, SZ.SIZE_LABEL, AVG(SR.MIN_VALUE) AS AVG_MIN_VALUE, AVG(SR.MAX_VALUE) AS AVG_MAX_VALUE FROM STYLES S JOIN STYLE_MEASUREMENTS SM ON S.STYLE_ID = SM.STYLE_ID JOIN MEASUREMENTS M ON SM.MEASUREMENT_ID = M.MEASUREMENT_ID JOIN SIZE_RANGES SR ON SM.MEASUREMENT_ID = SR.MEASUREMENT_ID JOIN SIZES SZ ON SR.SIZE_ID = SZ.SIZE_ID GROUP BY S.STYLE_NAME, M.MEASUREMENT_NAME, SZ.SIZE_LABEL ORDER BY S.STYLE_NAME, M.MEASUREMENT_NAME, SZ.SIZE_LABEL;
WITH SIZERANGEVALUES AS ( SELECT S.SIZE_ID, S.SIZE_LABEL, SR.MIN_VALUE, SR.MAX_VALUE FROM SIZES S INNER JOIN SIZE_RANGES SR ON S.SIZE_ID = SR.SIZE_ID ), STYLEMEASUREMENTVALUES AS ( SELECT M.MEASUREMENT_ID, M.MEASUREMENT_NAME, SM.STYLE_ID, SR.SIZE_LABEL, SR.MIN_VALUE, SR.MAX_VALUE FROM MEASUREMENTS M INNER JOIN STYLE_MEASUREMENTS SM ON M.MEASUREMENT_ID = SM.MEASUREMENT_ID INNER JOIN SIZERANGEVALUES SR ON SM.STYLE_ID = SR.SIZE_ID ), AGGREGATEDVALUES AS ( SELECT SMV.STYLE_ID, S.STYLE_NAME, SMV.MEASUREMENT_ID, M.MEASUREMENT_NAME, SMV.SIZE_LABEL, AVG(SMV.MIN_VALUE) AS AVG_MIN_VALUE, AVG(SMV.MAX_VALUE) AS AVG_MAX_VALUE FROM STYLEMEASUREMENTVALUES SMV INNER JOIN STYLES S ON SMV.STYLE_ID = S.STYLE_ID INNER JOIN MEASUREMENTS M ON SMV.MEASUREMENT_ID = M.MEASUREMENT_ID GROUP BY SMV.STYLE_ID, S.STYLE_NAME, SMV.MEASUREMENT_ID, M.MEASUREMENT_NAME, SMV.SIZE_LABEL ) SELECT AV.STYLE_NAME, AV.MEASUREMENT_NAME, AV.SIZE_LABEL, AV.AVG_MIN_VALUE, AV.AVG_MAX_VALUE FROM AGGREGATEDVALUES AV ORDER BY AV.STYLE_NAME, AV.MEASUREMENT_NAME, AV.SIZE_LABEL;

