SELECT C.COUNTRY_NAME, E.POLLUTANT_NAME, SUM(E.EMISSIONS) AS TOTAL_POLLUTANT_EMISSIONS FROM EMISSION_DATA E JOIN COUNTRIES C ON E.COUNTRY_CODE = C.COUNTRY_CODE WHERE E.COUNTRY_CODE = ( SELECT COUNTRY_CODE FROM EMISSION_DATA GROUP BY COUNTRY_CODE HAVING SUM(EMISSIONS) = ( SELECT MAX(TOTAL_EMISSIONS) FROM ( SELECT SUM(EMISSIONS) AS TOTAL_EMISSIONS FROM EMISSION_DATA GROUP BY COUNTRY_CODE ) ) ) GROUP BY C.COUNTRY_NAME, E.POLLUTANT_NAME ORDER BY TOTAL_POLLUTANT_EMISSIONS DESC LIMIT 1;
WITH EMISSIONTOTALSPERCOUNTRYANDPOLLUTANT AS ( SELECT COUNTRY_CODE, POLLUTANT_NAME, SUM(EMISSIONS) AS TOTAL_EMISSIONS FROM EMISSION_DATA GROUP BY COUNTRY_CODE, POLLUTANT_NAME ), TOTALEMISSIONSPERCOUNTRY AS ( SELECT COUNTRY_CODE, SUM(TOTAL_EMISSIONS) AS COUNTRY_TOTAL_EMISSIONS FROM EMISSIONTOTALSPERCOUNTRYANDPOLLUTANT GROUP BY COUNTRY_CODE ), MAXEMISSIONSCOUNTRY AS ( SELECT COUNTRY_CODE, COUNTRY_TOTAL_EMISSIONS FROM TOTALEMISSIONSPERCOUNTRY ORDER BY COUNTRY_TOTAL_EMISSIONS DESC LIMIT 1 ), PRIMARYPOLLUTANTINMAXCOUNTRY AS ( SELECT COUNTRY_CODE, POLLUTANT_NAME, TOTAL_EMISSIONS FROM EMISSIONTOTALSPERCOUNTRYANDPOLLUTANT WHERE COUNTRY_CODE = (SELECT COUNTRY_CODE FROM MAXEMISSIONSCOUNTRY) ORDER BY TOTAL_EMISSIONS DESC LIMIT 1 ) SELECT COUNTRIES.COUNTRY_NAME, PRIMARYPOLLUTANTINMAXCOUNTRY.POLLUTANT_NAME, PRIMARYPOLLUTANTINMAXCOUNTRY.TOTAL_EMISSIONS FROM COUNTRIES JOIN PRIMARYPOLLUTANTINMAXCOUNTRY ON COUNTRIES.COUNTRY_CODE = PRIMARYPOLLUTANTINMAXCOUNTRY.COUNTRY_CODE;

