WITH AVG_SLEEP_DURATION AS ( SELECT S.PATIENT_ID, AVG(S.TOTAL_MINUTES_ASLEEP) AS AVERAGE_SLEEP FROM SLEEP_DATA S GROUP BY S.PATIENT_ID ), GOAL_DURATION AS ( SELECT G.PATIENT_ID, G.GOAL_VALUE FROM SLEEP_GOALS G WHERE G.GOAL_TYPE = 'DURATION' ) SELECT P.PATIENT_ID, P.NAME, A.AVERAGE_SLEEP, G.GOAL_VALUE FROM PATIENTS P LEFT JOIN AVG_SLEEP_DURATION A ON P.PATIENT_ID = A.PATIENT_ID LEFT JOIN GOAL_DURATION G ON P.PATIENT_ID = G.PATIENT_ID WHERE A.AVERAGE_SLEEP < G.GOAL_VALUE OR G.GOAL_VALUE IS NULL;

