WITH GENETOTALFOLDCHANGE AS ( SELECT GENE_ID, SUM(FC_VALUE) AS TOTAL_FOLD_CHANGE FROM DATASETS GROUP BY GENE_ID ), GENEAVERAGENVALUE AS ( SELECT GENE_ID, AVG(N_VALUE) AS AVERAGE_N_VALUE FROM DATASETS GROUP BY GENE_ID ) SELECT G.GENE_NAME, (GFC.TOTAL_FOLD_CHANGE + GANV.AVERAGE_N_VALUE) AS COMBINED_METRIC FROM GENES G JOIN GENETOTALFOLDCHANGE GFC ON G.GENE_ID = GFC.GENE_ID JOIN GENEAVERAGENVALUE GANV ON G.GENE_ID = GANV.GENE_ID ORDER BY COMBINED_METRIC DESC;
WITH GENE_STATS AS ( SELECT G.GENE_ID, G.GENE_NAME, SUM(D.FC_VALUE) AS TOTAL_FC, AVG(D.N_VALUE) AS AVG_N FROM DATASETS D JOIN GENES G ON D.GENE_ID = G.GENE_ID GROUP BY G.GENE_ID, G.GENE_NAME ) SELECT GS.GENE_NAME, GS.TOTAL_FC + GS.AVG_N AS COMBINED_METRIC FROM GENE_STATS GS ORDER BY COMBINED_METRIC DESC;

