WITH CITATIONCOUNT AS (
    SELECT 
        PAPER_ID,
        COUNT(CITATION_ID) AS CITATION_COUNT
    FROM 
        CITATIONS
    GROUP BY 
        PAPER_ID
)
SELECT 
    P.TITLE, 
    A.NAME AS AUTHOR_NAME, 
    COALESCE(CC.CITATION_COUNT, 0) AS CITATION_COUNT
FROM 
    PAPERS P
LEFT JOIN 
    AUTHORS A ON P.AUTHOR_ID = A.AUTHOR_ID
LEFT JOIN 
    CITATIONCOUNT CC ON P.PAPER_ID = CC.PAPER_ID
ORDER BY 
    CITATION_COUNT DESC;

