WITH AVERAGECITATION AS ( SELECT AVG(TOTAL_CITATIONS) AS AVG_CITATIONS FROM PUBLICATIONS ), HIGHLYCITEDPUBLICATIONS AS ( SELECT P.PUBLICATION_ID, P.TOTAL_CITATIONS, COUNT(PA.AUTHOR_ID) AS NUM_AUTHORS FROM PUBLICATIONS P INNER JOIN PUBLICATION_AUTHORS PA ON P.PUBLICATION_ID = PA.PUBLICATION_ID WHERE P.TOTAL_CITATIONS > (SELECT AVG_CITATIONS FROM AVERAGECITATION) GROUP BY P.PUBLICATION_ID, P.TOTAL_CITATIONS ) SELECT SUM(NUM_AUTHORS * TOTAL_CITATIONS) AS TOTAL_PUBLICATION_IMPACT FROM HIGHLYCITEDPUBLICATIONS;
WITH PUBLICATIONCITATIONSCTE AS ( SELECT P.PUBLICATION_ID, COUNT(C.CITATION_ID) AS TOTAL_CITATIONS FROM PUBLICATIONS P LEFT JOIN CITATIONS C ON P.PUBLICATION_ID = C.PUBLICATION_ID GROUP BY P.PUBLICATION_ID ), AUTHORCOUNTCTE AS ( SELECT PA.PUBLICATION_ID, COUNT(PA.AUTHOR_ID) AS AUTHOR_COUNT FROM PUBLICATION_AUTHORS PA GROUP BY PA.PUBLICATION_ID ) SELECT SUM(AC.AUTHOR_COUNT * PC.TOTAL_CITATIONS) AS TOTAL_IMPACT FROM PUBLICATIONCITATIONSCTE PC INNER JOIN AUTHORCOUNTCTE AC ON PC.PUBLICATION_ID = AC.PUBLICATION_ID WHERE PC.TOTAL_CITATIONS > (SELECT AVG(TOTAL_CITATIONS) FROM PUBLICATIONCITATIONSCTE);

