WITH COUNTRYSUICIDERATESCTE AS ( SELECT SR.COUNTRY_ID, AVG(SR.SUICIDES_NO) AS AVG_SUICIDES_NO FROM SUICIDE_RATES SR GROUP BY SR.COUNTRY_ID ), COUNTRYECONOMICINDICATORSCTE AS ( SELECT EI.COUNTRY_ID, AVG(EI.GDP_PER_CAPITA) AS AVG_GDP_PER_CAPITA FROM ECONOMIC_INDICATORS EI GROUP BY EI.COUNTRY_ID ), COUNTRYHDIINDICATORSCTE AS ( SELECT EI.COUNTRY_ID, AVG(EI.HDI) AS AVG_HDI FROM ECONOMIC_INDICATORS EI GROUP BY EI.COUNTRY_ID ), GLOBALAVERAGESCTE AS ( SELECT AVG(AVG_SUICIDES_NO) AS GLOBAL_AVG_SUICIDES_NO FROM COUNTRYSUICIDERATESCTE ) SELECT COUNT(C.COUNTRY_ID) AS COUNT FROM COUNTRIES C INNER JOIN COUNTRYSUICIDERATESCTE CSR ON C.COUNTRY_ID = CSR.COUNTRY_ID INNER JOIN COUNTRYECONOMICINDICATORSCTE CEI ON C.COUNTRY_ID = CEI.COUNTRY_ID INNER JOIN COUNTRYHDIINDICATORSCTE CHI ON C.COUNTRY_ID = CHI.COUNTRY_ID CROSS JOIN GLOBALAVERAGESCTE GA WHERE CSR.AVG_SUICIDES_NO > GA.GLOBAL_AVG_SUICIDES_NO AND CEI.AVG_GDP_PER_CAPITA > 10000 AND CHI.AVG_HDI > 0.7;
WITH GLOBALAVERAGESUICIDE AS (
  SELECT AVG(SUICIDES_NO) AS GLOBAL_AVERAGE_SUICIDES
  FROM SUICIDE_RATES
),
COUNTRYAVERAGESUICIDES AS (
  SELECT 
    COUNTRY_ID, 
    AVG(SUICIDES_NO) AS AVERAGE_SUICIDES
  FROM 
    SUICIDE_RATES
  GROUP BY 
    COUNTRY_ID
  HAVING 
    AVG(SUICIDES_NO) > (SELECT GLOBAL_AVERAGE_SUICIDES FROM GLOBALAVERAGESUICIDE)
),
COUNTRYECONOMICINDICATORS AS (
  SELECT 
    COUNTRY_ID, 
    AVG(GDP) AS AVERAGE_GDP, 
    AVG(HDI) AS AVERAGE_HDI
  FROM 
    ECONOMIC_INDICATORS
  GROUP BY 
    COUNTRY_ID
)
SELECT 
  COUNT(C.COUNTRY_ID) AS COUNT_OF_COUNTRIES
FROM 
  COUNTRIES C
JOIN 
  COUNTRYAVERAGESUICIDES CAS ON C.COUNTRY_ID = CAS.COUNTRY_ID
JOIN 
  COUNTRYECONOMICINDICATORS CEI ON C.COUNTRY_ID = CEI.COUNTRY_ID
WHERE 
  CAS.AVERAGE_SUICIDES > (SELECT GLOBAL_AVERAGE_SUICIDES FROM GLOBALAVERAGESUICIDE)
  AND CEI.AVERAGE_GDP > 10000
  AND CEI.AVERAGE_HDI > 0.7;

