SELECT SENIOR_CENTERS.CENTER_ID, SENIOR_CENTERS.NAME, SENIOR_CENTERS.PROGRAM, LOCATIONS.ADDRESS, LOCATIONS.CITY, LOCATIONS.STATE, LOCATIONS.ZIP_CODE, PHONES.PHONE_NUMBER, FAXES.FAX_NUMBER, ADMINS.ADMIN_NAME, COUNTIES.COUNTY_NAME, EMAILS.EMAIL_ADDRESS, WEBSITES.WEBSITE_URL, SENIOR_CENTERS.RATING, SENIOR_CENTERS.DATE_ESTABLISHED, SENIOR_CENTERS.LAST_UPDATED, SENIOR_CENTERS.STATUS, PROGRAMS.PROGRAM_NAME, PROGRAMS.DESCRIPTION, PROGRAMS.CATEGORY, PROGRAMS.FREQUENCY, PROGRAMS.DURATION, PROGRAMS.ELIGIBILITY, PROGRAMS.FEE, CENTER_PROGRAMS.START_DATE, CENTER_PROGRAMS.END_DATE FROM SENIOR_CENTERS INNER JOIN LOCATIONS ON SENIOR_CENTERS.LOCATION_ID = LOCATIONS.LOCATION_ID INNER JOIN ADMINS ON SENIOR_CENTERS.ADMIN_ID = ADMINS.ADMIN_ID INNER JOIN COUNTIES ON SENIOR_CENTERS.COUNTY_ID = COUNTIES.COUNTY_ID INNER JOIN PHONES ON SENIOR_CENTERS.PHONE_ID = PHONES.PHONE_ID INNER JOIN FAXES ON SENIOR_CENTERS.FAX_ID = FAXES.FAX_ID INNER JOIN EMAILS ON SENIOR_CENTERS.EMAIL_ID = EMAILS.EMAIL_ID INNER JOIN WEBSITES ON SENIOR_CENTERS.WEBSITE_ID = WEBSITES.WEBSITE_ID LEFT JOIN CENTER_PROGRAMS ON SENIOR_CENTERS.CENTER_ID = CENTER_PROGRAMS.CENTER_ID LEFT JOIN PROGRAMS ON CENTER_PROGRAMS.PROGRAM_ID = PROGRAMS.PROGRAM_ID ORDER BY SENIOR_CENTERS.RATING DESC;
WITH CENTER_DETAILS AS ( SELECT SC.CENTER_ID, SC.NAME AS CENTER_NAME, SC.PROGRAM, L.ADDRESS, L.CITY, L.STATE, L.ZIP_CODE, P.PHONE_NUMBER, F.FAX_NUMBER, A.ADMIN_NAME, C.COUNTY_NAME, E.EMAIL_ADDRESS, W.WEBSITE_URL, SC.RATING, SC.DATE_ESTABLISHED, SC.LAST_UPDATED, SC.STATUS FROM SENIOR_CENTERS SC JOIN LOCATIONS L ON SC.LOCATION_ID = L.LOCATION_ID JOIN ADMINS A ON SC.ADMIN_ID = A.ADMIN_ID JOIN PHONES P ON SC.PHONE_ID = P.PHONE_ID JOIN FAXES F ON SC.FAX_ID = F.FAX_ID JOIN EMAILS E ON SC.EMAIL_ID = E.EMAIL_ID JOIN WEBSITES W ON SC.WEBSITE_ID = W.WEBSITE_ID JOIN COUNTIES C ON SC.COUNTY_ID = C.COUNTY_ID ), PROGRAM_DETAILS AS ( SELECT CP.CENTER_ID, PR.PROGRAM_NAME, PR.DESCRIPTION AS PROGRAM_DESCRIPTION, PR.CATEGORY AS PROGRAM_CATEGORY, PR.FREQUENCY AS PROGRAM_FREQUENCY, PR.DURATION AS PROGRAM_DURATION, PR.ELIGIBILITY AS PROGRAM_ELIGIBILITY, PR.FEE AS PROGRAM_FEE, CP.START_DATE, CP.END_DATE FROM CENTER_PROGRAMS CP JOIN PROGRAMS PR ON CP.PROGRAM_ID = PR.PROGRAM_ID ) SELECT CD.CENTER_ID, CD.CENTER_NAME, CD.PROGRAM, CD.ADDRESS, CD.CITY, CD.STATE, CD.ZIP_CODE, CD.PHONE_NUMBER, CD.FAX_NUMBER, CD.ADMIN_NAME, CD.COUNTY_NAME, CD.EMAIL_ADDRESS, CD.WEBSITE_URL, CD.RATING, CD.DATE_ESTABLISHED, CD.LAST_UPDATED, CD.STATUS, PD.PROGRAM_NAME, PD.PROGRAM_DESCRIPTION, PD.PROGRAM_CATEGORY, PD.PROGRAM_FREQUENCY, PD.PROGRAM_DURATION, PD.PROGRAM_ELIGIBILITY, PD.PROGRAM_FEE, PD.START_DATE, PD.END_DATE FROM CENTER_DETAILS CD JOIN PROGRAM_DETAILS PD ON CD.CENTER_ID = PD.CENTER_ID ORDER BY CD.RATING DESC;

