SELECT P.LAST_NAME FROM PLAYERS P WHERE P.PLAYER_ID IN ( SELECT GL.PLAYER_ID FROM GAME_LOGS GL JOIN GAMES G ON GL.GAME_ID = G.GAME_ID WHERE G.SEASON = '2020-2021' GROUP BY GL.PLAYER_ID HAVING AVG(GL.POINTS) = ( SELECT MAX(AVG_POINTS) FROM ( SELECT AVG(GL2.POINTS) AS AVG_POINTS FROM GAME_LOGS GL2 JOIN GAMES G2 ON GL2.GAME_ID = G2.GAME_ID WHERE G2.SEASON = '2020-2021' GROUP BY GL2.PLAYER_ID ) ) ) ORDER BY ( SELECT AVG(GL3.POINTS) FROM GAME_LOGS GL3 JOIN GAMES G3 ON GL3.GAME_ID = G3.GAME_ID WHERE G3.SEASON = '2020-2021' AND GL3.PLAYER_ID = P.PLAYER_ID ) DESC LIMIT 10;
WITH PLAYERAVERAGE AS ( SELECT P.PLAYER_ID, P.LAST_NAME, SUM(GL.POINTS) / COUNT(DISTINCT GL.GAME_ID) AS AVERAGE_POINTS FROM PLAYERS P JOIN GAME_LOGS GL ON P.PLAYER_ID = GL.PLAYER_ID JOIN GAMES G ON GL.GAME_ID = G.GAME_ID WHERE G.SEASON = '2020-2021' GROUP BY P.PLAYER_ID, P.LAST_NAME ) SELECT LAST_NAME FROM PLAYERAVERAGE ORDER BY AVERAGE_POINTS DESC LIMIT 10;

