WITH RECORDOFTHEYEARVOTES AS ( SELECT N.ARTIST_NAME, COUNT(V.VOTE_ID) AS ROI_VOTES FROM NOMINEES N JOIN VOTES V ON N.NOMINEE_ID = V.NOMINEE_ID JOIN CATEGORIES C ON N.CATEGORY_ID = C.CATEGORY_ID WHERE C.CATEGORY_NAME = 'RECORD OF THE YEAR' GROUP BY N.ARTIST_NAME ), ALLCATEGORYVOTES AS ( SELECT N.ARTIST_NAME, COUNT(V.VOTE_ID) AS TOTAL_VOTES FROM NOMINEES N JOIN VOTES V ON N.NOMINEE_ID = V.NOMINEE_ID GROUP BY N.ARTIST_NAME ), AWARDSHOWPARTICIPATION AS ( SELECT N.ARTIST_NAME, COUNT(DISTINCT N.AWARD_SHOW_ID) AS PARTICIPATION_COUNT FROM NOMINEES N GROUP BY N.ARTIST_NAME ) SELECT ROI.ARTIST_NAME, ROI.ROI_VOTES, ACV.TOTAL_VOTES, ASP.PARTICIPATION_COUNT FROM RECORDOFTHEYEARVOTES ROI LEFT JOIN ALLCATEGORYVOTES ACV ON ROI.ARTIST_NAME = ACV.ARTIST_NAME LEFT JOIN AWARDSHOWPARTICIPATION ASP ON ROI.ARTIST_NAME = ASP.ARTIST_NAME ORDER BY ROI.ROI_VOTES DESC;
WITH RECORDOFTHEYEARVOTES AS ( SELECT N.ARTIST_NAME, COUNT(V.VOTE_ID) AS VOTES_FOR_RECORD_OF_THE_YEAR FROM NOMINEES N JOIN VOTES V ON N.NOMINEE_ID = V.NOMINEE_ID JOIN CATEGORIES C ON N.CATEGORY_ID = C.CATEGORY_ID WHERE C.CATEGORY_NAME = 'RECORD OF THE YEAR' GROUP BY N.ARTIST_NAME ), TOTALVOTES AS ( SELECT N.ARTIST_NAME, COUNT(V.VOTE_ID) AS TOTAL_VOTES FROM NOMINEES N JOIN VOTES V ON N.NOMINEE_ID = V.NOMINEE_ID GROUP BY N.ARTIST_NAME ), TOTALAWARDSHOWS AS ( SELECT N.ARTIST_NAME, COUNT(DISTINCT N.AWARD_SHOW_ID) AS TOTAL_AWARD_SHOWS FROM NOMINEES N GROUP BY N.ARTIST_NAME ) SELECT R.ARTIST_NAME, R.VOTES_FOR_RECORD_OF_THE_YEAR, T.TOTAL_VOTES, A.TOTAL_AWARD_SHOWS FROM RECORDOFTHEYEARVOTES R JOIN TOTALVOTES T ON R.ARTIST_NAME = T.ARTIST_NAME JOIN TOTALAWARDSHOWS A ON R.ARTIST_NAME = A.ARTIST_NAME ORDER BY R.VOTES_FOR_RECORD_OF_THE_YEAR DESC;

