SELECT M.TITLE, M.DIRECTOR, M.MAIN_ACTOR, (M.REVENUE_ADJ - M.BUDGET_ADJ) AS NET_PROFIT, AVG(F.RATING) AS AVERAGE_USER_RATING, COALESCE(MC.TOTAL_REACH, 0) AS TOTAL_MARKETING_REACH, COALESCE(MC.TOTAL_IMPRESSIONS, 0) AS TOTAL_MARKETING_IMPRESSIONS, COALESCE(MD.TOTAL_DISTRIBUTION_REVENUE, 0) AS TOTAL_DISTRIBUTION_REVENUE FROM MOVIES M LEFT JOIN ( SELECT MOVIE_ID, SUM(REACH) AS TOTAL_REACH, SUM(IMPRESSIONS) AS TOTAL_IMPRESSIONS FROM MARKETING_CAMPAIGNS GROUP BY MOVIE_ID ) MC ON M.MOVIE_ID = MC.MOVIE_ID LEFT JOIN ( SELECT MOVIE_ID, SUM(REVENUE) AS TOTAL_DISTRIBUTION_REVENUE FROM MOVIE_DISTRIBUTIONS GROUP BY MOVIE_ID ) MD ON M.MOVIE_ID = MD.MOVIE_ID LEFT JOIN AUDIENCE_FEEDBACK F ON M.MOVIE_ID = F.MOVIE_ID GROUP BY M.MOVIE_ID, M.TITLE, M.DIRECTOR, M.MAIN_ACTOR, M.REVENUE_ADJ, M.BUDGET_ADJ, MC.TOTAL_REACH, MC.TOTAL_IMPRESSIONS, MD.TOTAL_DISTRIBUTION_REVENUE ORDER BY NET_PROFIT DESC;
WITH MOVIEFINANCIALS AS ( SELECT MOVIE_ID, (REVENUE_ADJ - BUDGET_ADJ) AS NET_PROFIT FROM MOVIES ), USERRATINGS AS ( SELECT MOVIE_ID, AVG(RATING) AS AVG_USER_RATING FROM AUDIENCE_FEEDBACK GROUP BY MOVIE_ID ), MARKETINGSTATS AS ( SELECT MOVIE_ID, SUM(REACH) AS TOTAL_REACH, SUM(IMPRESSIONS) AS TOTAL_IMPRESSIONS FROM MARKETING_CAMPAIGNS GROUP BY MOVIE_ID ), DISTRIBUTIONSTATS AS ( SELECT MOVIE_ID, SUM(REVENUE) AS TOTAL_DISTRIBUTION_REVENUE FROM MOVIE_DISTRIBUTIONS GROUP BY MOVIE_ID ) SELECT M.TITLE, M.DIRECTOR, M.MAIN_ACTOR, MF.NET_PROFIT, UR.AVG_USER_RATING, MS.TOTAL_REACH, MS.TOTAL_IMPRESSIONS, DS.TOTAL_DISTRIBUTION_REVENUE FROM MOVIES M JOIN MOVIEFINANCIALS MF ON M.MOVIE_ID = MF.MOVIE_ID LEFT JOIN USERRATINGS UR ON M.MOVIE_ID = UR.MOVIE_ID LEFT JOIN MARKETINGSTATS MS ON M.MOVIE_ID = MS.MOVIE_ID LEFT JOIN DISTRIBUTIONSTATS DS ON M.MOVIE_ID = DS.MOVIE_ID ORDER BY MF.NET_PROFIT DESC;

