WITH LATESTTWEETVOLUMECTE AS ( SELECT TP.TREND_ID, TP.METRIC_VALUE AS TWEET_VOLUME FROM TREND_PERFORMANCE TP WHERE TP.METRIC_TYPE = 'TWEET_VOLUME' AND TP.METRIC_DATE = ( SELECT MAX(TP2.METRIC_DATE) FROM TREND_PERFORMANCE TP2 WHERE TP2.TREND_ID = TP.TREND_ID AND TP2.METRIC_TYPE = 'TWEET_VOLUME' ) ), TRENDMENTIONSCTE AS ( SELECT TM.TREND_ID, COUNT(TM.MENTION_ID) AS MENTION_COUNT FROM TREND_MENTIONS TM GROUP BY TM.TREND_ID ), TRENDSHARESCTE AS ( SELECT TS.TREND_ID, COUNT(TS.SHARE_ID) AS SHARE_COUNT FROM TREND_SHARES TS GROUP BY TS.TREND_ID ) SELECT T.TREND_ID, T.TREND_NAME, COALESCE(LTV.TWEET_VOLUME, 0) + COALESCE(TM.MENTION_COUNT, 0) + COALESCE(TS.SHARE_COUNT, 0) AS TOTAL_ACTIVITY FROM TRENDS T LEFT JOIN LATESTTWEETVOLUMECTE LTV ON T.TREND_ID = LTV.TREND_ID LEFT JOIN TRENDMENTIONSCTE TM ON T.TREND_ID = TM.TREND_ID LEFT JOIN TRENDSHARESCTE TS ON T.TREND_ID = TS.TREND_ID ORDER BY TOTAL_ACTIVITY DESC LIMIT 10;
WITH TRENDPERFORMANCECTE AS ( SELECT T.TREND_ID, T.TREND_NAME, MAX(TP.METRIC_DATE) AS LATEST_DATE, MAX(TP.METRIC_VALUE) AS LATEST_TWEET_VOLUME FROM TRENDS T INNER JOIN TREND_PERFORMANCE TP ON T.TREND_ID = TP.TREND_ID GROUP BY T.TREND_ID, T.TREND_NAME ), TRENDMENTIONSCTE AS ( SELECT TM.TREND_ID, COUNT(TM.MENTION_ID) AS TOTAL_MENTIONS FROM TREND_MENTIONS TM GROUP BY TM.TREND_ID ), TRENDSHARESCTE AS ( SELECT TS.TREND_ID, COUNT(TS.SHARE_ID) AS TOTAL_SHARES FROM TREND_SHARES TS GROUP BY TS.TREND_ID ) SELECT TP.TREND_ID, TP.TREND_NAME, (TP.LATEST_TWEET_VOLUME + COALESCE(TM.TOTAL_MENTIONS, 0) + COALESCE(TS.TOTAL_SHARES, 0)) AS TOTAL_ACTIVITY FROM TRENDPERFORMANCECTE TP LEFT JOIN TRENDMENTIONSCTE TM ON TP.TREND_ID = TM.TREND_ID LEFT JOIN TRENDSHARESCTE TS ON TP.TREND_ID = TS.TREND_ID ORDER BY TOTAL_ACTIVITY DESC LIMIT 10;

