WITH TOPPIS AS (
    SELECT
        G.CONTACT_PI_ID,
        SUM(G.TOTAL_DOLLARS_AWARDED) AS TOTAL_PI_AWARDS
    FROM GRANTS G
    GROUP BY G.CONTACT_PI_ID
    ORDER BY TOTAL_PI_AWARDS DESC
    LIMIT 10
),
INSTITUTIONTOTALS AS (
    SELECT
        G.INSTITUTION_ID,
        SUM(G.TOTAL_DOLLARS_AWARDED) AS TOTAL_INSTITUTION_AWARDS
    FROM GRANTS G
    INNER JOIN TOPPIS TPI ON G.CONTACT_PI_ID = TPI.CONTACT_PI_ID
    GROUP BY G.INSTITUTION_ID
)
SELECT
    I.INSTITUTION_NAME,
    IT.TOTAL_INSTITUTION_AWARDS
FROM INSTITUTIONS I
INNER JOIN INSTITUTIONTOTALS IT ON I.INSTITUTION_ID = IT.INSTITUTION_ID
ORDER BY IT.TOTAL_INSTITUTION_AWARDS DESC;
WITH TOPPRINCIPALINVESTIGATORS AS ( SELECT P.PI_ID, P.PI_NAME, SUM(G.TOTAL_DOLLARS_AWARDED) AS TOTAL_GRANTS_RECEIVED FROM GRANTS G INNER JOIN PRINCIPAL_INVESTIGATORS P ON G.CONTACT_PI_ID = P.PI_ID GROUP BY P.PI_ID, P.PI_NAME ORDER BY TOTAL_GRANTS_RECEIVED DESC LIMIT 10 ), INSTITUTIONSWITHTOPPIS AS ( SELECT G.INSTITUTION_ID, I.INSTITUTION_NAME, SUM(G.TOTAL_DOLLARS_AWARDED) AS TOTAL_AWARDS FROM GRANTS G INNER JOIN INSTITUTIONS I ON G.INSTITUTION_ID = I.INSTITUTION_ID INNER JOIN PRINCIPAL_INVESTIGATORS P ON G.CONTACT_PI_ID = P.PI_ID WHERE P.PI_ID IN (SELECT PI_ID FROM TOPPRINCIPALINVESTIGATORS) GROUP BY G.INSTITUTION_ID, I.INSTITUTION_NAME ) SELECT I.INSTITUTION_NAME, I.TOTAL_AWARDS FROM INSTITUTIONSWITHTOPPIS I ORDER BY I.TOTAL_AWARDS DESC;

