WITH EXPERIMENTVERSIONS AS ( SELECT EXPERIMENT_ID, COUNT(EXPERIMENT_VERSION_ID) AS VERSION_COUNT FROM EXPERIMENT_VERSIONS GROUP BY EXPERIMENT_ID ), TOTALDELTAPH AS ( SELECT EXPERIMENT_ID, SUM(DELTA_PH_VALUE) AS TOTAL_DELTA_PH FROM DELTA_PH GROUP BY EXPERIMENT_ID ) SELECT AT.EXPERIMENT_ID, AT.ANIMAL_TYPE_NAME, AT.TYPE_DESCRIPTION, COALESCE(EV.VERSION_COUNT, 0) AS VERSION_COUNT, COALESCE(DPH.TOTAL_DELTA_PH, 0) AS TOTAL_DELTA_PH FROM ANIMAL_TYPES AT LEFT JOIN EXPERIMENTVERSIONS EV ON AT.EXPERIMENT_ID = EV.EXPERIMENT_ID LEFT JOIN TOTALDELTAPH DPH ON AT.EXPERIMENT_ID = DPH.EXPERIMENT_ID ORDER BY AT.EXPERIMENT_ID, AT.ANIMAL_TYPE_NAME;

