WITH BOTTOM_MEASUREMENTS AS ( SELECT DISTINCT UM.USER_ID, M.SIZE_ID FROM USER_MEASUREMENTS UM JOIN MEASUREMENTS M ON UM.MEASUREMENT_ID = M.MEASUREMENT_ID JOIN SIZES S ON M.SIZE_ID = S.SIZE_ID JOIN CATEGORIES CAT ON S.CATEGORY_ID = CAT.CATEGORY_ID WHERE CAT.CATEGORY_NAME = 'BOTTOMS' ), CONVERSION_RULES_WITH_FORMULA AS ( SELECT DISTINCT CR.CATEGORY_ID FROM CONVERSION_RULES CR WHERE CR.CONVERSION_FORMULA IS NOT NULL ), ELIGIBLE_USERS AS ( SELECT BM.USER_ID, BM.SIZE_ID FROM BOTTOM_MEASUREMENTS BM JOIN CONVERSION_RULES_WITH_FORMULA CRF ON BM.SIZE_ID IN ( SELECT S.SIZE_ID FROM SIZES S WHERE S.CATEGORY_ID = CRF.CATEGORY_ID ) ) SELECT EU.USER_ID, S.SIZE_NAME AS RECOMMENDED_SIZE_NAME FROM ELIGIBLE_USERS EU JOIN SIZES S ON EU.SIZE_ID = S.SIZE_ID JOIN RECOMMENDED_SIZES RS ON RS.USER_ID = EU.USER_ID ORDER BY RS.USER_ID;

