WITH ACCESSEDCHANGES AS ( SELECT CHANGE_ID FROM ACCESS_LOGS WHERE ACCESS_DATE = '2020-09-21' ), DOCUMENTCOUNTS AS ( SELECT D.DOCUMENT_NAME, COUNT(*) AS TOTAL_COUNT, SUM(CASE WHEN CDM.MAPPING_TYPE = 'ONE-TO-ONE' THEN 1 ELSE 0 END) AS ONE_TO_ONE_COUNT, SUM(CASE WHEN CDM.MAPPING_TYPE = 'ONE-TO-MANY' THEN 1 ELSE 0 END) AS ONE_TO_MANY_COUNT FROM DOCUMENTS D JOIN CHANGE_DOCUMENT_MAPPING CDM ON D.DOCUMENT_ID = CDM.DOCUMENT_ID JOIN ACCESSEDCHANGES AC ON CDM.CHANGE_ID = AC.CHANGE_ID GROUP BY D.DOCUMENT_NAME ), MAPPINGDOMINANCE AS ( SELECT DOCUMENT_NAME, CASE WHEN ONE_TO_ONE_COUNT > ONE_TO_MANY_COUNT THEN 'ONE-TO-ONE DOMINANT' WHEN ONE_TO_MANY_COUNT > ONE_TO_ONE_COUNT THEN 'ONE-TO-MANY DOMINANT' ELSE 'EQUAL MAPPING TYPES' END AS MAPPING_TYPE_DOMINANCE FROM DOCUMENTCOUNTS ) SELECT DC.DOCUMENT_NAME, DC.TOTAL_COUNT, DC.ONE_TO_ONE_COUNT, DC.ONE_TO_MANY_COUNT, MD.MAPPING_TYPE_DOMINANCE FROM DOCUMENTCOUNTS DC JOIN MAPPINGDOMINANCE MD ON DC.DOCUMENT_NAME = MD.DOCUMENT_NAME ORDER BY DC.TOTAL_COUNT DESC;
WITH CHANGEACCESSCTE AS ( SELECT CR.CHANGE_ID, CR.CHANGE_NUMBER, CR.STATUS, CR.PRIORITY, CR.CHANGE_TYPE, CR.AUTHOR_ID, U.USER_NAME AS CHANGE_AUTHOR_NAME FROM CHANGE_REQUESTS CR JOIN ACCESS_LOGS A ON CR.CHANGE_ID = A.CHANGE_ID JOIN USERS U ON CR.AUTHOR_ID = U.USER_ID WHERE A.ACCESS_DATE = '2020-09-21' AND A.ACCESS_TYPE = 'VIEW' ), DOCUMENTMAPPINGCTE AS ( SELECT CAD.DOCUMENT_ID, D.DOCUMENT_NAME, CAD.MAPPING_TYPE FROM CHANGE_DOCUMENT_MAPPING CAD JOIN DOCUMENTS D ON CAD.DOCUMENT_ID = D.DOCUMENT_ID ), FILTEREDDOCUMENTS AS ( SELECT DTCTE.DOCUMENT_ID, DTCTE.DOCUMENT_NAME, DTCTE.MAPPING_TYPE FROM DOCUMENTMAPPINGCTE DTCTE JOIN CHANGEACCESSCTE CARCTE ON DTCTE.DOCUMENT_ID IN ( SELECT DOCUMENT_ID FROM CHANGE_DOCUMENT_MAPPING WHERE CHANGE_ID = CARCTE.CHANGE_ID ) ) SELECT DOCUMENT_NAME, COUNT(*) AS DOCUMENT_COUNT, SUM(CASE WHEN MAPPING_TYPE = 'ONE-TO-ONE' THEN 1 ELSE 0 END) AS ONE_TO_ONE_COUNT, SUM(CASE WHEN MAPPING_TYPE = 'ONE-TO-MANY' THEN 1 ELSE 0 END) AS ONE_TO_MANY_COUNT, CASE WHEN SUM(CASE WHEN MAPPING_TYPE = 'ONE-TO-ONE' THEN 1 ELSE 0 END) > SUM(CASE WHEN MAPPING_TYPE = 'ONE-TO-MANY' THEN 1 ELSE 0 END) THEN 'ONE-TO-ONE' WHEN SUM(CASE WHEN MAPPING_TYPE = 'ONE-TO-ONE' THEN 1 ELSE 0 END) < SUM(CASE WHEN MAPPING_TYPE = 'ONE-TO-MANY' THEN 1 ELSE 0 END) THEN 'ONE-TO-MANY' ELSE 'EQUAL' END AS DOMINANT_MAPPING_TYPE FROM FILTEREDDOCUMENTS GROUP BY DOCUMENT_NAME ORDER BY DOCUMENT_COUNT DESC;

