WITH TOPRESEARCHERS AS ( SELECT R.RESEARCHER_ID FROM RESEARCHERS R JOIN PUBLICATION_AUTHORS PA ON R.RESEARCHER_ID = PA.RESEARCHER_ID GROUP BY R.RESEARCHER_ID ORDER BY COUNT(PA.PUBLICATION_ID) DESC LIMIT 5 ), TOPTEAMS AS ( SELECT RT.TEAM_ID FROM RESEARCH_TEAMS RT JOIN TEAM_MEMBERS TM ON RT.TEAM_ID = TM.TEAM_ID JOIN PUBLICATION_AUTHORS PA ON TM.RESEARCHER_ID = PA.RESEARCHER_ID GROUP BY RT.TEAM_ID ORDER BY COUNT(PA.PUBLICATION_ID) DESC LIMIT 5 ), TEAMPUBLICATIONS AS ( SELECT DISTINCT MP.METEORITE_ID, MP.PUBLICATION_ID FROM METEORITE_PUBLICATIONS MP JOIN PUBLICATION_AUTHORS PA ON MP.PUBLICATION_ID = PA.PUBLICATION_ID JOIN TEAM_MEMBERS TM ON PA.RESEARCHER_ID = TM.RESEARCHER_ID WHERE TM.TEAM_ID IN (SELECT TEAM_ID FROM TOPTEAMS) ), RESEARCHERPUBLICATIONS AS ( SELECT DISTINCT MP.METEORITE_ID, MP.PUBLICATION_ID FROM METEORITE_PUBLICATIONS MP JOIN PUBLICATION_AUTHORS PA ON MP.PUBLICATION_ID = PA.PUBLICATION_ID WHERE PA.RESEARCHER_ID IN (SELECT RESEARCHER_ID FROM TOPRESEARCHERS) ), COMBINEDPUBLICATIONS AS ( SELECT METEORITE_ID, PUBLICATION_ID FROM TEAMPUBLICATIONS UNION SELECT METEORITE_ID, PUBLICATION_ID FROM RESEARCHERPUBLICATIONS ), METEORITEPUBLICATIONCOUNTS AS ( SELECT METEORITE_ID, COUNT(PUBLICATION_ID) AS PUB_COUNT FROM COMBINEDPUBLICATIONS GROUP BY METEORITE_ID ) SELECT METEORITE_ID FROM METEORITEPUBLICATIONCOUNTS ORDER BY PUB_COUNT DESC LIMIT 1;

