WITH OWNERCAMPAIGNS AS ( SELECT O.OWNER_NAME, C.CAMPAIGN_ID, C.START_DATE, C.OWNER_ID, C.STATUS_ID FROM CAMPAIGNS C INNER JOIN OWNERS O ON C.OWNER_ID = O.OWNER_ID WHERE C.OWNER_ID IN (7, 19, 25) AND C.STATUS_ID > 2 ), BUDGETSUMMARY AS ( SELECT CB.CAMPAIGN_ID, SUM(CB.SPENT_AMOUNT) AS TOTALBUDGETSPENT, AVG(CB.SPENT_AMOUNT) AS AVERAGEBUDGETSPENT FROM CAMPAIGN_BUDGETS CB GROUP BY CB.CAMPAIGN_ID ), PERFORMANCESUMMARY AS ( SELECT CP.CAMPAIGN_ID, SUM(CASE WHEN CP.METRIC_NAME = 'CLICKS' THEN CP.VALUE ELSE 0 END) AS TOTALCLICKS, SUM(CASE WHEN CP.METRIC_NAME = 'IMPRESSIONS' THEN CP.VALUE ELSE 0 END) AS TOTALIMPRESSIONS FROM CAMPAIGN_PERFORMANCE CP GROUP BY CP.CAMPAIGN_ID ) SELECT OC.OWNER_NAME, OC.CAMPAIGN_ID, OC.START_DATE, BS.TOTALBUDGETSPENT, BS.AVERAGEBUDGETSPENT, PS.TOTALCLICKS, PS.TOTALIMPRESSIONS FROM OWNERCAMPAIGNS OC INNER JOIN BUDGETSUMMARY BS ON OC.CAMPAIGN_ID = BS.CAMPAIGN_ID INNER JOIN PERFORMANCESUMMARY PS ON OC.CAMPAIGN_ID = PS.CAMPAIGN_ID ORDER BY OC.OWNER_NAME, OC.START_DATE;

