WITH CREDITSCOREDATES AS ( SELECT BORROWER_ID, CREDIT_SCORE_DATE FROM CREDIT_SCORE ), FILTEREDCOLLECTIONS AS ( SELECT C.APPLICATION_ID, C.COLLECTION_AMOUNT FROM COLLECTIONS C JOIN CREDITSCOREDATES CSD ON C.APPLICATION_ID = CSD.BORROWER_ID WHERE C.COLLECTION_DATE > CSD.CREDIT_SCORE_DATE ), FILTEREDPAYMENTS AS ( SELECT R.APPLICATION_ID, R.PAYMENT_AMOUNT FROM REPAYMENT_SCHEDULE R JOIN CREDITSCOREDATES CSD ON R.APPLICATION_ID = CSD.BORROWER_ID WHERE R.PAYMENT_DATE > CSD.CREDIT_SCORE_DATE ), COLLECTIONSUMS AS ( SELECT APPLICATION_ID, SUM(COLLECTION_AMOUNT) AS TOTAL_COLLECTIONS FROM FILTEREDCOLLECTIONS GROUP BY APPLICATION_ID ), PAYMENTSUMS AS ( SELECT APPLICATION_ID, SUM(PAYMENT_AMOUNT) AS TOTAL_PAYMENTS FROM FILTEREDPAYMENTS GROUP BY APPLICATION_ID ) SELECT COALESCE(CS.APPLICATION_ID, PS.APPLICATION_ID) AS APPLICATION_ID, COALESCE(CS.TOTAL_COLLECTIONS, 0) - COALESCE(PS.TOTAL_PAYMENTS, 0) AS COLLECTION_PAYMENT_DIFFERENCE FROM COLLECTIONSUMS CS FULL OUTER JOIN PAYMENTSUMS PS ON CS.APPLICATION_ID = PS.APPLICATION_ID ORDER BY APPLICATION_ID;

