SELECT 
  I.NAME
FROM 
  INVENTORIES I
JOIN 
  (SELECT 
     INVENTORY_ID, 
     SUM(DIRECTORY_SIZE) AS TOTAL_DIRECTORY_SIZE
   FROM 
     DIRECTORIES
   GROUP BY 
     INVENTORY_ID
   HAVING 
     SUM(DIRECTORY_SIZE) > 0) D ON I.INVENTORY_ID = D.INVENTORY_ID
JOIN 
  (SELECT 
     INVENTORY_ID, 
     SUM(FILE_SIZE) AS TOTAL_DATA_FILE_SIZE
   FROM 
     DATA_FILES
   GROUP BY 
     INVENTORY_ID
   HAVING 
     SUM(FILE_SIZE) > 0) F ON I.INVENTORY_ID = F.INVENTORY_ID
ORDER BY 
  D.TOTAL_DIRECTORY_SIZE DESC;
SELECT I.NAME FROM INVENTORIES I WHERE EXISTS ( SELECT 1 FROM DIRECTORIES D WHERE D.INVENTORY_ID = I.INVENTORY_ID GROUP BY D.INVENTORY_ID HAVING SUM(D.DIRECTORY_SIZE) > 0 ) AND EXISTS ( SELECT 1 FROM DATA_FILES DF WHERE DF.INVENTORY_ID = I.INVENTORY_ID GROUP BY DF.INVENTORY_ID HAVING SUM(DF.FILE_SIZE) > 0 ) ORDER BY ( SELECT SUM(D.DIRECTORY_SIZE) FROM DIRECTORIES D WHERE D.INVENTORY_ID = I.INVENTORY_ID ) DESC;

