SELECT 
    PM.INDIVIDUAL_ID,
    (PM.FEAR_SCORE + PM.RELIGIOSITY_SCORE + PM.HAPPINESS_SCORE + PM.ANXIETY_SCORE + PM.DEPRESSION_SCORE + PM.STRESS_SCORE + PM.SELFESTEEM_SCORE + PM.RESILIENCE_SCORE) / 8.0 AS AVERAGE_PSYCHOLOGICAL_SCORE,
    CASE 
        WHEN LC.HEALTHY_LIFESTYLE = 'YES' THEN 1
        WHEN LC.HEALTHY_LIFESTYLE = 'NO' THEN 0
    END AS HEALTHY_LIFESTYLE_SCORE
FROM 
    PSYCHOLOGICAL_METRICS PM
JOIN 
    LIFESTYLE_CHOICES LC ON PM.INDIVIDUAL_ID = LC.INDIVIDUAL_ID
ORDER BY 
    HEALTHY_LIFESTYLE_SCORE DESC, 
    AVERAGE_PSYCHOLOGICAL_SCORE DESC;
WITH PSYCHOLOGICAL_AVERAGES AS ( SELECT INDIVIDUAL_ID, (FEAR_SCORE + RELIGIOSITY_SCORE + HAPPINESS_SCORE + ANXIETY_SCORE + DEPRESSION_SCORE + STRESS_SCORE + SELFESTEEM_SCORE + RESILIENCE_SCORE) / 8.0 AS AVERAGE_PSYCHOLOGICAL_SCORE FROM PSYCHOLOGICAL_METRICS ), HEALTHY_LIFESTYLE_SCORES AS ( SELECT INDIVIDUAL_ID, CASE WHEN HEALTHY_LIFESTYLE = 'YES' THEN 1 WHEN HEALTHY_LIFESTYLE = 'NO' THEN 0 END AS HEALTHY_LIFESTYLE_SCORE FROM LIFESTYLE_CHOICES ) SELECT PA.INDIVIDUAL_ID, PA.AVERAGE_PSYCHOLOGICAL_SCORE, HLS.HEALTHY_LIFESTYLE_SCORE FROM PSYCHOLOGICAL_AVERAGES PA JOIN HEALTHY_LIFESTYLE_SCORES HLS ON PA.INDIVIDUAL_ID = HLS.INDIVIDUAL_ID ORDER BY HLS.HEALTHY_LIFESTYLE_SCORE DESC, PA.AVERAGE_PSYCHOLOGICAL_SCORE DESC;

