SELECT 
    P.PARTICIPANT_ID,
    ((SUM(PM.AVERAGE_PARTIAL_SCORE) / COUNT(PM.PARTICIPANT_ID)) +
     (SUM(PM.AVERAGE_LATENCY) / COUNT(PM.PARTICIPANT_ID)) +
     (SUM(PM.AVERAGE_ACCURACY) / COUNT(PM.PARTICIPANT_ID))) / 3 AS OVERALL_PERFORMANCE
FROM PARTICIPANTS P
JOIN PERFORMANCE_METRICS PM ON P.PARTICIPANT_ID = PM.PARTICIPANT_ID
GROUP BY P.PARTICIPANT_ID;
WITH PARTICIPANTAVERAGEMETRICS AS ( SELECT P.PARTICIPANT_ID, AVG(PM.AVERAGE_PARTIAL_SCORE) AS AVERAGE_PARTIAL_SCORE, AVG(PM.AVERAGE_LATENCY) AS AVERAGE_LATENCY, AVG(PM.AVERAGE_ACCURACY) AS AVERAGE_ACCURACY FROM PARTICIPANTS P INNER JOIN PERFORMANCE_METRICS PM ON P.PARTICIPANT_ID = PM.PARTICIPANT_ID GROUP BY P.PARTICIPANT_ID ) SELECT PARTICIPANT_ID, (AVERAGE_PARTIAL_SCORE + AVERAGE_LATENCY + AVERAGE_ACCURACY) / 3 AS OVERALL_PERFORMANCE FROM PARTICIPANTAVERAGEMETRICS;

