WITH LATESTSTOCKPRICES AS ( SELECT SYMBOL, MAX(DATE_RECORDED) AS MAX_DATE, CLOSE_PRICE FROM STOCK_PRICES GROUP BY SYMBOL, CLOSE_PRICE ), USERPORTFOLIO AS ( SELECT U.USER_ID, U.USER_NAME, U.SUBSCRIPTION_TIER, P.SYMBOL, P.QUANTITY, P.PURCHASE_PRICE, P.QUANTITY * (LSP.CLOSE_PRICE - P.PURCHASE_PRICE) AS GAIN FROM USERS U JOIN PORTFOLIO P ON U.USER_ID = P.USER_ID JOIN LATESTSTOCKPRICES LSP ON P.SYMBOL = LSP.SYMBOL ), USERGAINS AS ( SELECT USER_ID, SUBSCRIPTION_TIER, SUM(GAIN) AS TOTAL_GAIN FROM USERPORTFOLIO GROUP BY USER_ID, SUBSCRIPTION_TIER ) SELECT MAX(TOTAL_GAIN) AS MAX_TOTAL_GAIN FROM USERGAINS;
WITH STOCKPRICELATEST AS ( SELECT SYMBOL, CLOSE_PRICE FROM STOCK_PRICES SP1 WHERE DATE_RECORDED = ( SELECT MAX(DATE_RECORDED) FROM STOCK_PRICES SP2 WHERE SP2.SYMBOL = SP1.SYMBOL ) ), PORTFOLIOWITHGAIN AS ( SELECT U.USER_ID, U.SUBSCRIPTION_TIER, SUM(P.QUANTITY * (SPL.CLOSE_PRICE - P.PURCHASE_PRICE)) AS TOTAL_GAIN FROM USERS U JOIN PORTFOLIO P ON U.USER_ID = P.USER_ID JOIN STOCKPRICELATEST SPL ON P.SYMBOL = SPL.SYMBOL GROUP BY U.USER_ID, U.SUBSCRIPTION_TIER ) SELECT MAX(TOTAL_GAIN) AS MAX_TOTAL_GAIN FROM PORTFOLIOWITHGAIN;

