WITH USERACTIVITY AS ( SELECT U.USER_ID, COUNT(UA.ACTIVITY_ID) AS TOTAL_ACTIVITIES, SUM(UA.ACTIVITY_VALUE) AS TOTAL_ACTIVITY_VALUE, MAX(UA.ACTIVITY_DATE) AS LAST_ACTIVITY_DATE FROM USERS U LEFT JOIN USER_ACTIVITY UA ON U.USER_ID = UA.USER_ID GROUP BY U.USER_ID ), USERCOMMENDATIONS AS ( SELECT C.USER_ID, COUNT(C.COMMENDATION_ID) AS TOTAL_COMMENDATIONS, MAX(C.CREATED_AT) AS LAST_COMMENDATION_DATE, SUM(CASE WHEN C.IS_FLAGGED = 1 THEN 1 ELSE 0 END) AS FLAGGED_COMMENDATIONS FROM COMMENDATIONS C GROUP BY C.USER_ID ) SELECT U.USER_ID, U.USERNAME, COALESCE(UA.TOTAL_ACTIVITIES, 0) AS TOTAL_ACTIVITIES, COALESCE(UA.TOTAL_ACTIVITY_VALUE, 0) AS TOTAL_ACTIVITY_VALUE, COALESCE(UC.TOTAL_COMMENDATIONS, 0) AS TOTAL_COMMENDATIONS, UA.LAST_ACTIVITY_DATE, UC.LAST_COMMENDATION_DATE, COALESCE(UC.FLAGGED_COMMENDATIONS, 0) AS FLAGGED_COMMENDATIONS FROM USERS U LEFT JOIN USERACTIVITY UA ON U.USER_ID = UA.USER_ID LEFT JOIN USERCOMMENDATIONS UC ON U.USER_ID = UC.USER_ID ORDER BY TOTAL_ACTIVITIES DESC, TOTAL_ACTIVITY_VALUE DESC, TOTAL_COMMENDATIONS DESC, FLAGGED_COMMENDATIONS ASC LIMIT 10;
WITH USERENGAGEMENTCTE AS (
    SELECT 
        U.USER_ID,
        U.USERNAME,
        COUNT(UA.ACTIVITY_ID) AS TOTAL_ACTIVITIES,
        SUM(UA.ACTIVITY_VALUE) AS TOTAL_ACTIVITY_VALUE,
        MAX(UA.ACTIVITY_DATE) AS LAST_ACTIVITY_DATE
    FROM 
        USERS U
    LEFT JOIN 
        USER_ACTIVITY UA ON U.USER_ID = UA.USER_ID
    GROUP BY 
        U.USER_ID, U.USERNAME
),
USERCOMMENDATIONSTATSCTE AS (
    SELECT 
        U.USER_ID,
        U.USERNAME,
        COUNT(C.COMMENDATION_ID) AS TOTAL_COMMENDATIONS,
        MAX(C.CREATED_AT) AS LAST_COMMENDATION_DATE,
        SUM(CASE WHEN C.IS_FLAGGED = 1 THEN 1 ELSE 0 END) AS FLAGGED_COMMENDATIONS
    FROM 
        USERS U
    LEFT JOIN 
        COMMENDATIONS C ON U.USER_ID = C.USER_ID
    GROUP BY 
        U.USER_ID, U.USERNAME
)
SELECT 
    UE.USER_ID,
    UE.USERNAME,
    UE.TOTAL_ACTIVITIES,
    UE.TOTAL_ACTIVITY_VALUE,
    UC.TOTAL_COMMENDATIONS,
    UE.LAST_ACTIVITY_DATE,
    UC.LAST_COMMENDATION_DATE,
    UC.FLAGGED_COMMENDATIONS
FROM 
    USERENGAGEMENTCTE UE
LEFT JOIN 
    USERCOMMENDATIONSTATSCTE UC ON UE.USER_ID = UC.USER_ID
ORDER BY 
    UE.TOTAL_ACTIVITIES DESC, 
    UE.TOTAL_ACTIVITY_VALUE DESC, 
    UC.TOTAL_COMMENDATIONS DESC, 
    UC.FLAGGED_COMMENDATIONS ASC
LIMIT 10;

