SELECT GE.NAME AS ENTITY_NAME, ET.HIERARCHY_LEVEL, SUM(SD.STATISTIC) AS CUMULATIVE_STATISTIC, AVG(SD.STATISTIC) AS AVERAGE_STATISTIC FROM GEOGRAPHICAL_ENTITIES GE INNER JOIN ENTITY_TYPES ET ON GE.TYPE = ET.TYPE_ID LEFT JOIN STATISTICAL_DATA SD ON GE.FIPS = SD.FIPS GROUP BY GE.FIPS, GE.NAME, ET.HIERARCHY_LEVEL ORDER BY ET.HIERARCHY_LEVEL, GE.NAME;
WITH HIERARCHICALENTITIES AS ( SELECT GE.NAME, ET.HIERARCHY_LEVEL, GE.FIPS FROM GEOGRAPHICAL_ENTITIES GE JOIN ENTITY_TYPES ET ON GE.TYPE = ET.TYPE_ID ), AGGREGATEDSTATS AS ( SELECT FIPS, SUM(STATISTIC) AS TOTAL_STATISTIC, AVG(STATISTIC) AS MEAN_STATISTIC FROM STATISTICAL_DATA GROUP BY FIPS ) SELECT HE.NAME, HE.HIERARCHY_LEVEL, AST.TOTAL_STATISTIC AS CUMULATIVE_STATISTIC, AST.MEAN_STATISTIC AS AVERAGE_STATISTIC FROM HIERARCHICALENTITIES HE JOIN AGGREGATEDSTATS AST ON HE.FIPS = AST.FIPS ORDER BY HE.HIERARCHY_LEVEL, HE.NAME;

