WITH CLIENT_AVG_RATINGS AS ( SELECT C.CLIENT_ID, AVG(GR.RATING) AS AVG_RATING FROM GAMES G JOIN GAME_REVIEWS GR ON G.GAME_ID = GR.GAME_ID JOIN CLIENTS C ON G.GAME_PROVIDER = C.CLIENT_ID GROUP BY C.CLIENT_ID HAVING AVG(GR.RATING) >= 4.5 ), GAMES_BY_TOP_CLIENTS AS ( SELECT G.GAME_ID FROM GAMES G JOIN CLIENT_AVG_RATINGS CAR ON G.GAME_PROVIDER = CAR.CLIENT_ID ), USERS_WITH_TOP_GAME_BETS AS ( SELECT DISTINCT B.USER_ID FROM BETS B JOIN GAMES_BY_TOP_CLIENTS GBC ON B.GAME_ID = GBC.GAME_ID ) SELECT USER_ID FROM USERS_WITH_TOP_GAME_BETS ORDER BY USER_ID;

