SELECT FM.MARKET_NAME, ( (SELECT AVG(MR.REVIEW_RATING) FROM MARKET_REVIEWS MR WHERE MR.MARKET_ID = FM.MARKET_ID) * (SELECT COUNT(V.VENDOR_ID) FROM VENDORS V WHERE V.MARKET_ID = FM.MARKET_ID) * (SELECT SUM(MP.NUMBER_OF_CUSTOMERS) FROM MARKET_PARTICIPATION MP WHERE MP.MARKET_ID = FM.MARKET_ID) ) / 1000000 AS MARKET_SCORE FROM FARMERS_MARKETS FM ORDER BY MARKET_SCORE DESC;
WITH MARKETREVIEWAVERAGES AS ( SELECT MARKET_ID, AVG(REVIEW_RATING) AS AVG_REVIEW_SCORE FROM MARKET_REVIEWS GROUP BY MARKET_ID ), VENDORCOUNTS AS ( SELECT MARKET_ID, COUNT(VENDOR_ID) AS TOTAL_VENDORS FROM VENDORS GROUP BY MARKET_ID ), CUSTOMERTOTALS AS ( SELECT MARKET_ID, SUM(NUMBER_OF_CUSTOMERS) AS TOTAL_VISITORS FROM MARKET_PARTICIPATION GROUP BY MARKET_ID ), MARKETCALCULATIONS AS ( SELECT MRA.MARKET_ID, MRA.AVG_REVIEW_SCORE, VC.TOTAL_VENDORS, CT.TOTAL_VISITORS, (MRA.AVG_REVIEW_SCORE * VC.TOTAL_VENDORS * CT.TOTAL_VISITORS) / 1000000 AS CALCULATED_SCORE FROM MARKETREVIEWAVERAGES MRA INNER JOIN VENDORCOUNTS VC ON MRA.MARKET_ID = VC.MARKET_ID INNER JOIN CUSTOMERTOTALS CT ON MRA.MARKET_ID = CT.MARKET_ID ) SELECT FM.MARKET_NAME, MC.CALCULATED_SCORE AS MARKET_SCORE FROM FARMERS_MARKETS FM INNER JOIN MARKETCALCULATIONS MC ON FM.MARKET_ID = MC.MARKET_ID ORDER BY MC.CALCULATED_SCORE DESC;

