WITH ENGAGEMENTMETRICS AS ( SELECT T.USER_ID, SUM(E.LIKES) AS TOTAL_LIKES, SUM(E.RETWEETS) AS TOTAL_RETWEETS, SUM(E.REPLIES) AS TOTAL_REPLIES FROM ENGAGEMENT E JOIN TWEETS T ON E.TWEET_ID = T.TWEET_ID GROUP BY T.USER_ID ) SELECT I.INFLUENCER_ID FROM INFLUENCERS I JOIN ENGAGEMENTMETRICS EM ON I.USER_ID = EM.USER_ID JOIN ANALYTICS A ON I.USER_ID = A.USER_ID WHERE EM.TOTAL_LIKES > EM.TOTAL_RETWEETS AND EM.TOTAL_REPLIES > EM.TOTAL_RETWEETS AND A.FOLLOWERS > 1000 ORDER BY EM.TOTAL_LIKES DESC;
WITH ENGAGEMENTSUMMARY AS ( SELECT I.INFLUENCER_ID, SUM(E.LIKES) AS TOTAL_LIKES, SUM(E.RETWEETS) AS TOTAL_RETWEETS, SUM(E.REPLIES) AS TOTAL_REPLIES FROM INFLUENCERS I JOIN TWEETS T ON I.USER_ID = T.USER_ID JOIN ENGAGEMENT E ON T.TWEET_ID = E.TWEET_ID GROUP BY I.INFLUENCER_ID ), FOLLOWERSUMMARY AS ( SELECT A.USER_ID AS INFLUENCER_ID, A.FOLLOWERS AS TOTAL_FOLLOWERS FROM ANALYTICS A JOIN INFLUENCERS I ON A.USER_ID = I.USER_ID ) SELECT ES.INFLUENCER_ID FROM ENGAGEMENTSUMMARY ES JOIN FOLLOWERSUMMARY FS ON ES.INFLUENCER_ID = FS.INFLUENCER_ID WHERE ES.TOTAL_LIKES > ES.TOTAL_RETWEETS AND ES.TOTAL_REPLIES > ES.TOTAL_RETWEETS AND FS.TOTAL_FOLLOWERS > 1000 ORDER BY ES.TOTAL_LIKES DESC;

