SELECT D.DEVICE_ID, U.USER_NAME, U.DEPARTMENT, COUNT(DM.MOVEMENT_ID) AS TOTAL_MOVEMENT_COUNT, AVG(SS.SIGNAL_VALUE) AS AVERAGE_SIGNAL_VALUE, MAX(AL.ACCESS_DATE) AS LAST_ACCESS_DATE FROM DEVICES D INNER JOIN DEVICE_MOVEMENTS DM ON D.DEVICE_ID = DM.DEVICE_ID INNER JOIN LOCATIONS L ON DM.LOCATION_ID = L.LOCATION_ID LEFT JOIN ACCESS_LOGS AL ON D.DEVICE_ID = AL.DEVICE_ID LEFT JOIN USERS U ON AL.USER_ID = U.USER_ID LEFT JOIN SIGNAL_STRENGTHS SS ON D.DEVICE_ID = SS.DEVICE_ID WHERE D.DEVICE_TYPE = 'LAPTOP' AND L.LOCATION_NAME = 'FLOOR 1, ROOM 101' GROUP BY D.DEVICE_ID, U.USER_NAME, U.DEPARTMENT;
WITH FLOOR1ROOM101DEVICES AS ( SELECT D.DEVICE_ID FROM DEVICES D JOIN LOCATIONS L ON D.LOCATION_ID = L.LOCATION_ID WHERE L.LOCATION_NAME = 'FLOOR 1, ROOM 101' AND D.DEVICE_TYPE = 'LAPTOP' ), DEVICEMOVEMENTS AS ( SELECT DEVICE_ID, COUNT(*) AS MOVEMENT_COUNT FROM DEVICE_MOVEMENTS WHERE DEVICE_ID IN (SELECT DEVICE_ID FROM FLOOR1ROOM101DEVICES) GROUP BY DEVICE_ID ), AVERAGESIGNALSTRENGTH AS ( SELECT DEVICE_ID, AVG(SIGNAL_VALUE) AS AVG_SIGNAL_STRENGTH FROM SIGNAL_STRENGTHS WHERE DEVICE_ID IN (SELECT DEVICE_ID FROM FLOOR1ROOM101DEVICES) GROUP BY DEVICE_ID ), LASTACCESS AS ( SELECT A.DEVICE_ID, U.USER_NAME, U.DEPARTMENT, MAX(A.ACCESS_DATE) AS LAST_ACCESS_DATE FROM ACCESS_LOGS A JOIN USERS U ON A.USER_ID = U.USER_ID WHERE A.DEVICE_ID IN (SELECT DEVICE_ID FROM FLOOR1ROOM101DEVICES) GROUP BY A.DEVICE_ID, U.USER_NAME, U.DEPARTMENT ) SELECT D.DEVICE_ID, LA.USER_NAME, LA.DEPARTMENT, DM.MOVEMENT_COUNT, ASS.AVG_SIGNAL_STRENGTH, LA.LAST_ACCESS_DATE FROM FLOOR1ROOM101DEVICES D LEFT JOIN DEVICEMOVEMENTS DM ON D.DEVICE_ID = DM.DEVICE_ID LEFT JOIN AVERAGESIGNALSTRENGTH ASS ON D.DEVICE_ID = ASS.DEVICE_ID LEFT JOIN LASTACCESS LA ON D.DEVICE_ID = LA.DEVICE_ID;

