SELECT DISTINCT C.CHARACTER_NAME FROM CHARACTERS C JOIN PARTY_MEMBERS PM ON C.CHARACTER_ID = PM.CHARACTER_ID JOIN PARTIES P ON PM.PARTY_ID = P.PARTY_ID JOIN CHARACTER_SKILLS CS ON C.CHARACTER_ID = CS.CHARACTER_ID JOIN CHARACTER_ABILITIES CA ON CS.ABILITY_ID = CA.ABILITY_ID JOIN CHARACTER_EQUIPMENT CE ON C.CHARACTER_ID = CE.CHARACTER_ID WHERE P.PARTY_NAME = 'BRAVE EXPLORERS' AND CA.ABILITY_NAME = 'SLASH' AND CS.PROFICIENCY_LEVEL > 2 AND C.LEVEL > 5 AND CE.ITEM_RARITY = 'RARE';
WITH PARTY_MEMBERS_CTE AS ( SELECT PM.CHARACTER_ID FROM PARTY_MEMBERS PM JOIN PARTIES P ON PM.PARTY_ID = P.PARTY_ID WHERE P.PARTY_NAME = 'BRAVE EXPLORERS' ), SLASH_ABILITIES_CTE AS ( SELECT CS.CHARACTER_ID FROM CHARACTER_SKILLS CS JOIN CHARACTER_ABILITIES CA ON CS.ABILITY_ID = CA.ABILITY_ID WHERE CA.ABILITY_NAME = 'SLASH' AND CS.PROFICIENCY_LEVEL > 2 ), HIGH_LEVEL_CHARACTERS_CTE AS ( SELECT C.CHARACTER_ID FROM CHARACTERS C WHERE C.LEVEL > 5 ), RARE_EQUIPPED_CHARACTERS_CTE AS ( SELECT CE.CHARACTER_ID FROM CHARACTER_EQUIPMENT CE WHERE CE.ITEM_RARITY = 'RARE' ) SELECT C.CHARACTER_NAME FROM CHARACTERS C WHERE C.CHARACTER_ID IN ( SELECT PM.CHARACTER_ID FROM PARTY_MEMBERS_CTE PM JOIN SLASH_ABILITIES_CTE SA ON PM.CHARACTER_ID = SA.CHARACTER_ID JOIN HIGH_LEVEL_CHARACTERS_CTE HLC ON PM.CHARACTER_ID = HLC.CHARACTER_ID JOIN RARE_EQUIPPED_CHARACTERS_CTE REC ON PM.CHARACTER_ID = REC.CHARACTER_ID );

