WITH BUTTONCOUNTS AS ( SELECT FEATURE_ID, COUNT(*) AS BUTTON_COUNT FROM BUTTON_INTERACTIONS GROUP BY FEATURE_ID ), VOCALCOUNTS AS ( SELECT FEATURE_ID, COUNT(*) AS VOCAL_COUNT FROM VOCAL_INTERACTIONS GROUP BY FEATURE_ID ), TOTALCOUNTS AS ( SELECT AF.FEATURE_ID, AF.FEATURE_NAME, IFNULL(BC.BUTTON_COUNT, 0) + IFNULL(VC.VOCAL_COUNT, 0) AS TOTAL_INTERACTIONS FROM AUDIO_FEATURES AF LEFT JOIN BUTTONCOUNTS BC ON AF.FEATURE_ID = BC.FEATURE_ID LEFT JOIN VOCALCOUNTS VC ON AF.FEATURE_ID = VC.FEATURE_ID ) SELECT FEATURE_NAME FROM TOTALCOUNTS ORDER BY TOTAL_INTERACTIONS DESC, FEATURE_NAME;
WITH FEATUREINTERACTIONCOUNTS AS ( SELECT AI.FEATURE_ID, AI.FEATURE_NAME, COALESCE(SUM(CASE WHEN BI.FEATURE_ID IS NOT NULL THEN 1 ELSE 0 END), 0) AS BUTTON_INTERACTION_COUNT, COALESCE(SUM(CASE WHEN VI.FEATURE_ID IS NOT NULL THEN 1 ELSE 0 END), 0) AS VOCAL_INTERACTION_COUNT FROM AUDIO_FEATURES AI LEFT JOIN BUTTON_INTERACTIONS BI ON AI.FEATURE_ID = BI.FEATURE_ID LEFT JOIN VOCAL_INTERACTIONS VI ON AI.FEATURE_ID = VI.FEATURE_ID GROUP BY AI.FEATURE_ID, AI.FEATURE_NAME ), TOP5FEATURES AS ( SELECT FEATURE_ID, FEATURE_NAME, (BUTTON_INTERACTION_COUNT + VOCAL_INTERACTION_COUNT) AS TOTAL_INTERACTIONS FROM FEATUREINTERACTIONCOUNTS ORDER BY TOTAL_INTERACTIONS DESC LIMIT 5 ) SELECT FEATURE_NAME FROM TOP5FEATURES ORDER BY FEATURE_NAME;

