WITH ACCESS_COUNTS AS ( SELECT A.NAME AS PARAMETER_NAME, COUNT(AL.ACCESS_ID) AS TOTAL_ACCESSES FROM ATMOSPHERIC_DATA A LEFT JOIN ACCESS_LOGS AL ON A.DATA_ID = AL.DATA_ID GROUP BY A.NAME ), FILE_SIZES AS ( SELECT A.NAME AS PARAMETER_NAME, AVG(DF.FILE_SIZE) AS AVG_FILE_SIZE FROM ATMOSPHERIC_DATA A LEFT JOIN DATA_FILES DF ON A.DATA_ID = DF.DATA_ID GROUP BY A.NAME ) SELECT AC.PARAMETER_NAME, COALESCE(AC.TOTAL_ACCESSES, 0) AS TOTAL_ACCESSES, COALESCE(FS.AVG_FILE_SIZE, 0) AS AVG_FILE_SIZE FROM ACCESS_COUNTS AC LEFT JOIN FILE_SIZES FS ON AC.PARAMETER_NAME = FS.PARAMETER_NAME ORDER BY AC.PARAMETER_NAME, AC.TOTAL_ACCESSES DESC;

