WITH PORTFOLIOPERFORMANCECTE AS ( SELECT P.PORTFOLIO_ID, P.PORTFOLIO_NAME, SUM((S.LAST_PRICE - PS.COST_BASIS) * PS.QUANTITY) AS PORTFOLIO_PROFIT FROM PORTFOLIOS P INNER JOIN PORTFOLIO_SECURITIES PS ON P.PORTFOLIO_ID = PS.PORTFOLIO_ID INNER JOIN SECURITIES S ON PS.SECURITY_ID = S.SECURITY_ID GROUP BY P.PORTFOLIO_ID, P.PORTFOLIO_NAME ) SELECT MAX(PORTFOLIO_PROFIT) AS MAX_PROFIT FROM PORTFOLIOPERFORMANCECTE WHERE PORTFOLIO_PROFIT > 0;
WITH PORTFOLIOVALUE AS (
    SELECT 
        PS.PORTFOLIO_ID,
        SUM(PS.QUANTITY * S.LAST_PRICE) AS CURRENT_VALUE,
        SUM(PS.QUANTITY * PS.COST_BASIS) AS TOTAL_INVESTMENT
    FROM PORTFOLIO_SECURITIES PS
    JOIN SECURITIES S ON PS.SECURITY_ID = S.SECURITY_ID
    GROUP BY PS.PORTFOLIO_ID
),
PORTFOLIOPROFIT AS (
    SELECT 
        PV.PORTFOLIO_ID,
        PV.CURRENT_VALUE - PV.TOTAL_INVESTMENT AS PROFIT
    FROM PORTFOLIOVALUE PV
)
SELECT 
    MAX(PROFIT) AS MAX_PROFIT
FROM PORTFOLIOPROFIT
WHERE PROFIT > 0;

