SELECT A.ATTACK_ID, A.WEAPON_CATEGORY, A.IGNORE_INVULNERABLE, A.NO_REACTION, A.IS_RANGED, A.SURFACE_IMPACT_EFFECT, A.ATTACK_TYPE, A.ANIMATION_ID, A.ATTACK_SPEED, A.COOLDOWN, D.DAMAGE_TYPE, D.AFFIXES, D.STATUS_EFFECT, D.EFFECT_ONLY_ON_DAMAGE, D.DEFLECT_DAMAGE_ID, D.CRITICAL_HIT_CHANCE, D.CRITICAL_HIT_MULTIPLIER, CM.STAGGER_DMG_MODIFIER, CM.STAGGER_RESIST_MODIFIER, CM.ADD_DMG, CM.IMPACT_RATING, CM.BLOCK_RATING, CM.PARRY_RATING, DC.DMG_COEF, DC.DMG_COEF_HEAD, DC.DMG_COEF_CRIT, DC.DMG_COEF_BODY, DC.DMG_COEF_ARM, DC.DMG_COEF_LEG FROM ATTACK_TYPES A JOIN DAMAGE_ATTRIBUTES D ON A.ATTACK_ID = D.ATTACK_ID JOIN COMBAT_MODIFIERS CM ON A.ATTACK_ID = CM.ATTACK_ID JOIN DAMAGE_COEFFICIENTS DC ON A.ATTACK_ID = DC.ATTACK_ID WHERE D.CRITICAL_HIT_CHANCE >= 0.8;
WITH ATTACK_DETAILS AS ( SELECT A.ATTACK_ID, A.WEAPON_CATEGORY, A.IGNORE_INVULNERABLE, A.NO_REACTION, A.IS_RANGED, A.SURFACE_IMPACT_EFFECT, A.ATTACK_TYPE, A.ANIMATION_ID, A.ATTACK_SPEED, A.COOLDOWN FROM ATTACK_TYPES A ), DAMAGE_DETAILS AS ( SELECT D.ATTACK_ID, D.DAMAGE_TYPE, D.AFFIXES, D.STATUS_EFFECT, D.EFFECT_ONLY_ON_DAMAGE, D.DEFLECT_DAMAGE_ID, D.CRITICAL_HIT_CHANCE, D.CRITICAL_HIT_MULTIPLIER FROM DAMAGE_ATTRIBUTES D ), COMBAT_MODIFIERS_DETAILS AS ( SELECT C.ATTACK_ID, C.STAGGER_DMG_MODIFIER, C.STAGGER_RESIST_MODIFIER, C.ADD_DMG, C.IMPACT_RATING, C.BLOCK_RATING, C.PARRY_RATING FROM COMBAT_MODIFIERS C ), DAMAGE_COEFFICIENTS_DETAILS AS ( SELECT AC.ATTACK_ID, AC.DMG_COEF, AC.DMG_COEF_HEAD, AC.DMG_COEF_CRIT, AC.DMG_COEF_BODY, AC.DMG_COEF_ARM, AC.DMG_COEF_LEG FROM DAMAGE_COEFFICIENTS AC ) SELECT AD.ATTACK_ID, AD.WEAPON_CATEGORY, AD.IGNORE_INVULNERABLE, AD.NO_REACTION, AD.IS_RANGED, AD.SURFACE_IMPACT_EFFECT, AD.ATTACK_TYPE, AD.ANIMATION_ID, AD.ATTACK_SPEED, AD.COOLDOWN, DD.DAMAGE_TYPE, DD.AFFIXES, DD.STATUS_EFFECT, DD.EFFECT_ONLY_ON_DAMAGE, DD.DEFLECT_DAMAGE_ID, DD.CRITICAL_HIT_CHANCE, DD.CRITICAL_HIT_MULTIPLIER, CMD.STAGGER_DMG_MODIFIER, CMD.STAGGER_RESIST_MODIFIER, CMD.ADD_DMG, CMD.IMPACT_RATING, CMD.BLOCK_RATING, CMD.PARRY_RATING, DCD.DMG_COEF, DCD.DMG_COEF_HEAD, DCD.DMG_COEF_CRIT, DCD.DMG_COEF_BODY, DCD.DMG_COEF_ARM, DCD.DMG_COEF_LEG FROM ATTACK_DETAILS AD INNER JOIN DAMAGE_DETAILS DD ON AD.ATTACK_ID = DD.ATTACK_ID LEFT JOIN COMBAT_MODIFIERS_DETAILS CMD ON AD.ATTACK_ID = CMD.ATTACK_ID LEFT JOIN DAMAGE_COEFFICIENTS_DETAILS DCD ON AD.ATTACK_ID = DCD.ATTACK_ID WHERE DD.CRITICAL_HIT_CHANCE >= 0.8;

