WITH GAMEPLATFORMS AS ( SELECT GAME_ID, COUNT(PLATFORM_ID) AS NUM_PLATFORMS FROM GAME_PLATFORMS GROUP BY GAME_ID ), GAMEAWARDS AS ( SELECT GAME_ID, COUNT(AWARD_ID) AS NUM_AWARDS FROM GAME_AWARDS GROUP BY GAME_ID ), GAMETAGS AS ( SELECT GAME_ID, COUNT(TAG_ID) AS NUM_TAGS FROM GAME_TAGS GROUP BY GAME_ID ), GAMESCORES AS ( SELECT GP.GAME_ID, COALESCE(GP.NUM_PLATFORMS, 0) + COALESCE(GA.NUM_AWARDS, 0) + COALESCE(GT.NUM_TAGS, 0) AS TOTAL_SCORE FROM GAMEPLATFORMS GP FULL OUTER JOIN GAMEAWARDS GA ON GP.GAME_ID = GA.GAME_ID FULL OUTER JOIN GAMETAGS GT ON GP.GAME_ID = GT.GAME_ID ) SELECT MAX(TOTAL_SCORE) AS MAX_TOTAL_SCORE FROM GAMESCORES;

