WITH COMPLETEDTRIPSCTE AS ( SELECT PASSENGER_ID FROM PASSENGER_TRAVEL_HISTORY WHERE TRAVEL_STATUS = 'COMPLETED' GROUP BY PASSENGER_ID HAVING COUNT(*) > 1 ), USEDTICKETSCTE AS ( SELECT PASSENGER_ID FROM TICKETS WHERE STATUS = 'USED' ), REVENUEGENERATINGROUTESCTE AS ( SELECT ROUTE_ID FROM REVENUE GROUP BY ROUTE_ID HAVING SUM(REVENUE_AMOUNT) > 0 ) SELECT COUNT(DISTINCT PTH.PASSENGER_ID) AS TOTAL_UNIQUE_PASSENGERS FROM PASSENGER_TRAVEL_HISTORY PTH JOIN COMPLETEDTRIPSCTE CT ON PTH.PASSENGER_ID = CT.PASSENGER_ID JOIN USEDTICKETSCTE UT ON PTH.PASSENGER_ID = UT.PASSENGER_ID JOIN REVENUEGENERATINGROUTESCTE RGR ON PTH.ROUTE_ID = RGR.ROUTE_ID WHERE PTH.TRAVEL_STATUS = 'COMPLETED';
WITH REVENUEROUTES AS ( SELECT DISTINCT ROUTE_ID FROM REVENUE WHERE ROUTE_ID IS NOT NULL ), PASSENGERREVENUE AS ( SELECT DISTINCT PTH.PASSENGER_ID FROM PASSENGER_TRAVEL_HISTORY PTH JOIN REVENUEROUTES RR ON PTH.ROUTE_ID = RR.ROUTE_ID WHERE PTH.TRAVEL_STATUS = 'COMPLETED' ), USEDTICKETS AS ( SELECT DISTINCT PASSENGER_ID FROM TICKETS WHERE STATUS = 'USED' ) SELECT COUNT(DISTINCT PR.PASSENGER_ID) AS PASSENGER_COUNT FROM ( SELECT PASSENGER_ID FROM PASSENGER_TRAVEL_HISTORY GROUP BY PASSENGER_ID HAVING COUNT(DISTINCT HISTORY_ID) > 1 ) PR JOIN PASSENGERREVENUE PRR ON PR.PASSENGER_ID = PRR.PASSENGER_ID JOIN USEDTICKETS UT ON PR.PASSENGER_ID = UT.PASSENGER_ID;

