SELECT P.PROJECT_NAME, P.START_DATE, P.END_DATE, P.BUDGET, P.STATUS, P.CLIENT_NAME, M.NAME AS PROJECT_MANAGER, D.DEPARTMENT_NAME, COALESCE(SUM(TE.HOURS), 0) AS TOTAL_HOURS_WORKED, COALESCE(SUM(TE.OVERTIME_HOURS), 0) AS TOTAL_OVERTIME_HOURS_WORKED, COALESCE((AVG(R.HOURLY_RATE) * SUM(TE.HOURS)) + (AVG(R.HOURLY_RATE) * SUM(TE.OVERTIME_HOURS)), 0) AS TOTAL_BUDGET_SPENT, COALESCE(AVG(R.HOURLY_RATE), 0) AS AVERAGE_HOURLY_RATE, COALESCE( ((AVG(R.HOURLY_RATE) * SUM(TE.HOURS)) + (AVG(R.HOURLY_RATE) * SUM(TE.OVERTIME_HOURS))) / P.BUDGET * 100, 0 ) AS BUDGET_SPENT_PERCENTAGE FROM PROJECTS P JOIN MANAGERS M ON P.PROJECT_MANAGER_ID = M.MANAGER_ID JOIN DEPARTMENTS D ON P.DEPARTMENT_ID = D.DEPARTMENT_ID LEFT JOIN TIME_ENTRIES TE ON TE.PROJECT_ID = P.PROJECT_ID LEFT JOIN ROLES R ON TE.ROLE_ID = R.ROLE_ID GROUP BY P.PROJECT_ID, P.PROJECT_NAME, P.START_DATE, P.END_DATE, P.BUDGET, P.STATUS, P.CLIENT_NAME, M.NAME, D.DEPARTMENT_NAME ORDER BY P.PROJECT_NAME;
WITH PROJECT_DETAILS AS ( SELECT P.PROJECT_ID, P.PROJECT_NAME, P.START_DATE, P.END_DATE, P.BUDGET, P.STATUS, P.CLIENT_NAME, M.NAME AS PROJECT_MANAGER, D.DEPARTMENT_NAME FROM PROJECTS P JOIN MANAGERS M ON P.PROJECT_MANAGER_ID = M.MANAGER_ID JOIN DEPARTMENTS D ON P.DEPARTMENT_ID = D.DEPARTMENT_ID ), TIME_ENTRY_DETAILS AS ( SELECT TE.PROJECT_ID, SUM(TE.HOURS) AS TOTAL_HOURS, SUM(TE.OVERTIME_HOURS) AS TOTAL_OVERTIME_HOURS, SUM(TE.HOURS * R.HOURLY_RATE) AS TOTAL_BUDGET_SPENT, AVG(R.HOURLY_RATE) AS AVERAGE_HOURLY_RATE FROM TIME_ENTRIES TE JOIN EMPLOYEE_ROLES ER ON TE.EMPLOYEE_ID = ER.EMPLOYEE_ID JOIN ROLES R ON ER.ROLE_ID = R.ROLE_ID GROUP BY TE.PROJECT_ID ) SELECT P.PROJECT_NAME, P.START_DATE, P.END_DATE, P.BUDGET, P.STATUS, P.CLIENT_NAME, P.PROJECT_MANAGER, P.DEPARTMENT_NAME, TED.TOTAL_HOURS, TED.TOTAL_OVERTIME_HOURS, TED.TOTAL_BUDGET_SPENT, TED.AVERAGE_HOURLY_RATE, (TED.TOTAL_BUDGET_SPENT / P.BUDGET) * 100 AS BUDGET_SPENT_PERCENTAGE FROM PROJECT_DETAILS P JOIN TIME_ENTRY_DETAILS TED ON P.PROJECT_ID = TED.PROJECT_ID ORDER BY P.PROJECT_NAME;

