WITH TRANSFERCOUNTS AS (
    SELECT 
        DT.STREAM_ID, 
        COUNT(DT.TRANSFER_ID) AS TRANSFER_COUNT, 
        SUM(DT.BYTES_TRANSFERRED) AS TOTAL_BYTES_TRANSFERRED
    FROM DATA_TRANSFERS DT
    GROUP BY DT.STREAM_ID
),
ERRORCOUNTS AS (
    SELECT 
        EL.STREAM_ID, 
        COUNT(EL.ERROR_ID) AS ERROR_COUNT, 
        SUM(CASE WHEN EL.ERROR_CODE = 1001 THEN 1 ELSE 0 END) AS TIMEOUT_ERRORS
    FROM ERROR_LOGS EL
    GROUP BY EL.STREAM_ID
),
USERACCESS AS (
    SELECT 
        UA.STREAM_ID, 
        UA.USER_ID
    FROM USER_ACCESS_LOGS UA
    WHERE UA.ACTION = 'VIEW' AND UA.ACCESS_TIME > '2022-01-01'
)
SELECT 
    S.STREAM_ID, 
    S.DESTINATION, 
    S.EVENT, 
    S.MTI, 
    S.DATA_CONTENT, 
    S.STREAM_TYPE_ID, 
    S.START_DATE, 
    S.END_DATE, 
    S.IS_ACTIVE, 
    TC.TRANSFER_COUNT, 
    TC.TOTAL_BYTES_TRANSFERRED, 
    EC.ERROR_COUNT, 
    EC.TIMEOUT_ERRORS, 
    UA.USER_ID
FROM STREAMS S
LEFT JOIN TRANSFERCOUNTS TC ON S.STREAM_ID = TC.STREAM_ID
LEFT JOIN ERRORCOUNTS EC ON S.STREAM_ID = EC.STREAM_ID
LEFT JOIN USERACCESS UA ON S.STREAM_ID = UA.STREAM_ID
WHERE S.IS_ACTIVE = 1
ORDER BY S.EVENT, S.DESTINATION, S.EVENT;
WITH TRANSFERCOUNTS AS ( SELECT DT.STREAM_ID, COUNT(DT.TRANSFER_ID) AS TRANSFER_COUNT, SUM(DT.BYTES_TRANSFERRED) AS TOTAL_BYTES_TRANSFERRED FROM DATA_TRANSFERS DT GROUP BY DT.STREAM_ID ), ERRORCOUNTS AS ( SELECT EL.STREAM_ID, COUNT(EL.ERROR_ID) AS ERROR_COUNT, SUM(CASE WHEN EL.ERROR_CODE = 1001 THEN 1 ELSE 0 END) AS TIMEOUT_ERRORS FROM ERROR_LOGS EL GROUP BY EL.STREAM_ID ), USERACCESS AS ( SELECT UA.STREAM_ID, UA.USER_ID FROM USER_ACCESS_LOGS UA WHERE UA.ACTION = 'VIEW' AND UA.ACCESS_TIME > '2022-01-01' ) SELECT S.STREAM_ID, S.DESTINATION, S.EVENT, S.MTI, S.DATA_CONTENT, S.STREAM_TYPE_ID, S.START_DATE, S.END_DATE, S.IS_ACTIVE, IFNULL(TC.TRANSFER_COUNT, 0) AS TRANSFER_COUNT, IFNULL(TC.TOTAL_BYTES_TRANSFERRED, 0) AS TOTAL_BYTES_TRANSFERRED, IFNULL(EC.ERROR_COUNT, 0) AS ERROR_COUNT, IFNULL(EC.TIMEOUT_ERRORS, 0) AS TIMEOUT_ERRORS, IFNULL(UA.USER_ID, 0) AS USER_ID FROM STREAMS S LEFT JOIN TRANSFERCOUNTS TC ON S.STREAM_ID = TC.STREAM_ID LEFT JOIN ERRORCOUNTS EC ON S.STREAM_ID = EC.STREAM_ID LEFT JOIN USERACCESS UA ON S.STREAM_ID = UA.STREAM_ID WHERE S.IS_ACTIVE = 1 ORDER BY S.EVENT, S.DESTINATION, S.EVENT;

