    COUNT(DISTINCT SE.STUDENT_ID) AS ACTIVE_STUDENTS, 
    COUNT(DISTINCT FA.FACULTY_ID) AS ASSIGNED_FACULTY
FROM 
    PROGRAMS P
LEFT JOIN 
    PROGRAM_ENROLLMENT SE ON P.PROGRAM_ID = SE.PROGRAM_ID AND SE.ENROLLMENT_STATUS = 'ACTIVE'
LEFT JOIN 
    FACULTY_ASSIGNMENTS FA ON P.PROGRAM_ID = FA.PROGRAM_ID
WHERE 
    P.IS_ACTIVE = 1
GROUP BY 
    P.PROGRAM_ID, P.PROGRAM_NAME
ORDER BY 
    ACTIVE_STUDENTS DESC, 
    ASSIGNED_FACULTY DESC;
WITH ACTIVESTUDENTS AS ( SELECT S.PROGRAM_ID, COUNT(S.STUDENT_ID) AS TOTAL_ACTIVE_STUDENTS FROM STUDENTS S INNER JOIN PROGRAM_ENROLLMENT PE ON S.STUDENT_ID = PE.STUDENT_ID WHERE S.STUDENT_ID = PE.STUDENT_ID AND PE.ENROLLMENT_STATUS = 'ACTIVE' GROUP BY S.PROGRAM_ID ), ASSIGNEDFACULTY AS ( SELECT PF.PROGRAM_ID, COUNT(PF.FACULTY_ID) AS TOTAL_FACULTY FROM PROGRAM_FACULTY PF GROUP BY PF.PROGRAM_ID ) SELECT P.PROGRAM_NAME, COALESCE(A.TOTAL_ACTIVE_STUDENTS, 0) AS TOTAL_ACTIVE_STUDENTS, COALESCE(F.TOTAL_FACULTY, 0) AS TOTAL_FACULTY FROM PROGRAMS P LEFT JOIN ACTIVESTUDENTS A ON P.PROGRAM_ID = A.PROGRAM_ID LEFT JOIN ASSIGNEDFACULTY F ON P.PROGRAM_ID = F.PROGRAM_ID WHERE P.IS_ACTIVE = 1 ORDER BY TOTAL_ACTIVE_STUDENTS DESC, TOTAL_FACULTY DESC;

