SELECT LP.PARCEL_ID, LP.SITE_NAME_ADDRESS, LP.HECTARES, LP.LAND_USE_TYPE, PP.PERMISSION_TYPE, PP.PERMISSION_DATE, PP.APPLICANT_NAME, RO.OPPORTUNITY_TYPE, RO.OPPORTUNITY_DESCRIPTION, C.COMPLIANCE_STATUS, C.NON_COMPLIANCE_REASON FROM LAND_PARCELS LP LEFT JOIN PLANNING_PERMISSIONS PP ON LP.PARCEL_ID = PP.PARCEL_ID LEFT JOIN REDEVELOPMENT_OPPORTUNITIES RO ON LP.PARCEL_ID = RO.PARCEL_ID LEFT JOIN COMPLIANCE C ON LP.PARCEL_ID = C.PARCEL_ID WHERE LP.REDEVELOPMENT_POTENTIAL = 1 ORDER BY LP.PARCEL_ID;
WITH PARCEL_DETAILS AS ( SELECT LP.PARCEL_ID, LP.SITE_NAME_ADDRESS, LP.HECTARES, LP.LAND_USE_TYPE, LP.REDEVELOPMENT_POTENTIAL FROM LAND_PARCELS LP WHERE LP.REDEVELOPMENT_POTENTIAL = 1 ), PERMISSION_DETAILS AS ( SELECT PP.PARCEL_ID, PP.PERMISSION_TYPE, PP.PERMISSION_DATE, PP.APPLICANT_NAME FROM PLANNING_PERMISSIONS PP ), OPPORTUNITY_DETAILS AS ( SELECT RO.PARCEL_ID, RO.OPPORTUNITY_TYPE, RO.OPPORTUNITY_DESCRIPTION FROM REDEVELOPMENT_OPPORTUNITIES RO ), COMPLIANCE_DETAILS AS ( SELECT C.PARCEL_ID, C.COMPLIANCE_STATUS, C.NON_COMPLIANCE_REASON FROM COMPLIANCE C ) SELECT PD.PARCEL_ID, PD.SITE_NAME_ADDRESS, PD.HECTARES, PD.LAND_USE_TYPE, COALESCE(PD2.PERMISSION_TYPE, 'N/A') AS PERMISSION_TYPE, COALESCE(PD2.PERMISSION_DATE, 'N/A') AS PERMISSION_DATE, COALESCE(PD2.APPLICANT_NAME, 'N/A') AS APPLICANT_NAME, COALESCE(OD.OPPORTUNITY_TYPE, 'N/A') AS OPPORTUNITY_TYPE, COALESCE(OD.OPPORTUNITY_DESCRIPTION, 'N/A') AS OPPORTUNITY_DESCRIPTION, COALESCE(CD.COMPLIANCE_STATUS, 'N/A') AS COMPLIANCE_STATUS, COALESCE(CD.NON_COMPLIANCE_REASON, 'N/A') AS NON_COMPLIANCE_REASON FROM PARCEL_DETAILS PD LEFT JOIN PERMISSION_DETAILS PD2 ON PD.PARCEL_ID = PD2.PARCEL_ID LEFT JOIN OPPORTUNITY_DETAILS OD ON PD.PARCEL_ID = OD.PARCEL_ID LEFT JOIN COMPLIANCE_DETAILS CD ON PD.PARCEL_ID = CD.PARCEL_ID ORDER BY PD.PARCEL_ID;

