SELECT D.NAME AS DEVELOPER_NAME, (SELECT COUNT(C.COMMIT_ID) FROM COMMITS C WHERE C.DEVELOPER_ID = D.DEVELOPER_ID) - (SELECT AVG(TEAM_TOTALS.TOTAL_COMMITS) FROM (SELECT D2.TEAM_ID, COUNT(C2.COMMIT_ID) AS TOTAL_COMMITS FROM DEVELOPERS D2 JOIN COMMITS C2 ON D2.DEVELOPER_ID = C2.DEVELOPER_ID GROUP BY D2.TEAM_ID) AS TEAM_TOTALS WHERE TEAM_TOTALS.TEAM_ID = D.TEAM_ID) AS COMMITS_ABOVE_AVG FROM DEVELOPERS D WHERE (SELECT COUNT(C.COMMIT_ID) FROM COMMITS C WHERE C.DEVELOPER_ID = D.DEVELOPER_ID) > (SELECT AVG(TEAM_TOTALS.TOTAL_COMMITS) FROM (SELECT D2.TEAM_ID, COUNT(C2.COMMIT_ID) AS TOTAL_COMMITS FROM DEVELOPERS D2 JOIN COMMITS C2 ON D2.DEVELOPER_ID = C2.DEVELOPER_ID GROUP BY D2.TEAM_ID) AS TEAM_TOTALS WHERE TEAM_TOTALS.TEAM_ID = D.TEAM_ID);
WITH TEAMCOMMITS AS ( SELECT T1.TEAM_ID, T2.DEVELOPER_ID, COUNT(T2.COMMIT_ID) AS COMMIT_COUNT FROM DEVELOPERS T1 INNER JOIN COMMITS T2 ON T1.DEVELOPER_ID = T2.DEVELOPER_ID GROUP BY T1.TEAM_ID, T2.DEVELOPER_ID ), TEAMAVERAGECOMMITS AS ( SELECT TEAM_ID, AVG(COMMIT_COUNT) AS AVG_COMMIT_COUNT FROM TEAMCOMMITS GROUP BY TEAM_ID ) SELECT T1.NAME, T2.COMMIT_COUNT - T3.AVG_COMMIT_COUNT AS COMMIT_DIFFERENCE FROM DEVELOPERS T1 INNER JOIN TEAMCOMMITS T2 ON T1.DEVELOPER_ID = T2.DEVELOPER_ID INNER JOIN TEAMAVERAGECOMMITS T3 ON T2.TEAM_ID = T3.TEAM_ID WHERE T2.COMMIT_COUNT > T3.AVG_COMMIT_COUNT;

