WITH RECALLQUANTITIES AS ( SELECT RECALL_NUMBER, SUM(QUANTITY_IN_COMMERCE) AS TOTAL_QUANTITY FROM RECALLS GROUP BY RECALL_NUMBER ), RECALLDISTRIBUTIONS AS ( SELECT RECALL_NUMBER, SUM(DISTRIBUTION_VOLUME) AS TOTAL_DISTRIBUTION FROM DISTRIBUTIONS GROUP BY RECALL_NUMBER ), RECALLACTIONS AS ( SELECT RECALL_NUMBER, ACTION_DESCRIPTION, ACTION_DATE, ACTION_STATUS FROM ACTIONS ) SELECT R.RECALL_NUMBER, R.DATE_POSTED, R.RECALL_STATUS, R.TERMINATION_DATE, RQ.TOTAL_QUANTITY, RA.ACTION_DESCRIPTION, RA.ACTION_DATE, RA.ACTION_STATUS, M.MANUFACTURER_NAME, M.CONTACT_EMAIL, M.ADDRESS, M.PHONE, RD.TOTAL_DISTRIBUTION FROM RECALLS R INNER JOIN RECALLQUANTITIES RQ ON R.RECALL_NUMBER = RQ.RECALL_NUMBER INNER JOIN RECALLDISTRIBUTIONS RD ON R.RECALL_NUMBER = RD.RECALL_NUMBER INNER JOIN RECALLACTIONS RA ON R.RECALL_NUMBER = RA.RECALL_NUMBER INNER JOIN MANUFACTURERS M ON R.RECALLING_MANUFACTURER = M.MANUFACTURER_NAME WHERE R.RECALL_STATUS = 'ONGOING' AND RA.ACTION_DATE = ( SELECT MAX(ACTION_DATE) FROM ACTIONS A WHERE A.RECALL_NUMBER = R.RECALL_NUMBER );
WITH RECALLQUANTITIES AS ( SELECT RECALL_NUMBER, SUM(QUANTITY_IN_COMMERCE) AS TOTAL_QUANTITY FROM RECALLS GROUP BY RECALL_NUMBER ), RECALLDISTRIBUTIONS AS ( SELECT RECALL_NUMBER, SUM(DISTRIBUTION_VOLUME) AS TOTAL_DISTRIBUTION FROM DISTRIBUTIONS GROUP BY RECALL_NUMBER ), RECENTACTIONS AS ( SELECT RECALL_NUMBER, ACTION_DESCRIPTION, ACTION_DATE, ACTION_STATUS FROM ACTIONS WHERE ACTION_DATE = ( SELECT MAX(ACTION_DATE) FROM ACTIONS A2 WHERE A2.RECALL_NUMBER = ACTIONS.RECALL_NUMBER ) ), RECALLINFO AS ( SELECT R.RECALL_NUMBER, R.DATE_POSTED, R.RECALL_STATUS, R.TERMINATION_DATE, RQ.TOTAL_QUANTITY, RA.ACTION_DESCRIPTION, RA.ACTION_DATE, RA.ACTION_STATUS, M.MANUFACTURER_NAME, M.CONTACT_EMAIL, M.ADDRESS, M.PHONE, RD.TOTAL_DISTRIBUTION FROM RECALLS R INNER JOIN RECALLQUANTITIES RQ ON R.RECALL_NUMBER = RQ.RECALL_NUMBER INNER JOIN RECALLDISTRIBUTIONS RD ON R.RECALL_NUMBER = RD.RECALL_NUMBER INNER JOIN RECENTACTIONS RA ON R.RECALL_NUMBER = RA.RECALL_NUMBER INNER JOIN MANUFACTURERS M ON R.RECALLING_MANUFACTURER = M.MANUFACTURER_NAME WHERE R.RECALL_STATUS = 'ONGOING' ) SELECT RECALL_NUMBER, DATE_POSTED, RECALL_STATUS, TERMINATION_DATE, TOTAL_QUANTITY, ACTION_DESCRIPTION, ACTION_DATE, ACTION_STATUS, MANUFACTURER_NAME, CONTACT_EMAIL, ADDRESS, PHONE, TOTAL_DISTRIBUTION FROM RECALLINFO;

