SELECT T.TASK_NAME
FROM TASKS T
JOIN CONFIG_OPTIONS CO ON T.TASK_ID = CO.TASK_ID
JOIN VERSIONS V ON T.TASK_ID = V.TASK_ID
LEFT JOIN TASK_DEPENDENCIES TD ON T.TASK_ID = TD.TASK_ID
JOIN PERFORMANCE_STATS PS ON T.TASK_ID = PS.TASK_ID
WHERE CO.OPTION_NAME = 'CALCULATION_MODE'
  AND CO.OPTION_VALUE = 'FORWARD'
  AND V.VERSION_NAME = 'V1.0'
  AND TD.DEPENDENT_TASK_ID IS NULL
  AND PS.STAT_NAME = 'EXECUTION TIME'
  AND PS.STAT_UNIT = 'SECONDS';
SELECT T.TASK_NAME FROM TASKS T -- JOIN TO FIND TASKS WITH 'CALCULATION_MODE' = 'FORWARD' JOIN CONFIG_OPTIONS CO ON T.TASK_ID = CO.TASK_ID WHERE CO.OPTION_NAME = 'CALCULATION_MODE' AND CO.OPTION_VALUE = 'FORWARD' -- JOIN TO FIND TASKS WITH VERSION 'V1.0' JOIN VERSIONS V ON T.TASK_ID = V.TASK_ID WHERE V.VERSION_NAME = 'V1.0' -- ENSURE THE TASK HAS NO DEPENDENT TASKS USING NOT EXISTS AND NOT EXISTS ( SELECT 1 FROM TASK_DEPENDENCIES TD WHERE TD.TASK_ID = T.TASK_ID ) -- ENSURE THE TASK HAS AN 'EXECUTION TIME' PERFORMANCE STAT IN 'SECONDS' AND EXISTS ( SELECT 1 FROM PERFORMANCE_STATS PS WHERE PS.TASK_ID = T.TASK_ID AND PS.STAT_NAME = 'EXECUTION TIME' AND PS.STAT_UNIT = 'SECONDS' );

