SELECT LD.REGION, COALESCE(SE.EVENT_TYPE, 'NO EVENT') AS EVENT_TYPE, AVG(LD.LOAD_MW) AS AVERAGE_LOAD, AVG(WD.TEMPERATURE) AS AVERAGE_TEMPERATURE, AVG(WD.HUMIDITY) AS AVERAGE_HUMIDITY FROM LOAD_DATA LD JOIN WEATHER_DATA WD ON LD.MEASUREMENT_DATE = WD.DATE_ID AND LD.REGION = WD.REGION_ID LEFT JOIN SPECIAL_EVENTS SE ON LD.MEASUREMENT_DATE = SE.DATE_ID AND LD.REGION = SE.REGION_ID GROUP BY LD.REGION, COALESCE(SE.EVENT_TYPE, 'NO EVENT') ORDER BY LD.REGION, COALESCE(SE.EVENT_TYPE, 'NO EVENT');
WITH REGION_WEATHER AS ( SELECT WD.REGION_ID, AVG(WD.TEMPERATURE) AS AVG_TEMPERATURE, AVG(WD.HUMIDITY) AS AVG_HUMIDITY FROM WEATHER_DATA WD GROUP BY WD.REGION_ID ), REGION_LOAD AS ( SELECT R.REGION_ID, AVG(LD.LOAD_MW) AS AVG_LOAD FROM LOAD_DATA LD JOIN REGIONS R ON LD.REGION = R.REGION_NAME GROUP BY R.REGION_ID ), REGION_EVENTS AS ( SELECT SE.REGION_ID, 'WITH EVENT' AS EVENT_STATUS FROM SPECIAL_EVENTS SE UNION SELECT R.REGION_ID, 'NO EVENT' AS EVENT_STATUS FROM REGIONS R LEFT JOIN SPECIAL_EVENTS SE ON R.REGION_ID = SE.REGION_ID WHERE SE.EVENT_ID IS NULL ) SELECT R.REGION_NAME AS REGION, RE.EVENT_STATUS, RL.AVG_LOAD, RW.AVG_TEMPERATURE, RW.AVG_HUMIDITY FROM REGIONS R JOIN REGION_LOAD RL ON R.REGION_ID = RL.REGION_ID JOIN REGION_WEATHER RW ON R.REGION_ID = RW.REGION_ID JOIN REGION_EVENTS RE ON R.REGION_ID = RE.REGION_ID ORDER BY R.REGION_NAME, RE.EVENT_STATUS;

