SELECT C.COURSE_ID, C.CLASS_NUMBER, C.MNEMONIC, C.NUMBER, C.SECTION, C.UNITS, C.ENROLLMENT_LIMIT, C.PREREQUISITES, C.COURSE_LEVEL, C.SYLLABUS, C.CREATED_AT, C.UPDATED_AT, CI.INSTRUCTOR_ID, CI.ROLE, R.ROOM_ID, R.BUILDING, R.ROOM_NUMBER, R.CAPACITY, CS.DAYS, CS.START_TIME, CS.END_TIME, CS.START_DATE, CS.END_DATE, CS.CREATED_AT AS SCHEDULE_CREATED_AT, CS.UPDATED_AT AS SCHEDULE_UPDATED_AT, WS.WAITLIST FROM COURSES C JOIN COURSE_INSTRUCTORS CI ON C.COURSE_ID = CI.COURSE_ID JOIN COURSE_SCHEDULE CS ON C.COURSE_ID = CS.COURSE_ID JOIN ROOMS R ON CS.ROOM_ID = R.ROOM_ID JOIN WAITLIST_STATUS WS ON C.COURSE_ID = WS.COURSE_ID WHERE C.TYPE IN ('SEMINAR', 'LECTURE', 'WORKSHOP') AND R.BUILDING = 'MINOR HALL' AND WS.WAITLIST > 0 AND CS.START_DATE BETWEEN '2023-01-01' AND '2023-01-10' ORDER BY C.MNEMONIC, C.CLASS_NUMBER, C.COURSE_ID;
WITH COURSE_FILTER AS ( SELECT COURSE_ID, CLASS_NUMBER, MNEMONIC, NUMBER, SECTION, UNITS, ENROLLMENT_LIMIT, PREREQUISITES, COURSE_LEVEL, SYLLABUS, CREATED_AT, UPDATED_AT, TYPE FROM COURSES WHERE TYPE IN ('SEMINAR', 'LECTURE', 'WORKSHOP') ), SCHEDULE_FILTER AS ( SELECT CS.COURSE_ID, CS.ROOM_ID, CS.DAYS, CS.START_TIME, CS.END_TIME, CS.START_DATE, CS.END_DATE, CS.CREATED_AT AS SCHEDULE_CREATED_AT, CS.UPDATED_AT AS SCHEDULE_UPDATED_AT FROM COURSE_SCHEDULE CS WHERE CS.START_DATE BETWEEN '2023-01-01' AND '2023-01-10' ), ROOM_FILTER AS ( SELECT ROOM_ID, BUILDING, ROOM_NUMBER, CAPACITY FROM ROOMS WHERE BUILDING = 'MINOR HALL' ), WAITLIST_FILTER AS ( SELECT COURSE_ID, WAITLIST FROM WAITLIST_STATUS WHERE WAITLIST IS NOT NULL ) SELECT CF.COURSE_ID, CF.CLASS_NUMBER, CF.MNEMONIC, CF.NUMBER, CF.SECTION, CF.UNITS, CF.ENROLLMENT_LIMIT, CF.PREREQUISITES, CF.COURSE_LEVEL, CF.SYLLABUS, CF.CREATED_AT, CF.UPDATED_AT, CI.INSTRUCTOR_ID, CI.ROLE, RF.ROOM_ID, RF.BUILDING, RF.ROOM_NUMBER, RF.CAPACITY, SF.DAYS, SF.START_TIME, SF.END_TIME, SF.START_DATE, SF.END_DATE, SF.SCHEDULE_CREATED_AT, SF.SCHEDULE_UPDATED_AT, WF.WAITLIST FROM COURSE_FILTER CF INNER JOIN COURSE_INSTRUCTORS CI ON CF.COURSE_ID = CI.COURSE_ID INNER JOIN SCHEDULE_FILTER SF ON CF.COURSE_ID = SF.COURSE_ID INNER JOIN ROOM_FILTER RF ON SF.ROOM_ID = RF.ROOM_ID INNER JOIN WAITLIST_FILTER WF ON CF.COURSE_ID = WF.COURSE_ID ORDER BY CF.MNEMONIC, CF.CLASS_NUMBER, CF.COURSE_ID;

