SELECT 
  M.MODEL_NAME, 
  COALESCE(SUM(CASE WHEN AL.ACCESS_TYPE = 'VIEW' THEN 1 ELSE 0 END), 0) AS VIEW_COUNT,
  COALESCE(SUM(CASE WHEN AL.ACCESS_TYPE = 'TRAIN' THEN 1 ELSE 0 END), 0) AS TRAIN_COUNT,
  COALESCE(SUM(CASE WHEN AL.ACCESS_TYPE = 'PREDICT' THEN 1 ELSE 0 END), 0) AS PREDICT_COUNT
FROM MODELS M
LEFT JOIN ACCESS_LOGS AL ON M.MODEL_ID = AL.MODEL_ID
GROUP BY M.MODEL_NAME
ORDER BY VIEW_COUNT DESC;
WITH VIEW_COUNTS AS ( SELECT MODEL_ID, COUNT(*) AS VIEW_COUNT FROM ACCESS_LOGS WHERE ACCESS_TYPE = 'VIEW' GROUP BY MODEL_ID ), TRAIN_COUNTS AS ( SELECT MODEL_ID, COUNT(*) AS TRAIN_COUNT FROM ACCESS_LOGS WHERE ACCESS_TYPE = 'TRAIN' GROUP BY MODEL_ID ), PREDICT_COUNTS AS ( SELECT MODEL_ID, COUNT(*) AS PREDICT_COUNT FROM ACCESS_LOGS WHERE ACCESS_TYPE = 'PREDICT' GROUP BY MODEL_ID ) SELECT M.MODEL_NAME, COALESCE(VC.VIEW_COUNT, 0) AS VIEW_COUNT, COALESCE(TC.TRAIN_COUNT, 0) AS TRAIN_COUNT, COALESCE(PC.PREDICT_COUNT, 0) AS PREDICT_COUNT FROM MODELS M LEFT JOIN VIEW_COUNTS VC ON M.MODEL_ID = VC.MODEL_ID LEFT JOIN TRAIN_COUNTS TC ON M.MODEL_ID = TC.MODEL_ID LEFT JOIN PREDICT_COUNTS PC ON M.MODEL_ID = PC.MODEL_ID ORDER BY VIEW_COUNT DESC;

