WITH ACTIVELISTINGS AS ( SELECT L.SELLER_ID, COUNT(*) AS ACTIVE_LISTINGS FROM LISTINGS L WHERE L.LISTING_STATUS = 'ACTIVE' GROUP BY L.SELLER_ID ), SELLERRATINGS AS ( SELECT R.SELLER_ID, AVG(R.RATING) AS AVERAGE_RATING FROM REVIEWS R GROUP BY R.SELLER_ID ), VEHICLEHISTORIES AS ( SELECT VH.VEHICLE_ID, COUNT(*) AS HISTORY_COUNT FROM VEHICLE_HISTORY VH GROUP BY VH.VEHICLE_ID ), SELLERLISTINGS AS ( SELECT L.SELLER_ID, SUM(VH.HISTORY_COUNT) AS TOTAL_HISTORY_COUNT FROM LISTINGS L LEFT JOIN VEHICLEHISTORIES VH ON L.VEHICLE_ID = VH.VEHICLE_ID WHERE L.LISTING_STATUS = 'ACTIVE' GROUP BY L.SELLER_ID ) SELECT S.SELLER_NAME, COALESCE(AL.ACTIVE_LISTINGS, 0) AS ACTIVE_LISTINGS, COALESCE(SR.AVERAGE_RATING, 0) AS AVERAGE_RATING, COALESCE(SL.TOTAL_HISTORY_COUNT, 0) AS TOTAL_HISTORY_COUNT FROM SELLERS S LEFT JOIN ACTIVELISTINGS AL ON S.SELLER_ID = AL.SELLER_ID LEFT JOIN SELLERRATINGS SR ON S.SELLER_ID = SR.SELLER_ID LEFT JOIN SELLERLISTINGS SL ON S.SELLER_ID = SL.SELLER_ID ORDER BY S.SELLER_NAME;
WITH TOTAL_ACTIVE_LISTINGS AS ( SELECT SELLER_ID, COUNT(*) AS TOTAL_LISTINGS FROM LISTINGS WHERE LISTING_STATUS = 'ACTIVE' GROUP BY SELLER_ID ), AVG_SELLER_RATINGS AS ( SELECT SELLER_ID, AVG(RATING) AS AVERAGE_RATING FROM SELLER_RATINGS GROUP BY SELLER_ID ), VEHICLE_HISTORIES AS ( SELECT L.SELLER_ID, COUNT(VH.HISTORY_ID) AS TOTAL_HISTORIES FROM LISTINGS L JOIN VEHICLE_HISTORY VH ON L.VEHICLE_ID = VH.VEHICLE_ID WHERE L.LISTING_STATUS = 'ACTIVE' GROUP BY L.SELLER_ID ) SELECT S.SELLER_NAME, TAL.TOTAL_LISTINGS, AVR.AVERAGE_RATING, VH.TOTAL_HISTORIES FROM SELLERS S JOIN TOTAL_ACTIVE_LISTINGS TAL ON S.SELLER_ID = TAL.SELLER_ID JOIN AVG_SELLER_RATINGS AVR ON S.SELLER_ID = AVR.SELLER_ID JOIN VEHICLE_HISTORIES VH ON S.SELLER_ID = VH.SELLER_ID ORDER BY S.SELLER_NAME ASC;

