WITH TOTALACCESSDURATION AS ( SELECT USER_ID, SUM(ACCESS_DURATION) AS TOTAL_ACCESS_DURATION FROM ACCESS_LOGS GROUP BY USER_ID ), AVERAGERESPONSETIMEPERTRIAL AS ( SELECT TRIAL_ID, AVG(RESPONSE_TIME) AS AVERAGE_RESPONSE_TIME FROM RESPONSES GROUP BY TRIAL_ID ), TOTALAVERAGERESPONSETIMEPERUSER AS ( SELECT USER_ID, SUM(AVERAGE_RESPONSE_TIME) AS TOTAL_AVERAGE_RESPONSE_TIME FROM ACCESS_LOGS INNER JOIN TRIALS ON ACCESS_LOGS.TRIAL_ID = TRIALS.TRIAL_ID INNER JOIN AVERAGERESPONSETIMEPERTRIAL ON TRIALS.TRIAL_ID = AVERAGERESPONSETIMEPERTRIAL.TRIAL_ID GROUP BY USER_ID ) SELECT U.USERNAME, COALESCE(TOTALAVERAGERESPONSETIMEPERUSER.TOTAL_AVERAGE_RESPONSE_TIME, 0) AS TOTAL_AVERAGE_RESPONSE_TIME, TOTALACCESSDURATION.TOTAL_ACCESS_DURATION FROM USERS U LEFT JOIN TOTALAVERAGERESPONSETIMEPERUSER ON U.USER_ID = TOTALAVERAGERESPONSETIMEPERUSER.USER_ID INNER JOIN TOTALACCESSDURATION ON U.USER_ID = TOTALACCESSDURATION.USER_ID ORDER BY TOTALACCESSDURATION.TOTAL_ACCESS_DURATION DESC;
WITH USERACCESS AS ( SELECT U.USER_ID, U.USERNAME, SUM(AL.ACCESS_DURATION) AS TOTAL_ACCESS_DURATION FROM USERS U JOIN ACCESS_LOGS AL ON U.USER_ID = AL.USER_ID GROUP BY U.USER_ID ), AVERAGERESPONSETIME AS ( SELECT R.TRIAL_ID, AVG(R.RESPONSE_TIME) AS AVG_RESPONSE_TIME FROM RESPONSES R GROUP BY R.TRIAL_ID ) SELECT UA.USERNAME, SUM(ART.AVG_RESPONSE_TIME) AS TOTAL_AVG_RESPONSE_TIME, UA.TOTAL_ACCESS_DURATION FROM USERACCESS UA JOIN ACCESS_LOGS AL ON UA.USER_ID = AL.USER_ID JOIN AVERAGERESPONSETIME ART ON AL.TRIAL_ID = ART.TRIAL_ID GROUP BY UA.USER_ID, UA.USERNAME, UA.TOTAL_ACCESS_DURATION ORDER BY UA.TOTAL_ACCESS_DURATION DESC;

