WITH FILTERED_DATA AS ( SELECT EC.COUNTRY_CODE, AVG(EC.CONSUMPTION_PER_CAPITA) AS AVG_CONSUMPTION FROM ENERGY_CONSUMPTION EC WHERE EC.ENERGY_SOURCE IN ('SOLAR', 'WIND') AND EC.DATA_SOURCE IN ('FIELD STUDIES', 'SATELLITE IMAGERY') GROUP BY EC.COUNTRY_CODE ), MAX_AVG_CONSUMPTION AS ( SELECT MAX(AVG_CONSUMPTION) AS MAX_CONSUMPTION FROM FILTERED_DATA ) SELECT C.NAME AS COUNTRY_NAME, FD.AVG_CONSUMPTION FROM COUNTRIES C INNER JOIN FILTERED_DATA FD ON C.CODE = FD.COUNTRY_CODE INNER JOIN MAX_AVG_CONSUMPTION MAC ON FD.AVG_CONSUMPTION = MAC.MAX_CONSUMPTION;

