SELECT COUNT(*) FROM ( SELECT DISTINCT TPR.USER_ID, TPR.PRODUCT_ID FROM PRODUCT_RECOMMENDATIONS TPR JOIN ( SELECT USER_ID, PRODUCT_ID, REASON FROM PRODUCT_RECOMMENDATIONS PR1 WHERE PR1.PRIORITY = ( SELECT MAX(PRIORITY) FROM PRODUCT_RECOMMENDATIONS PR2 WHERE PR2.USER_ID = PR1.USER_ID ) ) AS TOP_RECS ON TPR.USER_ID = TOP_RECS.USER_ID AND TPR.PRODUCT_ID = TOP_RECS.PRODUCT_ID JOIN PRODUCTS P ON TPR.PRODUCT_ID = P.PRODUCT_ID JOIN ( SELECT PRODUCT_ID, AVG(RATING) AS AVG_RATING FROM PRODUCT_REVIEWS GROUP BY PRODUCT_ID ) AS AVG_RATINGS ON P.PRODUCT_ID = AVG_RATINGS.PRODUCT_ID ) AS FINAL_RESULT;
WITH AVGREVIEWRATINGS AS ( SELECT PRODUCT_ID, AVG(RATING) AS AVG_RATING FROM PRODUCT_REVIEWS GROUP BY PRODUCT_ID ), RANKEDRECOMMENDATIONS AS ( SELECT PR.USER_ID, PR.PRODUCT_ID, PR.REASON, PR.PRIORITY FROM PRODUCT_RECOMMENDATIONS PR ), TOPPRIORITYRECOMMENDATIONS AS ( SELECT USER_ID, PRODUCT_ID, REASON FROM RANKEDRECOMMENDATIONS R WHERE PRIORITY = ( SELECT MAX(PRIORITY) FROM RANKEDRECOMMENDATIONS R2 WHERE R2.USER_ID = R.USER_ID ) ) SELECT COUNT(*) FROM TOPPRIORITYRECOMMENDATIONS TPR JOIN PRODUCTS P ON TPR.PRODUCT_ID = P.PRODUCT_ID JOIN AVGREVIEWRATINGS ARR ON P.PRODUCT_ID = ARR.PRODUCT_ID;

