SELECT I.INSTITUTION_NAME, P.AVERAGE_CGPA, R.RATING FROM INSTITUTIONS I JOIN PERFORMANCE P ON I.INSTITUTION_ID = P.INSTITUTION_ID AND P.SEMESTER_ID = ( SELECT MAX(S.SEMESTER_ID) FROM SEMESTERS S WHERE S.INSTITUTION_ID = I.INSTITUTION_ID ) JOIN INSTITUTION_RATINGS R ON I.INSTITUTION_ID = R.INSTITUTION_ID AND R.RATING_YEAR = ( SELECT MAX(R2.RATING_YEAR) FROM INSTITUTION_RATINGS R2 WHERE R2.INSTITUTION_ID = I.INSTITUTION_ID ) ORDER BY I.INSTITUTION_NAME ASC;
WITH LATESTSEMESTER AS ( SELECT SEMESTER_ID FROM SEMESTERS ORDER BY SEMESTER_ID DESC LIMIT 1 ), LATESTPERFORMANCE AS ( SELECT P.INSTITUTION_ID, P.AVERAGE_CGPA FROM PERFORMANCE P JOIN LATESTSEMESTER LS ON P.SEMESTER_ID = LS.SEMESTER_ID ), LATESTRATINGS AS ( SELECT R.INSTITUTION_ID, R.RATING FROM INSTITUTION_RATINGS R INNER JOIN ( SELECT INSTITUTION_ID, MAX(RATING_ID) AS MAX_RATING_ID FROM INSTITUTION_RATINGS GROUP BY INSTITUTION_ID ) AS LR ON R.INSTITUTION_ID = LR.INSTITUTION_ID AND R.RATING_ID = LR.MAX_RATING_ID ) SELECT I.INSTITUTION_NAME, IFNULL(LP.AVERAGE_CGPA, 'N/A') AS AVERAGE_CGPA_IN_LATEST_SEMESTER, IFNULL(LR.RATING, 'N/A') AS LATEST_RATING FROM INSTITUTIONS I LEFT JOIN LATESTPERFORMANCE LP ON I.INSTITUTION_ID = LP.INSTITUTION_ID LEFT JOIN LATESTRATINGS LR ON I.INSTITUTION_ID = LR.INSTITUTION_ID ORDER BY I.INSTITUTION_NAME ASC;

