WITH CITYSESSIONS AS ( SELECT S.CITY_ID, SUM(S.TOTAL_SESSIONS) AS TOTAL_SESSIONS, COALESCE(SUM(M.BOT_SESSIONS), 0) AS BOT_SESSIONS, SUM(S.TOTAL_SESSIONS) - COALESCE(SUM(M.BOT_SESSIONS), 0) AS VALID_SESSIONS FROM SESSIONS S LEFT JOIN SESSION_METRICS M ON S.SESSION_ID = M.SESSION_ID GROUP BY S.CITY_ID ), CITYDATA AS ( SELECT CS.CITY_ID, C.CITY_NAME, C.COUNTRY_ID, CR.REGION, CS.TOTAL_SESSIONS, CS.BOT_SESSIONS, CS.VALID_SESSIONS FROM CITYSESSIONS CS INNER JOIN CITIES C ON CS.CITY_ID = C.CITY_ID INNER JOIN COUNTRIES CR ON C.COUNTRY_ID = CR.COUNTRY_ID ) SELECT CITY_NAME, REGION, TOTAL_SESSIONS AS CUMULATIVE_TOTAL_SESSIONS, BOT_SESSIONS AS CUMULATIVE_BOT_SESSIONS, VALID_SESSIONS AS VALID_SESSIONS FROM CITYDATA ORDER BY CUMULATIVE_TOTAL_SESSIONS DESC;
WITH REGIONALSESSIONS AS ( SELECT CI.CITY_NAME, CO.REGION, SUM(SE.TOTAL_SESSIONS) AS TOTAL_SESSIONS, SUM(SM.BOT_SESSIONS) AS BOT_SESSIONS FROM SESSIONS SE JOIN CITIES CI ON SE.CITY_ID = CI.CITY_ID JOIN COUNTRIES CO ON CI.COUNTRY_ID = CO.COUNTRY_ID JOIN SESSION_METRICS SM ON SE.SESSION_ID = SM.SESSION_ID GROUP BY CI.CITY_NAME, CO.REGION ) SELECT CITY_NAME, REGION, TOTAL_SESSIONS AS CUMULATIVE_SESSIONS, BOT_SESSIONS AS CUMULATIVE_BOT_SESSIONS, (TOTAL_SESSIONS - BOT_SESSIONS) AS VALID_SESSIONS FROM REGIONALSESSIONS ORDER BY CUMULATIVE_SESSIONS DESC;

