WITH IDEAINTERACTIONS AS ( SELECT I.IDEA_ID, I.IDEA_TEXT, COUNT(II.INTERACTION_ID) AS TOTAL_INTERACTIONS FROM IDEAS I JOIN IDEA_INTERACTIONS II ON I.IDEA_ID IN (II.IDEA_ID_LEFT, II.IDEA_ID_RIGHT) GROUP BY I.IDEA_ID, I.IDEA_TEXT ), IDEAWINS AS ( SELECT IW.IDEA_ID, AVG(IW.WIN_PERCENTAGE) AS AVG_WIN_PERCENTAGE FROM IDEA_WINS IW GROUP BY IW.IDEA_ID ) SELECT II.IDEA_TEXT AS IDEA, II.TOTAL_INTERACTIONS AS TOTAL_INTERACTIONS, IW.AVG_WIN_PERCENTAGE AS AVG_WIN_PERCENTAGE FROM IDEAINTERACTIONS II JOIN IDEAWINS IW ON II.IDEA_ID = IW.IDEA_ID WHERE II.TOTAL_INTERACTIONS > 0 ORDER BY II.TOTAL_INTERACTIONS DESC, IW.AVG_WIN_PERCENTAGE DESC;

