WITH ATTENDEECOUNTS AS ( SELECT EVENT_ID, COUNT(ATTENDANCE_ID) AS ATTENDEE_COUNT FROM ATTENDANCE GROUP BY EVENT_ID ), EQUIPMENTSUMMARY AS ( SELECT EVENT_ID, SUM(QUANTITY) AS TOTAL_EQUIPMENT FROM EVENT_EQUIPMENT GROUP BY EVENT_ID ), RESOURCESUMMARY AS ( SELECT EVENT_ID, SUM(QUANTITY) AS TOTAL_RESOURCES FROM EVENT_RESOURCES GROUP BY EVENT_ID ), REVIEWSUMMARY AS ( SELECT EVENT_ID, AVG(RATING) AS AVERAGE_RATING FROM EVENT_REVIEWS GROUP BY EVENT_ID ) SELECT E.EVENT_ID, E.EVENT_TYPE_ID, E.START_DATE, E.END_DATE, E.START_TIME, E.END_TIME, E.DAY_OF_WEEK, E.PLACE, E.IS_SCHEDULED, E.COMPANY_ID, E.DESCRIPTION, AC.ATTENDEE_COUNT, COALESCE(ES.TOTAL_EQUIPMENT, 0) AS TOTAL_EQUIPMENT, COALESCE(RS.TOTAL_RESOURCES, 0) AS TOTAL_RESOURCES, COALESCE(R.AVERAGE_RATING, 0) AS AVERAGE_RATING FROM EVENTS E LEFT JOIN ATTENDEECOUNTS AC ON E.EVENT_ID = AC.EVENT_ID LEFT JOIN EQUIPMENTSUMMARY ES ON E.EVENT_ID = ES.EVENT_ID LEFT JOIN RESOURCESUMMARY RS ON E.EVENT_ID = RS.EVENT_ID LEFT JOIN REVIEWSUMMARY R ON E.EVENT_ID = R.EVENT_ID ORDER BY E.EVENT_ID;
WITH EVENTATTENDEES AS ( SELECT E.EVENT_ID, COUNT(R.USER_ID) AS ATTENDEES_COUNT FROM EVENTS E LEFT JOIN REGISTRATIONS R ON E.EVENT_ID = R.EVENT_ID GROUP BY E.EVENT_ID ), EVENTEQUIPMENT AS ( SELECT E.EVENT_ID, SUM(EE.QUANTITY) AS TOTAL_EQUIPMENT_REQUIRED FROM EVENTS E LEFT JOIN EVENT_EQUIPMENT EE ON E.EVENT_ID = EE.EVENT_ID GROUP BY E.EVENT_ID ), EVENTRESOURCES AS ( SELECT E.EVENT_ID, SUM(ER.QUANTITY) AS TOTAL_RESOURCE_REQUIRED FROM EVENTS E LEFT JOIN EVENT_RESOURCES ER ON E.EVENT_ID = ER.EVENT_ID GROUP BY E.EVENT_ID ), EVENTRATINGS AS ( SELECT E.EVENT_ID, AVG(ER.RATING) AS AVERAGE_RATING FROM EVENTS E LEFT JOIN EVENT_REVIEWS ER ON E.EVENT_ID = ER.EVENT_ID GROUP BY E.EVENT_ID ) SELECT E.EVENT_ID, E.EVENT_TYPE_ID, E.START_DATE, E.END_DATE, E.START_TIME, E.END_TIME, E.DAY_OF_WEEK, E.PLACE, E.IS_SCHEDULED, E.COMPANY_ID, E.DESCRIPTION, EA.ATTENDEES_COUNT, EE.TOTAL_EQUIPMENT_REQUIRED, ER.TOTAL_RESOURCE_REQUIRED, ERAT.AVERAGE_RATING FROM EVENTS E LEFT JOIN EVENTATTENDEES EA ON E.EVENT_ID = EA.EVENT_ID LEFT JOIN EVENTEQUIPMENT EE ON E.EVENT_ID = EE.EVENT_ID LEFT JOIN EVENTRESOURCES ER ON E.EVENT_ID = ER.EVENT_ID LEFT JOIN EVENTRATINGS ERAT ON E.EVENT_ID = ERAT.EVENT_ID ORDER BY E.EVENT_ID;

