WITH QUALITYCONTROLCTE AS ( SELECT BATCH_ID FROM QUALITY_CONTROLS WHERE CONTROL_RESULT = 'PASS' GROUP BY BATCH_ID ), ACCESSLOGSCTE AS ( SELECT BATCH_ID, MAX(ACCESS_DATE) AS LATEST_ACCESS_DATE FROM ACCESS_LOGS WHERE ACCESS_DATE > '2023-01-01' GROUP BY BATCH_ID ) SELECT W.BATCH_NUMBER FROM WINES W INNER JOIN BATCHES B ON W.BATCH_NUMBER = B.BATCH_NUMBER LEFT JOIN QUALITYCONTROLCTE QCC ON B.BATCH_ID = QCC.BATCH_ID LEFT JOIN ACCESSLOGSCTE ALC ON B.BATCH_ID = ALC.BATCH_ID WHERE W.FIXED_ACIDITY > 5.0 AND W.RESIDUAL_SUGAR < 2.0 AND QCC.BATCH_ID IS NOT NULL AND ALC.LATEST_ACCESS_DATE IS NOT NULL ORDER BY ALC.LATEST_ACCESS_DATE DESC LIMIT 1;
WITH RECENT_ACCESS AS ( SELECT A.BATCH_ID, A.ACCESS_DATE FROM ACCESS_LOGS A WHERE A.ACCESS_DATE > '2023-01-01' ), PASSED_QUALITY AS ( SELECT QC.BATCH_ID FROM QUALITY_CONTROLS QC WHERE QC.CONTROL_RESULT = 'PASSED' ), FILTERED_WINES AS ( SELECT W.BATCH_NUMBER, W.FIXED_ACIDITY, W.RESIDUAL_SUGAR FROM WINES W WHERE W.FIXED_ACIDITY > 5.0 AND W.RESIDUAL_SUGAR < 2.0 ) SELECT FA.BATCH_NUMBER FROM FILTERED_WINES FA JOIN PASSED_QUALITY PQ ON FA.BATCH_NUMBER = PQ.BATCH_ID JOIN RECENT_ACCESS RA ON FA.BATCH_NUMBER = RA.BATCH_ID ORDER BY RA.ACCESS_DATE DESC LIMIT 1;

