SELECT D.DISTRIBUTION_NAME, AVG(V.DATA_VALUE) AS AVERAGE_DATA_VALUE FROM DATA_VALUES V JOIN DISTRIBUTIONS D ON V.DISTRIBUTION_ID = D.DISTRIBUTION_ID JOIN FIELDS F ON V.FIELD_ID = F.FIELD_ID JOIN BUILDING_OBJECTS O ON F.OBJECT_ID = O.OBJECT_ID JOIN BUILDING_CLASSES C ON O.CLASS_ID = C.CLASS_ID WHERE C.IS_ACTIVE = 1 AND O.IS_ACTIVE = 1 AND F.IS_ACTIVE = 1 AND V.IS_ACTIVE = 1 GROUP BY D.DISTRIBUTION_NAME ORDER BY AVERAGE_DATA_VALUE DESC;
SELECT D.DISTRIBUTION_NAME, AVG(V.DATA_VALUE) AS AVERAGE_VALUE FROM DISTRIBUTIONS D JOIN DATA_VALUES V ON D.DISTRIBUTION_ID = V.DISTRIBUTION_ID JOIN FIELDS F ON V.FIELD_ID = F.FIELD_ID JOIN BUILDING_OBJECTS O ON F.OBJECT_ID = O.OBJECT_ID JOIN BUILDING_CLASSES C ON O.CLASS_ID = C.CLASS_ID WHERE D.IS_ACTIVE = 1 AND O.IS_ACTIVE = 1 AND F.IS_ACTIVE = 1 AND V.IS_ACTIVE = 1 AND C.IS_ACTIVE = 1 GROUP BY D.DISTRIBUTION_NAME ORDER BY AVERAGE_VALUE DESC;

