ORDER BY P.PORTFOLIO_NAME;
WITH PORTFOLIO_RETURNS AS ( SELECT P.PORTFOLIO_ID, P.PORTFOLIO_NAME, AVG(PM.RETURNS) AS AVERAGE_RETURNS FROM PORTFOLIOS P LEFT JOIN PERFORMANCE_METRICS PM ON P.PORTFOLIO_ID = PM.PORTFOLIO_ID GROUP BY P.PORTFOLIO_ID, P.PORTFOLIO_NAME ), PORTFOLIO_SHARES AS ( SELECT P.PORTFOLIO_ID, SUM(I.SHARES) AS TOTAL_SHARES FROM PORTFOLIOS P LEFT JOIN INVESTMENTS I ON P.PORTFOLIO_ID = I.PORTFOLIO_ID GROUP BY P.PORTFOLIO_ID ) SELECT PR.PORTFOLIO_NAME, PR.AVERAGE_RETURNS, PS.TOTAL_SHARES FROM PORTFOLIO_RETURNS PR LEFT JOIN PORTFOLIO_SHARES PS ON PR.PORTFOLIO_ID = PS.PORTFOLIO_ID ORDER BY PR.PORTFOLIO_NAME;

