WITH INVESTMENTSUMMARY AS ( SELECT I.CRYPTO_ID, SUM(I.AMOUNT) AS TOTAL_INVESTMENT FROM INVESTMENTS I WHERE I.USER_ID = 1 GROUP BY I.CRYPTO_ID ), PRICESUMMARY AS ( SELECT MD.CRYPTO_ID, AVG(MD.CLOSE_PRICE) AS AVG_CLOSE_PRICE FROM MARKET_DATA MD GROUP BY MD.CRYPTO_ID ) SELECT CRYPT.NAME AS CRYPTO_NAME, CASE WHEN INV.TOTAL_INVESTMENT > 1000 AND PRICE.AVG_CLOSE_PRICE > 10000 THEN 'HIGH INVESTMENT, HIGH PRICE' WHEN INV.TOTAL_INVESTMENT > 1000 AND PRICE.AVG_CLOSE_PRICE <= 10000 THEN 'HIGH INVESTMENT, LOW PRICE' WHEN INV.TOTAL_INVESTMENT <= 1000 AND PRICE.AVG_CLOSE_PRICE > 10000 THEN 'LOW INVESTMENT, HIGH PRICE' ELSE 'LOW INVESTMENT, LOW PRICE' END AS INVESTMENT_ANALYSIS FROM INVESTMENTSUMMARY INV JOIN PRICESUMMARY PRICE ON INV.CRYPTO_ID = PRICE.CRYPTO_ID JOIN CRYPTOCURRENCIES CRYPT ON INV.CRYPTO_ID = CRYPT.CRYPTO_ID ORDER BY CRYPT.NAME;
WITH USERINVESTMENTS AS ( SELECT I.CRYPTO_ID, SUM(I.AMOUNT) AS TOTAL_INVESTMENT FROM INVESTMENTS I WHERE I.USER_ID = 1 GROUP BY I.CRYPTO_ID ), MARKETPERFORMANCE AS ( SELECT MD.CRYPTO_ID, AVG(MD.CLOSE_PRICE) AS AVG_CLOSE_PRICE FROM MARKET_DATA MD GROUP BY MD.CRYPTO_ID ) SELECT C.NAME AS CRYPTO_NAME, CASE WHEN UI.TOTAL_INVESTMENT > 1000 AND MP.AVG_CLOSE_PRICE > 10000 THEN 'HIGH INVESTMENT, HIGH PRICE' WHEN UI.TOTAL_INVESTMENT > 1000 AND MP.AVG_CLOSE_PRICE <= 10000 THEN 'HIGH INVESTMENT, LOW PRICE' WHEN UI.TOTAL_INVESTMENT <= 1000 AND MP.AVG_CLOSE_PRICE > 10000 THEN 'LOW INVESTMENT, HIGH PRICE' ELSE 'LOW INVESTMENT, LOW PRICE' END AS INVESTMENT_ANALYSIS FROM USERINVESTMENTS UI JOIN CRYPTOCURRENCIES C ON UI.CRYPTO_ID = C.CRYPTO_ID JOIN MARKETPERFORMANCE MP ON C.CRYPTO_ID = MP.CRYPTO_ID ORDER BY C.NAME;

