WITH USERBORROWINGSTATS AS ( SELECT BH.USER_ID, COUNT(BH.BOOK_ID) AS TOTAL_BOOKS_BORROWED, AVG(R.RATING) AS AVG_RATING FROM BORROWING_HISTORY BH LEFT JOIN RATINGS_AND_REVIEWS R ON BH.BOOK_ID = R.BOOK_ID AND BH.USER_ID = R.USER_ID GROUP BY BH.USER_ID ), TOPBORROWERS AS ( SELECT USER_ID, TOTAL_BOOKS_BORROWED, AVG_RATING FROM USERBORROWINGSTATS ORDER BY TOTAL_BOOKS_BORROWED DESC, AVG_RATING DESC LIMIT 5 ) SELECT U.USER_NAME, TB.TOTAL_BOOKS_BORROWED, TB.AVG_RATING FROM TOPBORROWERS TB JOIN USERS U ON TB.USER_ID = U.USER_ID;

