SELECT 
    U.USER_NAME, 
    U.ROLE, 
    COUNT(AL.ACCESS_ID) AS TOTAL_ACCESSES, 
    SUM(CASE WHEN AL.ACCESS_TYPE = 'LOGIN' THEN 1 ELSE 0 END) AS TOTAL_LOGINS, 
    SUM(CASE WHEN AL.ACCESS_TYPE = 'LOGOUT' THEN 1 ELSE 0 END) AS TOTAL_LOGOUTS, 
    COUNT(R.REPORT_ID) AS TOTAL_REPORTS, 
    SUM(CASE WHEN R.REPORT_TYPE = 'TREND ANALYSIS' THEN 1 ELSE 0 END) AS TOTAL_TREND_REPORTS, 
    SUM(CASE WHEN R.REPORT_TYPE = 'COMPARATIVE ANALYSIS' THEN 1 ELSE 0 END) AS TOTAL_COMPARATIVE_REPORTS
FROM 
    USERS U
LEFT JOIN 
    ACCESS_LOGS AL ON U.USER_ID = AL.USER_ID
LEFT JOIN 
    REPORTS R ON U.USER_ID = R.USER_ID
GROUP BY 
    U.USER_ID, U.USER_NAME, U.ROLE
ORDER BY 
    U.USER_NAME, U.ROLE;
WITH ACCESSSTATS AS ( SELECT USER_ID, COUNT(ACCESS_ID) AS ACCESS_COUNT, SUM(CASE WHEN ACCESS_TYPE = 'LOGIN' THEN 1 ELSE 0 END) AS LOGIN_COUNT, SUM(CASE WHEN ACCESS_TYPE = 'LOGOUT' THEN 1 ELSE 0 END) AS LOGOUT_COUNT FROM ACCESS_LOGS GROUP BY USER_ID ), REPORTSTATS AS ( SELECT USER_ID, COUNT(REPORT_ID) AS REPORT_COUNT, SUM(CASE WHEN REPORT_TYPE = 'TREND ANALYSIS' THEN 1 ELSE 0 END) AS TREND_ANALYSIS_COUNT, SUM(CASE WHEN REPORT_TYPE = 'COMPARATIVE ANALYSIS' THEN 1 ELSE 0 END) AS COMPARATIVE_ANALYSIS_COUNT FROM REPORTS GROUP BY USER_ID ) SELECT U.USER_NAME, U.ROLE, COALESCE(A.ACCESS_COUNT, 0) AS ACCESS_COUNT, COALESCE(A.LOGIN_COUNT, 0) AS LOGIN_COUNT, COALESCE(A.LOGOUT_COUNT, 0) AS LOGOUT_COUNT, COALESCE(R.REPORT_COUNT, 0) AS REPORT_COUNT, COALESCE(R.TREND_ANALYSIS_COUNT, 0) AS TREND_ANALYSIS_REPORT_COUNT, COALESCE(R.COMPARATIVE_ANALYSIS_COUNT, 0) AS COMPARATIVE_ANALYSIS_REPORT_COUNT FROM USERS U LEFT JOIN ACCESSSTATS A ON U.USER_ID = A.USER_ID LEFT JOIN REPORTSTATS R ON U.USER_ID = R.USER_ID ORDER BY U.USER_NAME, U.ROLE;

