WITH CONFERENCEPLAYERS AS ( SELECT P.PLAYER_ID, P.PLAYER_NAME, T.CONFERENCE_ID FROM PLAYERS P JOIN TEAMS T ON P.TEAM_ID = T.TEAM_ID ), PLAYERAVGGOALS AS ( SELECT GS.PLAYER_ID, AVG(GS.GA) AS AVG_GOALS_AGAINST FROM GAME_STATISTICS GS GROUP BY GS.PLAYER_ID ), MAXGOALSPERCONFERENCE AS ( SELECT CP.CONFERENCE_ID, MAX(PAG.AVG_GOALS_AGAINST) AS MAX_AVG_GOALS FROM CONFERENCEPLAYERS CP JOIN PLAYERAVGGOALS PAG ON CP.PLAYER_ID = PAG.PLAYER_ID GROUP BY CP.CONFERENCE_ID ) SELECT CP.PLAYER_NAME, CP.CONFERENCE_ID FROM CONFERENCEPLAYERS CP JOIN PLAYERAVGGOALS PAG ON CP.PLAYER_ID = PAG.PLAYER_ID JOIN MAXGOALSPERCONFERENCE MGPC ON CP.CONFERENCE_ID = MGPC.CONFERENCE_ID WHERE PAG.AVG_GOALS_AGAINST = MGPC.MAX_AVG_GOALS;

