WITH EDUCATIONINCOMECOUNTS AS ( SELECT E.EDUCATION_NAME, COUNT(CASE WHEN I.INCOME_LEVEL = '>50K' THEN 1 END) AS COUNT_HIGH_INCOME, COUNT(I.INDIVIDUAL_ID) AS COUNT_TOTAL FROM INDIVIDUALS I INNER JOIN EDUCATIONS E ON I.EDUCATION_ID = E.EDUCATION_ID GROUP BY E.EDUCATION_NAME ), EDUCATIONINCOMEPERCENTAGES AS ( SELECT EDUCATION_NAME, (COUNT_HIGH_INCOME * 100.0 / COUNT_TOTAL) AS PERCENTAGE FROM EDUCATIONINCOMECOUNTS ) SELECT EIP.EDUCATION_NAME, EIP.PERCENTAGE FROM EDUCATIONINCOMEPERCENTAGES EIP WHERE EIP.PERCENTAGE IN ( SELECT EIP2.PERCENTAGE FROM EDUCATIONINCOMEPERCENTAGES EIP2 ORDER BY EIP2.PERCENTAGE DESC LIMIT 5 ) ORDER BY EIP.PERCENTAGE DESC;
WITH HIGH_INCOME_INDIVIDUALS AS ( SELECT EDUCATION_ID, COUNT(*) AS HIGH_INCOME_COUNT FROM INDIVIDUALS WHERE INCOME_LEVEL = '>50K' GROUP BY EDUCATION_ID ), TOTAL_INDIVIDUALS AS ( SELECT EDUCATION_ID, COUNT(*) AS TOTAL_COUNT FROM INDIVIDUALS GROUP BY EDUCATION_ID ), EDUCATION_PERCENTAGES AS ( SELECT E.EDUCATION_NAME, (HI.HIGH_INCOME_COUNT * 100.0 / T.TOTAL_COUNT) AS PERCENTAGE FROM HIGH_INCOME_INDIVIDUALS HI INNER JOIN TOTAL_INDIVIDUALS T ON HI.EDUCATION_ID = T.EDUCATION_ID INNER JOIN EDUCATIONS E ON HI.EDUCATION_ID = E.EDUCATION_ID ) SELECT EDUCATION_NAME, PERCENTAGE FROM EDUCATION_PERCENTAGES ORDER BY PERCENTAGE DESC LIMIT 5;

