WITH AVERAGERATING AS ( SELECT BEER_ID, AVG(RATING) AS AVERAGE_RATING FROM RATINGS GROUP BY BEER_ID ), SOLDQUANTITY AS ( SELECT BEER_ID, SUM(QUANTITY_ORDERED) AS TOTAL_SOLD FROM ORDERS GROUP BY BEER_ID ), COMBINEDMETRICS AS ( SELECT B.BEER_ID, B.BEER_NAME, (AR.AVERAGE_RATING * SQ.TOTAL_SOLD) AS TOTAL_RATING_VALUE FROM BEERS B JOIN AVERAGERATING AR ON B.BEER_ID = AR.BEER_ID JOIN SOLDQUANTITY SQ ON B.BEER_ID = SQ.BEER_ID ) SELECT BEER_NAME, TOTAL_RATING_VALUE FROM COMBINEDMETRICS ORDER BY TOTAL_RATING_VALUE DESC LIMIT 5;
WITH BEERSALES AS ( SELECT B.BEER_ID, B.BEER_NAME, AVG(R.RATING) AS AVG_RATING, SUM(O.QUANTITY_ORDERED) AS TOTAL_SOLD FROM BEERS AS B JOIN RATINGS AS R ON B.BEER_ID = R.BEER_ID JOIN ORDERS AS O ON B.BEER_ID = O.BEER_ID GROUP BY B.BEER_ID, B.BEER_NAME ), TOPRATEDBEERS AS ( SELECT BS.BEER_ID, BS.BEER_NAME, BS.AVG_RATING, BS.TOTAL_SOLD, (BS.AVG_RATING * BS.TOTAL_SOLD) AS TOTAL_RATING_VALUE FROM BEERSALES AS BS ORDER BY TOTAL_RATING_VALUE DESC LIMIT 5 ) SELECT TRB.BEER_NAME, TRB.TOTAL_RATING_VALUE FROM TOPRATEDBEERS AS TRB;

