WITH PATHWAYCOUNTS AS ( SELECT GP.GENE_ID, COUNT(GP.PATHWAY_ID) AS PATHWAY_COUNT FROM GENE_PATHWAY GP GROUP BY GP.GENE_ID ), REGULATIONCOUNTS AS ( SELECT GR.GENE_ID_1, COUNT(GR.GENE_ID_2) AS REGULATION_COUNT FROM GENE_REGULATION GR GROUP BY GR.GENE_ID_1 ), EXPRESSIONCOUNTS AS ( SELECT GE.GENE_ID, COUNT(DISTINCT GE.EXPERIMENT_ID) AS EXPERIMENT_COUNT FROM GENE_EXPRESSION GE GROUP BY GE.GENE_ID ) SELECT G.GENE_NAME, COALESCE(PC.PATHWAY_COUNT, 0) + COALESCE(RC.REGULATION_COUNT, 0) + COALESCE(EC.EXPERIMENT_COUNT, 0) AS INTERACTION_COUNT FROM GENES G LEFT JOIN PATHWAYCOUNTS PC ON G.GENE_ID = PC.GENE_ID LEFT JOIN REGULATIONCOUNTS RC ON G.GENE_ID = RC.GENE_ID_1 LEFT JOIN EXPRESSIONCOUNTS EC ON G.GENE_ID = EC.GENE_ID ORDER BY INTERACTION_COUNT DESC, G.GENE_NAME ASC;

