WITH CONTENTPOPULARITY AS ( SELECT C.CONTENT_ID, SUM(CASE WHEN CE.ENGAGEMENT_TYPE IN ('LIKE', 'COMMENT', 'SHARE') THEN 1 ELSE 0 END) AS TOTAL_ENGAGEMENTS, COUNT(DISTINCT CV.EMPLOYEE_ID) AS VIEWS_COUNT, COUNT(DISTINCT CS.EMPLOYEE_ID) AS SHARES_COUNT FROM CONTENT C LEFT JOIN CONTENT_ENGAGEMENT CE ON C.CONTENT_ID = CE.CONTENT_ID LEFT JOIN CONTENT_VIEWS CV ON C.CONTENT_ID = CV.CONTENT_ID LEFT JOIN CONTENT_SHARES CS ON C.CONTENT_ID = CS.CONTENT_ID WHERE C.STATUS = 'PUBLISHED' GROUP BY C.CONTENT_ID ), CONTENTPOPULARITYSCORE AS ( SELECT CONTENT_ID, (TOTAL_ENGAGEMENTS + VIEWS_COUNT + SHARES_COUNT) AS POPULARITY_SCORE FROM CONTENTPOPULARITY ) SELECT MAX(POPULARITY_SCORE) AS MAX_POPULARITY_SCORE FROM CONTENTPOPULARITYSCORE;
WITH ENGAGEMENTCOUNTS AS ( SELECT CONTENT_ID, COUNT(*) AS TOTAL_ENGAGEMENTS FROM CONTENT_ENGAGEMENT GROUP BY CONTENT_ID ), VIEWCOUNTS AS ( SELECT CONTENT_ID, COUNT(*) AS TOTAL_VIEWS FROM CONTENT_VIEWS GROUP BY CONTENT_ID ), SHARECOUNTS AS ( SELECT CONTENT_ID, COUNT(*) AS TOTAL_SHARES FROM CONTENT_SHARES GROUP BY CONTENT_ID ), POPULARITYCALCULATION AS ( SELECT C.CONTENT_ID, C.TITLE, COALESCE(E.TOTAL_ENGAGEMENTS, 0) + COALESCE(V.TOTAL_VIEWS, 0) + COALESCE(S.TOTAL_SHARES, 0) AS CALCULATED_POPULARITY FROM CONTENT C LEFT JOIN ENGAGEMENTCOUNTS E ON C.CONTENT_ID = E.CONTENT_ID LEFT JOIN VIEWCOUNTS V ON C.CONTENT_ID = V.CONTENT_ID LEFT JOIN SHARECOUNTS S ON C.CONTENT_ID = S.CONTENT_ID WHERE C.STATUS = 'PUBLISHED' ) SELECT MAX(CALCULATED_POPULARITY) AS HIGHEST_POPULARITY_SCORE FROM POPULARITYCALCULATION;

