WITH TOPICENGAGEMENT AS ( SELECT A.TOPIC_ID, SUM(A.VIEWS + A.DOWNLOADS) AS TOTAL_ENGAGEMENT FROM ARTICLES A GROUP BY A.TOPIC_ID ), AVGENGAGEMENT AS ( SELECT AVG(VIEWS + DOWNLOADS) AS AVG_ENGAGEMENT FROM ARTICLES ) SELECT TE.TOPIC_ID FROM TOPICENGAGEMENT TE CROSS JOIN AVGENGAGEMENT AE WHERE TE.TOTAL_ENGAGEMENT > AE.AVG_ENGAGEMENT ORDER BY TE.TOTAL_ENGAGEMENT DESC LIMIT 1;

