WITH CANDIDATERESULTS AS ( SELECT R.CANDIDATE_ID, R.OFFICE_ID, R.DISTRICT_ID, R.VOTES, R.PERCENTAGE, O.OFFICE_NAME, D.STATE, C.COUNTY_NAME, CAN.NAME AS CANDIDATE_NAME, CAN.PARTY FROM RESULTS R INNER JOIN OFFICES O ON R.OFFICE_ID = O.OFFICE_ID INNER JOIN DISTRICTS D ON R.DISTRICT_ID = D.DISTRICT_ID INNER JOIN COUNTIES C ON R.COUNTY_ID = C.COUNTY_ID INNER JOIN CANDIDATES CAN ON R.CANDIDATE_ID = CAN.CANDIDATE_ID ), OFFICEAVERAGES AS ( SELECT OFFICE_ID, AVG(PERCENTAGE) AS AVG_PERCENTAGE FROM RESULTS GROUP BY OFFICE_ID ), DISTRICTAVERAGES AS ( SELECT DISTRICT_ID, AVG(PERCENTAGE) AS AVG_PERCENTAGE FROM RESULTS GROUP BY DISTRICT_ID ) SELECT CR.CANDIDATE_NAME, SUM(CR.PERCENTAGE - OA.AVG_PERCENTAGE - DA.AVG_PERCENTAGE) AS TOTAL_PERFORMANCE_DIFFERENCE FROM CANDIDATERESULTS CR LEFT JOIN OFFICEAVERAGES OA ON CR.OFFICE_ID = OA.OFFICE_ID LEFT JOIN DISTRICTAVERAGES DA ON CR.DISTRICT_ID = DA.DISTRICT_ID GROUP BY CR.CANDIDATE_ID ORDER BY TOTAL_PERFORMANCE_DIFFERENCE DESC;
WITH OFFICEDISTRICTAVG AS ( SELECT R.OFFICE_ID, R.DISTRICT_ID, AVG(R.PERCENTAGE) AS AVG_PERCENTAGE FROM RESULTS R GROUP BY R.OFFICE_ID, R.DISTRICT_ID ), CANDIDATEDETAILS AS ( SELECT R.CANDIDATE_ID, R.OFFICE_ID, R.DISTRICT_ID, R.PERCENTAGE, C.NAME AS CANDIDATE_NAME FROM RESULTS R JOIN CANDIDATES C ON R.CANDIDATE_ID = C.CANDIDATE_ID ) SELECT CD.CANDIDATE_NAME, SUM(CD.PERCENTAGE - ODA.AVG_PERCENTAGE) AS TOTAL_PERFORMANCE_DIFFERENCE FROM CANDIDATEDETAILS CD JOIN OFFICEDISTRICTAVG ODA ON CD.OFFICE_ID = ODA.OFFICE_ID AND CD.DISTRICT_ID = ODA.DISTRICT_ID GROUP BY CD.CANDIDATE_ID, CD.CANDIDATE_NAME ORDER BY TOTAL_PERFORMANCE_DIFFERENCE DESC;

