WITH CHERBOURGEMBARKATIONS AS ( SELECT T.TICKET_ID, T.PASSENGER_ID FROM TICKETS T JOIN EMBARKATION_LOGS EL ON T.TICKET_ID = EL.TICKET_ID WHERE T.EMBARKED = 'CHERBOURG' AND EL.EMBARKATION_TIME BETWEEN '2023-04-01 00:00:00' AND '2023-04-30 23:59:59' ), PASSENGERCABINASSIGNMENTS AS ( SELECT PC.PASSENGER_ID, C.CABIN_NUMBER FROM PASSENGER_CABINS PC JOIN CABINS C ON PC.CABIN_ID = C.CABIN_ID ), LOYALTYPROGRAMDETAILS AS ( SELECT PL.PASSENGER_ID, LP.PROGRAM_NAME FROM PASSENGER_LOYALTY PL JOIN LOYALTY_PROGRAMS LP ON PL.PROGRAM_ID = LP.PROGRAM_ID WHERE PL.POINTS_EARNED > 500 ) SELECT P.NAME, PCA.CABIN_NUMBER, LP.PROGRAM_NAME FROM PASSENGERS P JOIN CHERBOURGEMBARKATIONS CE ON P.PASSENGER_ID = CE.PASSENGER_ID JOIN PASSENGERCABINASSIGNMENTS PCA ON P.PASSENGER_ID = PCA.PASSENGER_ID JOIN LOYALTYPROGRAMDETAILS LP ON P.PASSENGER_ID = LP.PASSENGER_ID ORDER BY P.NAME, PCA.CABIN_NUMBER, LP.PROGRAM_NAME;

