SELECT A.AUTHOR_NAME, (COALESCE(SUM(CASE WHEN UA.ACTIVITY_TYPE = 'VIEW' THEN 1 ELSE 0 END), 0) + COALESCE(SUM(CASE WHEN UA.ACTIVITY_TYPE = 'COMMENT' THEN 1 ELSE 0 END), 0) + COALESCE(SUM(CASE WHEN UA.ACTIVITY_TYPE = 'BOOKMARK' THEN 1 ELSE 0 END), 0) + COALESCE(COUNT(H.HIT_ID), 0)) AS TOTAL_INTERACTIONS, COALESCE(AVG(R.RATING_VALUE), 0) AS AVERAGE_STORY_RATING, A.TOTAL_STORIES AS TOTAL_STORIES_PUBLISHED FROM AUTHORS A LEFT JOIN ( SELECT STORY_ID, ACTIVITY_TYPE FROM USER_ACTIVITY ) UA ON A.AUTHOR_ID = UA.STORY_ID LEFT JOIN ( SELECT STORY_ID, HIT_ID FROM HITS ) H ON A.AUTHOR_ID = H.STORY_ID LEFT JOIN ( SELECT STORY_ID, RATING_VALUE FROM RATINGS ) R ON A.AUTHOR_ID = R.STORY_ID GROUP BY A.AUTHOR_ID, A.AUTHOR_NAME, A.TOTAL_STORIES ORDER BY TOTAL_INTERACTIONS DESC;
WITH TOTALINTERACTIONS AS ( SELECT A.AUTHOR_ID, SUM(CASE WHEN UA.ACTIVITY_TYPE = 'VIEW' THEN 1 ELSE 0 END) AS TOTAL_VIEWS, SUM(CASE WHEN UA.ACTIVITY_TYPE = 'COMMENT' THEN 1 ELSE 0 END) AS TOTAL_COMMENTS, SUM(CASE WHEN UA.ACTIVITY_TYPE = 'BOOKMARK' THEN 1 ELSE 0 END) AS TOTAL_BOOKMARKS, SUM(CASE WHEN UA.ACTIVITY_TYPE = 'HIT' THEN 1 ELSE 0 END) AS TOTAL_HITS FROM AUTHORS A JOIN RATINGS R ON A.AUTHOR_ID = R.STORY_ID JOIN USER_ACTIVITY UA ON R.STORY_ID = UA.STORY_ID GROUP BY A.AUTHOR_ID ), AVERAGERATINGS AS ( SELECT R.STORY_ID, AVG(R.RATING_VALUE) AS AVERAGE_RATING FROM RATINGS R GROUP BY R.STORY_ID ), AUTHORAVERAGERATINGS AS ( SELECT A.AUTHOR_ID, AVG(AR.AVERAGE_RATING) AS AVERAGE_STORY_RATING FROM AUTHORS A JOIN RATINGS R ON A.AUTHOR_ID = R.STORY_ID JOIN AVERAGERATINGS AR ON R.STORY_ID = AR.STORY_ID GROUP BY A.AUTHOR_ID ) SELECT A.AUTHOR_NAME, TI.TOTAL_VIEWS + TI.TOTAL_COMMENTS + TI.TOTAL_BOOKMARKS + TI.TOTAL_HITS AS TOTAL_INTERACTIONS, COALESCE(AAR.AVERAGE_STORY_RATING, 0) AS AVERAGE_STORY_RATING, A.TOTAL_STORIES FROM AUTHORS A JOIN TOTALINTERACTIONS TI ON A.AUTHOR_ID = TI.AUTHOR_ID JOIN AUTHORAVERAGERATINGS AAR ON A.AUTHOR_ID = AAR.AUTHOR_ID ORDER BY TOTAL_INTERACTIONS DESC;

