SELECT W.BATCH_NUMBER
FROM WINES W
JOIN QUALITY_CONTROLS QC ON W.WINE_ID = QC.BATCH_ID
JOIN ACCESS_LOGS A ON W.WINE_ID = A.BATCH_ID
WHERE W.FIXED_ACIDITY > 5.0
  AND W.RESIDUAL_SUGAR < 2.0
  AND QC.CONTROL_RESULT = 'PASSED'
  AND A.ACCESS_DATE > '2023-01-01'
GROUP BY W.BATCH_NUMBER, A.ACCESS_DATE
ORDER BY A.ACCESS_DATE DESC
LIMIT 1;
WITH RECENT_ACCESS AS ( SELECT DISTINCT W.BATCH_NUMBER, A.ACCESS_DATE FROM WINES W JOIN ACCESS_LOGS A ON W.WINE_ID = A.BATCH_ID WHERE W.FIXED_ACIDITY > 5.0 AND W.RESIDUAL_SUGAR < 2.0 AND A.ACCESS_DATE > '2023-01-01' ), PASSED_QUALITY AS ( SELECT DISTINCT W.BATCH_NUMBER FROM WINES W JOIN QUALITY_CONTROLS QC ON W.WINE_ID = QC.BATCH_ID WHERE QC.CONTROL_RESULT = 'PASSED' ) SELECT RA.BATCH_NUMBER FROM RECENT_ACCESS RA JOIN PASSED_QUALITY PQ ON RA.BATCH_NUMBER = PQ.BATCH_NUMBER ORDER BY RA.ACCESS_DATE DESC LIMIT 1;

