WITH MINERRORFORECASTS AS ( SELECT MIN(EF.ERROR) AS MIN_ERROR, EF.ELECTION_ID FROM ELECTION_FORECASTS EF GROUP BY EF.ELECTION_ID ) SELECT E.ELECTION_TYPE, EI.AVG_GROWTH_PERSONAL_INCOMES FROM MINERRORFORECASTS MEF JOIN ELECTIONS E ON MEF.ELECTION_ID = E.ID JOIN ( SELECT YEAR, AVG(AVERAGE_RECENT_GROWTH_PERSONAL_INCOMES) AS AVG_GROWTH_PERSONAL_INCOMES FROM ECONOMIC_INDICATORS GROUP BY YEAR ) EI ON E.YEAR = EI.YEAR JOIN ELECTION_FORECASTS EF ON MEF.ELECTION_ID = EF.ELECTION_ID AND EF.ERROR = MEF.MIN_ERROR;

