SELECT T.USER_ID, U.USER_NAME, T.BIKEID AS BIKE_ID, COALESCE(SUM(T.ROUTE_DISTANCE), 0) AS TOTAL_DISTANCE_TRAVELLED, COALESCE(SUM(ML.MAINTENANCE_COST), 0) AS TOTAL_MAINTENANCE_COST, COALESCE(SUM(P.PAYMENT_AMOUNT), 0) AS TOTAL_REVENUE FROM TRIPS T JOIN USERS U ON T.USER_ID = U.USER_ID JOIN BIKES B ON T.BIKEID = B.BIKE_ID LEFT JOIN MAINTENANCE_LOGS ML ON B.BIKE_ID = ML.BIKE_ID LEFT JOIN PAYMENTS P ON T.USER_ID = P.USER_ID GROUP BY T.USER_ID, U.USER_NAME, T.BIKEID ORDER BY T.USER_ID, T.BIKEID;
WITH USERBIKEDISTANCE AS ( SELECT T.USER_ID, T.BIKEID, SUM(T.ROUTE_DISTANCE) AS TOTAL_DISTANCE FROM TRIPS T GROUP BY T.USER_ID, T.BIKEID ), BIKEMAINTENANCECOST AS ( SELECT ML.BIKE_ID, SUM(ML.MAINTENANCE_COST) AS TOTAL_MAINTENANCE_COST FROM MAINTENANCE_LOGS ML GROUP BY ML.BIKE_ID ), USERREVENUE AS ( SELECT P.USER_ID, SUM(P.PAYMENT_AMOUNT) AS TOTAL_REVENUE FROM PAYMENTS P GROUP BY P.USER_ID ) SELECT UBD.USER_ID, U.USER_NAME, UBD.BIKEID, UBD.TOTAL_DISTANCE, BMC.TOTAL_MAINTENANCE_COST, UR.TOTAL_REVENUE FROM USERBIKEDISTANCE UBD JOIN USERS U ON UBD.USER_ID = U.USER_ID JOIN BIKEMAINTENANCECOST BMC ON UBD.BIKEID = BMC.BIKE_ID JOIN USERREVENUE UR ON UBD.USER_ID = UR.USER_ID ORDER BY UBD.USER_ID, UBD.BIKEID;

