WITH NEIGHBORHOOD_STATS AS ( SELECT N.NEIGHBORHOOD_ID, N.NEIGHBORHOOD_NAME, D.POPULATION, D.DENSITY, COUNT(CS.CRIME_ID) AS TOTAL_CRIMES FROM NEIGHBORHOODS N JOIN DEMOGRAPHIC_DATA D ON N.NEIGHBORHOOD_ID = D.NEIGHBORHOOD_ID LEFT JOIN CRIME_STATS CS ON N.NEIGHBORHOOD_ID = CS.NEIGHBORHOOD_ID GROUP BY N.NEIGHBORHOOD_ID, N.NEIGHBORHOOD_NAME, D.POPULATION, D.DENSITY ), AVG_METRICS AS ( SELECT AVG(DENSITY) AS AVG_DENSITY, AVG(TOTAL_CRIMES) AS AVG_CRIME_COUNT FROM NEIGHBORHOOD_STATS ) SELECT NS.NEIGHBORHOOD_NAME FROM NEIGHBORHOOD_STATS NS CROSS JOIN AVG_METRICS AM WHERE NS.POPULATION > 10000 AND NS.DENSITY > AM.AVG_DENSITY AND NS.TOTAL_CRIMES < AM.AVG_CRIME_COUNT ORDER BY NS.POPULATION DESC;

