WITH LATESTMODELVERSIONS AS ( SELECT MODEL_ID, MAX(VERSION_NUMBER) AS LATEST_VERSION FROM MODEL_VERSIONS GROUP BY MODEL_ID ), AUDIOFILESWITHLATESTMODEL AS ( SELECT AF.FILE_ID FROM AUDIO_FILES AF INNER JOIN LATESTMODELVERSIONS LMV ON AF.MODEL_VERSION = LMV.LATEST_VERSION ), MODELINFO AS ( SELECT M.MODEL_ID, M.MODEL_TYPE, ME.ACCURACY FROM MODELS M INNER JOIN MODEL_EVALUATIONS ME ON M.MODEL_ID = ME.MODEL_ID ), USERACCESS AS ( SELECT FILE_ID FROM FILE_USER_ACCESS GROUP BY FILE_ID ) SELECT COUNT(AFM.FILE_ID) AS COUNT_LATEST_MODEL_VERSIONS FROM AUDIOFILESWITHLATESTMODEL AFM INNER JOIN MODELINFO MI ON AFM.FILE_ID = MI.MODEL_ID INNER JOIN USERACCESS UA ON AFM.FILE_ID = UA.FILE_ID;

