SELECT 
    T.TRACK_NAME,
    A.ARTIST_NAME,
    SUM(TP.PLAY_DURATION_MS) AS TOTAL_PLAYS
FROM 
    TRACKS T
INNER JOIN 
    ALBUMS AL ON T.ALBUM_ID = AL.ALBUM_ID
INNER JOIN 
    ARTISTS A ON AL.ALBUM_ARTIST_ID = A.ARTIST_ID
INNER JOIN 
    TRACK_PLAYS TP ON T.TRACK_ID = TP.TRACK_ID
GROUP BY 
    T.TRACK_NAME, A.ARTIST_NAME
ORDER BY 
    TOTAL_PLAYS DESC
LIMIT 10;
WITH TRACK_PLAY_COUNTS AS ( SELECT T.TRACK_ID, T.TRACK_NAME, A.ARTIST_NAME, SUM(TP.PLAY_DURATION_MS) AS TOTAL_PLAYS FROM TRACKS T INNER JOIN ALBUMS AL ON T.ALBUM_ID = AL.ALBUM_ID INNER JOIN ARTISTS A ON AL.ALBUM_ARTIST_ID = A.ARTIST_ID INNER JOIN TRACK_PLAYS TP ON T.TRACK_ID = TP.TRACK_ID GROUP BY T.TRACK_ID, T.TRACK_NAME, A.ARTIST_NAME ) SELECT TRACK_NAME, ARTIST_NAME, TOTAL_PLAYS FROM TRACK_PLAY_COUNTS ORDER BY TOTAL_PLAYS DESC LIMIT 10;

