WITH VALIDATIONCOUNTS AS ( SELECT DATA_ID, SUM(CASE WHEN VALIDATION_RESULT = 'FAILED' THEN 1 ELSE 0 END) AS TOTAL_FAILED_VALIDATION FROM DATA_VALIDATION GROUP BY DATA_ID ), ACCESSCOUNTS AS ( SELECT DATA_ID, SUM(CASE WHEN ACCESS_TYPE = 'DOWNLOAD' THEN 1 ELSE 0 END) AS TOTAL_DOWNLOAD_ACCESS FROM ACCESS_LOGS GROUP BY DATA_ID ) SELECT DV.DATA_ID, VC.TOTAL_FAILED_VALIDATION, AC.TOTAL_DOWNLOAD_ACCESS, DF.FILE_SIZE FROM DATA_VALIDATION DV JOIN VALIDATIONCOUNTS VC ON DV.DATA_ID = VC.DATA_ID JOIN ACCESSCOUNTS AC ON DV.DATA_ID = AC.DATA_ID JOIN DATA_FILES DF ON DV.DATA_ID = DF.DATA_ID ORDER BY VC.TOTAL_FAILED_VALIDATION DESC;
WITH FAILED_DATA AS ( SELECT DATA_ID, COUNT(*) AS FAILED_COUNT FROM DATA_VALIDATION WHERE VALIDATION_RESULT = 'FAILED' GROUP BY DATA_ID ), ACCESS_DATA AS ( SELECT DATA_ID, COUNT(*) AS ACCESS_COUNT FROM ACCESS_LOGS WHERE ACCESS_TYPE = 'DOWNLOAD' GROUP BY DATA_ID ) SELECT ED.DATA_ID, COALESCE(FD.FAILED_COUNT, 0) AS TOTAL_FAILED_VALIDATIONS, COALESCE(AD.ACCESS_COUNT, 0) AS TOTAL_DOWNLOAD_ACCESSES, COALESCE(DFL.FILE_SIZE, 0) AS FILE_SIZE FROM ENVIRONMENTAL_DATA ED LEFT JOIN FAILED_DATA FD ON ED.DATA_ID = FD.DATA_ID LEFT JOIN ACCESS_DATA AD ON ED.DATA_ID = AD.DATA_ID LEFT JOIN DATA_FILES DFL ON ED.DATA_ID = DFL.DATA_ID ORDER BY TOTAL_FAILED_VALIDATIONS DESC;

