SELECT S.STUDY_NAME, COUNT(DISTINCT P.PARTICIPANT_ID) AS ACTIVE_PARTICIPANTS, (COUNT(DISTINCT SR.RESPONSE_ID) * 1.0 / COUNT(DISTINCT P.PARTICIPANT_ID)) AS AVG_RESPONSES_PER_PARTICIPANT, S.STUDY_STATUS FROM STUDIES S JOIN PARTICIPANTS P ON S.STUDY_ID = P.STUDY_ID AND P.PARTICIPANT_STATUS = 'ACTIVE' LEFT JOIN SURVEY_RESPONSES SR ON P.PARTICIPANT_ID = SR.PARTICIPANT_ID AND S.STUDY_ID = SR.STUDY_ID AND SR.RESPONSE_STATUS = 'COMPLETED' GROUP BY S.STUDY_ID, S.STUDY_NAME, S.STUDY_STATUS ORDER BY ACTIVE_PARTICIPANTS DESC, AVG_RESPONSES_PER_PARTICIPANT DESC;
WITH ACTIVEPARTICIPANTS AS ( SELECT P.STUDY_ID, COUNT(DISTINCT P.PARTICIPANT_ID) AS ACTIVE_PARTICIPANT_COUNT FROM PARTICIPANTS P WHERE P.PARTICIPANT_STATUS = 'ACTIVE' GROUP BY P.STUDY_ID ), PARTICIPANTRESPONSECOUNTS AS ( SELECT SR.PARTICIPANT_ID, SR.STUDY_ID, COUNT(SR.RESPONSE_ID) AS RESPONSE_COUNT FROM SURVEY_RESPONSES SR GROUP BY SR.PARTICIPANT_ID, SR.STUDY_ID ), AVERAGERESPONSES AS ( SELECT PRC.STUDY_ID, SUM(PRC.RESPONSE_COUNT) AS TOTAL_RESPONSES, COUNT(PRC.PARTICIPANT_ID) AS TOTAL_PARTICIPANTS, CASE WHEN COUNT(PRC.PARTICIPANT_ID) = 0 THEN 0 ELSE SUM(PRC.RESPONSE_COUNT) / COUNT(PRC.PARTICIPANT_ID) END AS AVERAGE_RESPONSES_PER_PARTICIPANT FROM PARTICIPANTRESPONSECOUNTS PRC GROUP BY PRC.STUDY_ID ) SELECT S.STUDY_NAME, AP.ACTIVE_PARTICIPANT_COUNT, AR.AVERAGE_RESPONSES_PER_PARTICIPANT, S.STUDY_STATUS FROM STUDIES S JOIN ACTIVEPARTICIPANTS AP ON S.STUDY_ID = AP.STUDY_ID JOIN AVERAGERESPONSES AR ON S.STUDY_ID = AR.STUDY_ID ORDER BY AP.ACTIVE_PARTICIPANT_COUNT DESC, AR.AVERAGE_RESPONSES_PER_PARTICIPANT DESC;

