WITH INSTITUTIONDATA AS ( SELECT I.INSTITUTION_ID, I.NAME, I.ESTABLISHED_YEAR, I.COUNTRY, COUNT(DISTINCT P.PUBLICATION_ID) AS PUBLICATION_COUNT, COUNT(DISTINCT G.GRANT_ID) AS GRANT_COUNT FROM INSTITUTIONS I LEFT JOIN PUBLICATIONS P ON I.INSTITUTION_ID = P.RESEARCHER_ID LEFT JOIN GRANTS G ON I.INSTITUTION_ID = G.RESEARCHER_ID GROUP BY I.INSTITUTION_ID, I.NAME, I.ESTABLISHED_YEAR, I.COUNTRY ) SELECT ID.NAME, ID.ESTABLISHED_YEAR, ID.COUNTRY, ID.PUBLICATION_COUNT, ID.GRANT_COUNT, R.RESEARCHER_ID FROM INSTITUTIONDATA ID LEFT JOIN RESEARCHERS R ON ID.INSTITUTION_ID = R.INSTITUTION_ID ORDER BY ID.PUBLICATION_COUNT DESC, ID.GRANT_COUNT DESC, ID.ESTABLISHED_YEAR DESC;
WITH PUB_COUNTS AS ( SELECT R.INSTITUTION_ID, COUNT(P.PUBLICATION_ID) AS PUB_COUNT FROM PUBLICATIONS P JOIN RESEARCHERS R ON P.RESEARCHER_ID = R.RESEARCHER_ID GROUP BY R.INSTITUTION_ID ), GRANT_COUNTS AS ( SELECT R.INSTITUTION_ID, COUNT(G.GRANT_ID) AS GRANT_COUNT FROM GRANTS G JOIN RESEARCHERS R ON G.RESEARCHER_ID = R.RESEARCHER_ID GROUP BY R.INSTITUTION_ID ) SELECT I.NAME, I.ESTABLISHED_YEAR, I.COUNTRY, COALESCE(PC.PUB_COUNT, 0) AS PUBLICATION_COUNT, COALESCE(GC.GRANT_COUNT, 0) AS GRANT_COUNT, R.RESEARCHER_ID FROM INSTITUTIONS I LEFT JOIN PUB_COUNTS PC ON I.INSTITUTION_ID = PC.INSTITUTION_ID LEFT JOIN GRANT_COUNTS GC ON I.INSTITUTION_ID = GC.INSTITUTION_ID JOIN RESEARCHERS R ON I.INSTITUTION_ID = R.INSTITUTION_ID ORDER BY COALESCE(PC.PUB_COUNT, 0) DESC, COALESCE(GC.GRANT_COUNT, 0) DESC, I.ESTABLISHED_YEAR DESC;

