WITH GENREHOURS AS ( SELECT UH.USER_ID, M.GENRE, SUM(UH.DURATION) / 60 AS HOURS_WATCHED FROM USER_HISTORY UH JOIN MOVIES M ON UH.MOVIE_ID = M.MOVIE_ID GROUP BY UH.USER_ID, M.GENRE ), TOPFIVEGENRES AS ( SELECT GENRE FROM GENREHOURS GROUP BY GENRE ORDER BY SUM(HOURS_WATCHED) DESC LIMIT 5 ) SELECT GH.USER_ID, GH.GENRE, SUM(GH.HOURS_WATCHED) AS TOTAL_HOURS_WATCHED FROM GENREHOURS GH JOIN TOPFIVEGENRES TFG ON GH.GENRE = TFG.GENRE GROUP BY GH.USER_ID, GH.GENRE HAVING SUM(GH.HOURS_WATCHED) > 20;
WITH USERGENRESTATS AS ( SELECT UH.USER_ID, MG.GENRE_ID, SUM(UH.DURATION) / 60 AS TOTAL_HOURS FROM USER_HISTORY UH JOIN MOVIE_GENRES MG ON UH.MOVIE_ID = MG.MOVIE_ID JOIN GENRES G ON MG.GENRE_ID = G.GENRE_ID GROUP BY UH.USER_ID, MG.GENRE_ID ), GENRESTATS AS ( SELECT GENRE_ID, SUM(TOTAL_HOURS) AS TOTAL_HOURS FROM USERGENRESTATS GROUP BY GENRE_ID ORDER BY TOTAL_HOURS DESC LIMIT 5 ), TOPUSERGENRES AS ( SELECT UGS.USER_ID, G.GENRE_NAME, UGS.TOTAL_HOURS FROM USERGENRESTATS UGS JOIN GENRES G ON UGS.GENRE_ID = G.GENRE_ID WHERE UGS.GENRE_ID IN (SELECT GENRE_ID FROM GENRESTATS) ) SELECT TUG.USER_ID, TUG.GENRE_NAME, TUG.TOTAL_HOURS FROM TOPUSERGENRES TUG WHERE TUG.TOTAL_HOURS > 20;

