WITH PROPERTYDATA AS ( SELECT P.PROPERTY_ID, P.CITY, P.AREA_LOCALITY, P.BHK FROM PROPERTIES P ), VIEWINGDATA AS ( SELECT V.PROPERTY_ID, COUNT(DISTINCT V.VIEWING_ID) AS TOTAL_VIEWINGS, SUM(CASE WHEN V.STATUS = 'SCHEDULED' THEN 1 ELSE 0 END) AS SCHEDULED_VIEWINGS, SUM(CASE WHEN V.STATUS = 'COMPLETED' THEN 1 ELSE 0 END) AS COMPLETED_VIEWINGS, SUM(CASE WHEN V.STATUS = 'CANCELLED' THEN 1 ELSE 0 END) AS CANCELLED_VIEWINGS FROM VIEWINGS V GROUP BY V.PROPERTY_ID ), LEASEDATA AS ( SELECT L.PROPERTY_ID, COUNT(DISTINCT L.LEASE_ID) AS TOTAL_LEASE, AVG(L.RENT) AS AVERAGE_RENT, SUM(L.SECURITY_DEPOSIT) AS TOTAL_SECURITY_DEPOSIT FROM LEASES L GROUP BY L.PROPERTY_ID ) SELECT PD.CITY, PD.AREA_LOCALITY, PD.BHK, VD.TOTAL_VIEWINGS, VD.SCHEDULED_VIEWINGS, VD.COMPLETED_VIEWINGS, VD.CANCELLED_VIEWINGS, LD.TOTAL_LEASE, LD.AVERAGE_RENT, LD.TOTAL_SECURITY_DEPOSIT FROM PROPERTYDATA PD LEFT JOIN VIEWINGDATA VD ON PD.PROPERTY_ID = VD.PROPERTY_ID LEFT JOIN LEASEDATA LD ON PD.PROPERTY_ID = LD.PROPERTY_ID GROUP BY PD.CITY, PD.AREA_LOCALITY, PD.BHK ORDER BY PD.CITY, PD.AREA_LOCALITY, PD.BHK;

