WITH AVERAGECODONFREQUENCIES AS ( SELECT SEQUENCE_ID, AVG(FREQUENCY) AS AVERAGE_CODON_FREQUENCY FROM CODON_USAGE GROUP BY SEQUENCE_ID ), AVERAGEAMINOACIDFREQUENCIES AS ( SELECT SEQUENCE_ID, AVG(FREQUENCY) AS AVERAGE_AMINO_ACID_FREQUENCY FROM AMINO_ACID_FREQUENCIES GROUP BY SEQUENCE_ID ), TOPSEQUENCES AS ( SELECT ACF.SEQUENCE_ID, S.ORGANISM, (ACF.AVERAGE_CODON_FREQUENCY + AAF.AVERAGE_AMINO_ACID_FREQUENCY) AS TOTAL_FREQUENCY FROM AVERAGECODONFREQUENCIES ACF JOIN SEQUENCES S ON ACF.SEQUENCE_ID = S.SEQUENCE_ID JOIN AVERAGEAMINOACIDFREQUENCIES AAF ON ACF.SEQUENCE_ID = AAF.SEQUENCE_ID ORDER BY TOTAL_FREQUENCY DESC LIMIT 10 ) SELECT TS.SEQUENCE_ID, TS.ORGANISM FROM TOPSEQUENCES TS;
WITH CODONFREQUENCIES AS (
    SELECT 
        SEQUENCE_ID,
        AVG(FREQUENCY) AS AVG_CODON_FREQUENCY
    FROM CODON_USAGE
    GROUP BY SEQUENCE_ID
),
AMINOACIDFREQUENCIES AS (
    SELECT 
        SEQUENCE_ID,
        AVG(FREQUENCY) AS AVG_AA_FREQUENCY
    FROM AMINO_ACID_FREQUENCIES
    GROUP BY SEQUENCE_ID
),
SEQUENCESTATS AS (
    SELECT 
        S.SEQUENCE_ID,
        S.ORGANISM,
        COALESCE(C.AVG_CODON_FREQUENCY, 0) AS AVG_CODON_FREQUENCY,
        COALESCE(A.AVG_AA_FREQUENCY, 0) AS AVG_AA_FREQUENCY,
        (COALESCE(C.AVG_CODON_FREQUENCY, 0) + COALESCE(A.AVG_AA_FREQUENCY, 0)) AS COMBINED_AVG_FREQUENCY
    FROM SEQUENCES S
    LEFT JOIN CODONFREQUENCIES C ON S.SEQUENCE_ID = C.SEQUENCE_ID
    LEFT JOIN AMINOACIDFREQUENCIES A ON S.SEQUENCE_ID = A.SEQUENCE_ID
)
SELECT 
    SEQUENCE_ID,
    ORGANISM
FROM SEQUENCESTATS
ORDER BY COMBINED_AVG_FREQUENCY DESC
LIMIT 10;

