WITH COUNTRYAVERAGEINDICATORS AS ( SELECT C.COUNTRY_NAME, I.INDICATOR_NAME, AVG(D.VALUE) AS AVG_VALUE FROM DATA_POINTS D JOIN COUNTRIES C ON D.COUNTRY_ID = C.COUNTRY_ID JOIN INDICATORS I ON D.INDICATOR_ID = I.INDICATOR_ID GROUP BY C.COUNTRY_NAME, I.INDICATOR_NAME ), GLOBALAVERAGEINDICATORS AS ( SELECT INDICATOR_NAME, AVG(AVG_VALUE) AS GLOBAL_AVG_VALUE FROM COUNTRYAVERAGEINDICATORS GROUP BY INDICATOR_NAME ), COUNTRYTOGLOBALPROPORTION AS ( SELECT CAI.COUNTRY_NAME, CAI.INDICATOR_NAME, CAI.AVG_VALUE, GAI.GLOBAL_AVG_VALUE, CAI.AVG_VALUE / GAI.GLOBAL_AVG_VALUE AS PROPORTION FROM COUNTRYAVERAGEINDICATORS CAI JOIN GLOBALAVERAGEINDICATORS GAI ON CAI.INDICATOR_NAME = GAI.INDICATOR_NAME ) SELECT COUNTRY_NAME FROM COUNTRYTOGLOBALPROPORTION WHERE PROPORTION = (SELECT MAX(PROPORTION) FROM COUNTRYTOGLOBALPROPORTION) LIMIT 1;
WITH GLOBALAVERAGEVALUES AS ( SELECT INDICATOR_ID, AVG(VALUE) AS GLOBAL_AVERAGE FROM DATA_POINTS GROUP BY INDICATOR_ID ), COUNTRYAVERAGEVALUES AS ( SELECT COUNTRY_ID, INDICATOR_ID, AVG(VALUE) AS COUNTRY_AVERAGE FROM DATA_POINTS GROUP BY COUNTRY_ID, INDICATOR_ID ), PROPORTIONVALUES AS ( SELECT CA.COUNTRY_ID, CA.INDICATOR_ID, CA.COUNTRY_AVERAGE / GAV.GLOBAL_AVERAGE AS PROPORTION FROM COUNTRYAVERAGEVALUES CA JOIN GLOBALAVERAGEVALUES GAV ON CA.INDICATOR_ID = GAV.INDICATOR_ID ), RANKEDCOUNTRIES AS ( SELECT PROPORTION, COUNTRY_ID FROM PROPORTIONVALUES ORDER BY PROPORTION DESC LIMIT 1 ) SELECT C.COUNTRY_NAME FROM RANKEDCOUNTRIES RC JOIN COUNTRIES C ON RC.COUNTRY_ID = C.COUNTRY_ID;

