WITH CONSUMPTIONSUMMARY AS ( SELECT METER_ID, SUM(VALUE) AS TOTAL_CONSUMPTION FROM ENERGY_CONSUMPTION GROUP BY METER_ID ), HIGHCONSUMPTIONMETERS AS ( SELECT CS.METER_ID, M.METER_SERIAL, CS.TOTAL_CONSUMPTION FROM CONSUMPTIONSUMMARY CS JOIN METERS M ON CS.METER_ID = M.METER_ID WHERE CS.TOTAL_CONSUMPTION > (SELECT AVG(TOTAL_CONSUMPTION) FROM CONSUMPTIONSUMMARY) ) SELECT HCM.METER_SERIAL, A.ALERT_TYPE FROM HIGHCONSUMPTIONMETERS HCM LEFT JOIN ALERTS A ON HCM.METER_ID = A.METER_ID ORDER BY HCM.TOTAL_CONSUMPTION DESC;
WITH ENERGYCONSUMPTION AS ( SELECT E.METER_ID, SUM(E.VALUE) AS TOTAL_CONSUMPTION FROM ENERGY_CONSUMPTION E GROUP BY E.METER_ID ), HIGHCONSUMPTIONMETERS AS ( SELECT M.METER_ID, M.METER_SERIAL, EC.TOTAL_CONSUMPTION FROM METERS M INNER JOIN ENERGYCONSUMPTION EC ON M.METER_ID = EC.METER_ID WHERE EC.TOTAL_CONSUMPTION > (SELECT AVG(TOTAL_CONSUMPTION) FROM ENERGYCONSUMPTION) ), METERALERTS AS ( SELECT A.METER_ID, A.ALERT_TYPE FROM ALERTS A ) SELECT HCM.METER_SERIAL, IFNULL(MA.ALERT_TYPE, 'NO ALERTS') AS ALERT_TYPE FROM HIGHCONSUMPTIONMETERS HCM LEFT JOIN METERALERTS MA ON HCM.METER_ID = MA.METER_ID ORDER BY HCM.TOTAL_CONSUMPTION DESC;

