WITH LATESTAPPLICATIONS AS ( SELECT STUDENT_ID, MAX(APPLICATION_DATE) AS LATEST_DATE FROM STUDENT_PROGRAMS GROUP BY STUDENT_ID ), SELECTEDSTUDENTS AS ( SELECT SP.STUDENT_ID, S.FIRST_NAME AS STUDENT_FIRST_NAME, SP.PROGRAM_ID, SP.SELECTED, SP.APPLICATION_DATE FROM STUDENT_PROGRAMS SP JOIN LATESTAPPLICATIONS LA ON SP.STUDENT_ID = LA.STUDENT_ID AND SP.APPLICATION_DATE = LA.LATEST_DATE JOIN STUDENTS S ON SP.STUDENT_ID = S.STUDENT_ID WHERE SP.SELECTED = 1 ) SELECT SS.STUDENT_FIRST_NAME, T.FIRST_NAME AS TEACHER_FIRST_NAME FROM SELECTEDSTUDENTS SS JOIN TEACHER_STUDENTS TS ON SS.STUDENT_ID = TS.STUDENT_ID JOIN TEACHERS T ON TS.TEACHER_ID = T.TEACHER_ID;
WITH LATESTAPPLICATIONS AS ( SELECT STUDENT_ID, PROGRAM_ID, SELECTED, APPLICATION_DATE FROM STUDENT_PROGRAMS SP1 WHERE APPLICATION_DATE = ( SELECT MAX(APPLICATION_DATE) FROM STUDENT_PROGRAMS SP2 WHERE SP1.STUDENT_ID = SP2.STUDENT_ID ) ), SELECTEDSTUDENTSWITHDETAILS AS ( SELECT LA.STUDENT_ID, S.FIRST_NAME AS STUDENT_FIRST_NAME, LA.PROGRAM_ID, LA.SELECTED FROM LATESTAPPLICATIONS LA JOIN STUDENTS S ON LA.STUDENT_ID = S.STUDENT_ID WHERE LA.SELECTED = 1 ) SELECT SSD.STUDENT_FIRST_NAME, T.FIRST_NAME AS TEACHER_FIRST_NAME FROM SELECTEDSTUDENTSWITHDETAILS SSD JOIN TEACHER_STUDENTS TS ON SSD.STUDENT_ID = TS.STUDENT_ID JOIN TEACHERS T ON TS.TEACHER_ID = T.TEACHER_ID;

