WITH NEUROLOGYRESIDENTS AS ( SELECT R.RESIDENT_ID, R.NAME FROM RESIDENTS R JOIN SPECIALTIES S ON R.SPECIALTY_ID = S.SPECIALTY_ID WHERE S.SPECIALTY_NAME = 'NEUROLOGY' ), RESIDENTROTATIONCOUNTS AS ( SELECT R.RESIDENT_ID, COUNT(RP.PROGRESS_ID) AS ROTATION_COUNT FROM NEUROLOGYRESIDENTS R LEFT JOIN RESIDENT_PROGRESS RP ON R.RESIDENT_ID = RP.RESIDENT_ID GROUP BY R.RESIDENT_ID ), QUALIFIEDNEUROLOGYRESIDENTS AS ( SELECT RESIDENT_ID FROM RESIDENTROTATIONCOUNTS WHERE ROTATION_COUNT > 1 ), HIGHESTSCORESPERROTATION AS ( SELECT RP.RESIDENT_ID, RP.PROGRESS_ID, MAX(RE.EVALUATION_SCORE) AS MAX_SCORE FROM RESIDENT_PROGRESS RP JOIN ROTATION_EVALUATIONS RE ON RP.PROGRESS_ID = RE.PROGRESS_ID WHERE RP.RESIDENT_ID IN (SELECT RESIDENT_ID FROM QUALIFIEDNEUROLOGYRESIDENTS) GROUP BY RP.RESIDENT_ID, RP.PROGRESS_ID ), AVERAGEOFHIGHESTSCORES AS ( SELECT RESIDENT_ID, AVG(MAX_SCORE) AS AVG_HIGHEST_EVALUATION_SCORE FROM HIGHESTSCORESPERROTATION GROUP BY RESIDENT_ID ) SELECT A.RESIDENT_ID, A.AVG_HIGHEST_EVALUATION_SCORE FROM AVERAGEOFHIGHESTSCORES A ORDER BY A.AVG_HIGHEST_EVALUATION_SCORE DESC;
WITH RESWITHROTATIONS AS ( SELECT R.RESIDENT_ID, R.NAME, COUNT(RP.PROGRESS_ID) AS NUM_ROTATIONS FROM RESIDENTS R JOIN SPECIALTIES S ON R.SPECIALTY_ID = S.SPECIALTY_ID LEFT JOIN RESIDENT_PROGRESS RP ON R.RESIDENT_ID = RP.RESIDENT_ID WHERE S.SPECIALTY_NAME = 'NEUROLOGY' ), QUALIFIEDRESIDENTS AS ( SELECT RESIDENT_ID FROM RESWITHROTATIONS WHERE NUM_ROTATIONS > 1 ), ROTATIONSCORES AS ( SELECT RP.RESIDENT_ID, E.EVALUATION_SCORE FROM RESIDENT_PROGRESS RP JOIN ROTATION_EVALUATIONS E ON RP.PROGRESS_ID = E.PROGRESS_ID ), MAXSCORES AS ( SELECT RS.RESIDENT_ID, MAX(RS.EVALUATION_SCORE) AS HIGHEST_EVALUATION_SCORE FROM ROTATIONSCORES RS GROUP BY RS.RESIDENT_ID ), AVGSCORES AS ( SELECT QR.RESIDENT_ID, SUM(MS.HIGHEST_EVALUATION_SCORE) / COUNT(MS.HIGHEST_EVALUATION_SCORE) AS AVG_HIGHEST_EVALUATION_SCORE FROM QUALIFIEDRESIDENTS QR JOIN MAXSCORES MS ON QR.RESIDENT_ID = MS.RESIDENT_ID GROUP BY QR.RESIDENT_ID ) SELECT RESIDENT_ID, AVG_HIGHEST_EVALUATION_SCORE FROM AVGSCORES ORDER BY AVG_HIGHEST_EVALUATION_SCORE DESC;

