WITH MENTIONEDTWEETS AS ( SELECT T.FIGURE_ID, COUNT(M.MENTION_ID) AS MENTION_COUNT, SUM(T.RETWEETS) AS TOTAL_RETWEETS, SUM(T.FAVORITES) AS TOTAL_FAVORITES, AVG(T.RETWEETS + T.FAVORITES) AS AVERAGE_ENGAGEMENT FROM TWEETS T JOIN MENTIONS M ON T.TWEET_ID = M.TWEET_ID WHERE M.USERNAME = 'THEVIEW' GROUP BY T.FIGURE_ID ), ENGAGEMENTSUMMARY AS ( SELECT PF.FIGURE_ID, PF.NAME, SUM(MUT.MENTION_COUNT) AS TOTAL_MENTIONS, SUM(MUT.TOTAL_RETWEETS) AS TOTAL_RETWEETS, SUM(MUT.TOTAL_FAVORITES) AS TOTAL_FAVORITES, AVG(MUT.AVERAGE_ENGAGEMENT) AS AVERAGE_ENGAGEMENT FROM MENTIONEDTWEETS MUT JOIN PUBLIC_FIGURES PF ON MUT.FIGURE_ID = PF.FIGURE_ID GROUP BY PF.FIGURE_ID, PF.NAME ) SELECT NAME, TOTAL_MENTIONS, TOTAL_RETWEETS, TOTAL_FAVORITES, AVERAGE_ENGAGEMENT FROM ENGAGEMENTSUMMARY ORDER BY AVERAGE_ENGAGEMENT DESC;

