SELECT 
    U.USERNAME,
    SUM(RU.DURATION) AS CUMULATIVE_DURATION
FROM 
    RESOURCES_USAGE RU
JOIN 
    RESOURCES R ON RU.RESOURCE_ID = R.RESOURCE_ID
JOIN 
    USERS U ON RU.USER_ID = U.USER_ID
WHERE 
    R.RESOURCE_TYPE IN ('MALWARE IP', 'INCIDENT REPORT')
GROUP BY 
    U.USERNAME
ORDER BY 
    CUMULATIVE_DURATION DESC;
WITH USERACCESS AS ( SELECT RU.USER_ID, U.USERNAME, SUM(RU.DURATION) AS TOTAL_DURATION FROM RESOURCES_USAGE RU INNER JOIN USERS U ON RU.USER_ID = U.USER_ID INNER JOIN RESOURCES R ON RU.RESOURCE_ID = R.RESOURCE_ID WHERE R.RESOURCE_TYPE IN ('MALWARE IP', 'INCIDENT REPORT') GROUP BY RU.USER_ID, U.USERNAME ) SELECT UA.USERNAME, SUM(UA.TOTAL_DURATION) AS TOTAL_CUMULATIVE_DURATION FROM USERACCESS UA GROUP BY UA.USER_ID, UA.USERNAME ORDER BY TOTAL_CUMULATIVE_DURATION DESC;

