WITH CHANGE_SUMMARY AS ( SELECT CH.INTERRUPT_ID, CH.DEVICE_ID, CH.CHANGE_REASON, COUNT(CH.CONFIG_ID) AS NUMBER_OF_CHANGES, MAX(CH.CHANGE_DATE) AS LAST_CHANGE_DATE FROM CONFIGURATION_HISTORY CH GROUP BY CH.INTERRUPT_ID, CH.DEVICE_ID, CH.CHANGE_REASON ), USER_DETAILS AS ( SELECT CH.INTERRUPT_ID, CH.DEVICE_ID, CH.CHANGE_REASON, CH.CHANGED_BY, U.USERNAME, U.ROLE FROM CONFIGURATION_HISTORY CH JOIN USERS U ON CH.CHANGED_BY = U.USER_ID ) SELECT I.NAME AS INTERRUPT_NAME, CS.DEVICE_ID, CS.NUMBER_OF_CHANGES, CS.LAST_CHANGE_DATE, CS.CHANGE_REASON, UD.USERNAME, UD.ROLE FROM CHANGE_SUMMARY CS JOIN USER_DETAILS UD ON CS.INTERRUPT_ID = UD.INTERRUPT_ID AND CS.DEVICE_ID = UD.DEVICE_ID AND CS.CHANGE_REASON = UD.CHANGE_REASON JOIN INTERRUPTS I ON CS.INTERRUPT_ID = I.INTERRUPT_ID ORDER BY CS.NUMBER_OF_CHANGES DESC, CS.LAST_CHANGE_DATE DESC;
WITH CHANGE_SUMMARY AS ( SELECT I.NAME AS INTERRUPT_NAME, CH.DEVICE_ID, COUNT(CH.CONFIG_ID) AS NUMBER_OF_CHANGES, MAX(CH.CHANGE_DATE) AS LAST_CHANGE_DATE, CH.CHANGE_REASON, U.USERNAME, U.ROLE FROM CONFIGURATION_HISTORY CH JOIN INTERRUPTS I ON CH.INTERRUPT_ID = I.INTERRUPT_ID JOIN USERS U ON CH.CHANGED_BY = U.USER_ID GROUP BY CH.INTERRUPT_ID, CH.DEVICE_ID, CH.CHANGE_REASON ) SELECT * FROM CHANGE_SUMMARY ORDER BY NUMBER_OF_CHANGES DESC, LAST_CHANGE_DATE DESC;

