SELECT E.EMPLOYEE_NAME, P.POSITION_NAME, D.DEPARTMENT_NAME, COALESCE(ET.COMPLETED_TRAINING_COUNT, 0) AS COMPLETED_TRAININGS FROM EMPLOYEES E INNER JOIN POSITIONS P ON E.POSITION = P.POSITION_ID INNER JOIN DEPARTMENTS D ON E.DEPARTMENT = D.DEPARTMENT_ID LEFT JOIN (SELECT ET.EMPLOYEE_ID, COUNT(*) AS COMPLETED_TRAINING_COUNT FROM EMPLOYEE_TRAINING ET WHERE ET.COMPLETION_STATUS = 'COMPLETED' GROUP BY ET.EMPLOYEE_ID) ET ON E.EMPLOYEE_ID = ET.EMPLOYEE_ID ORDER BY D.DEPARTMENT_NAME, P.POSITION_NAME, E.EMPLOYEE_NAME;
WITH COMPLETED_TRAININGS AS ( SELECT E.EMPLOYEE_ID, COUNT(ET.TRAINING_ID) AS NUM_COMPLETED_TRAININGS FROM EMPLOYEES E LEFT JOIN EMPLOYEE_TRAINING ET ON E.EMPLOYEE_ID = ET.EMPLOYEE_ID AND ET.COMPLETION_STATUS = 'COMPLETED' GROUP BY E.EMPLOYEE_ID ), EMPLOYEE_DETAILS AS ( SELECT E.EMPLOYEE_ID, E.EMPLOYEE_NAME, P.POSITION_NAME, D.DEPARTMENT_NAME FROM EMPLOYEES E INNER JOIN POSITIONS P ON E.POSITION = P.POSITION_ID INNER JOIN DEPARTMENTS D ON E.DEPARTMENT = D.DEPARTMENT_ID ) SELECT ED.EMPLOYEE_NAME, ED.POSITION_NAME, ED.DEPARTMENT_NAME, IFNULL(CT.NUM_COMPLETED_TRAININGS, 0) AS COMPLETED_TRAININGS FROM EMPLOYEE_DETAILS ED LEFT JOIN COMPLETED_TRAININGS CT ON ED.EMPLOYEE_ID = CT.EMPLOYEE_ID ORDER BY ED.DEPARTMENT_NAME, ED.POSITION_NAME, ED.EMPLOYEE_NAME;

