SELECT SD.SENSOR_ID, ST.SENSOR_NAME, COUNT(*) AS SENSOR_DATA_COUNT, AVG(SD.BOT_REACT_X) AS AVG_BOT_REACT_X, AVG(SD.BOT_REACT_Y) AS AVG_BOT_REACT_Y, AVG(SD.TOP_REACT_X) AS AVG_TOP_REACT_X, AVG(SD.TOP_REACT_Y) AS AVG_TOP_REACT_Y, SUM(CASE WHEN SD.BOT_REACT_X > 10 OR SD.BOT_REACT_Y > 10 OR SD.TOP_REACT_X > 10 OR SD.TOP_REACT_Y > 10 THEN 1 ELSE 0 END) AS SUSPICIOUS_DATA_COUNT FROM SENSOR_DATA SD INNER JOIN SENSOR_TYPES ST ON SD.SENSOR_ID = ST.SENSOR_ID WHERE ST.SENSOR_TYPE = 'REACTION FORCE' GROUP BY SD.SENSOR_ID, ST.SENSOR_NAME ORDER BY SD.SENSOR_ID;
WITH SENSORDATA AS ( SELECT SD.DATA_ID, SD.SENSOR_ID, SD.BOT_REACT_X, SD.BOT_REACT_Y, SD.TOP_REACT_X, SD.TOP_REACT_Y FROM SENSOR_DATA SD JOIN SENSOR_TYPES S ON SD.SENSOR_ID = S.SENSOR_ID WHERE S.SENSOR_TYPE = 'REACTION FORCE' ), AGGREGATEDDATA AS ( SELECT SENSOR_ID, COUNT(DATA_ID) AS TOTAL_DATA_ENTRIES, SUM(CASE WHEN BOT_REACT_X > 10 THEN 1 ELSE 0 END) AS HIGH_FORCE_BOT_X_COUNT, SUM(CASE WHEN BOT_REACT_Y > 10 THEN 1 ELSE 0 END) AS HIGH_FORCE_BOT_Y_COUNT, SUM(CASE WHEN TOP_REACT_X > 10 THEN 1 ELSE 0 END) AS HIGH_FORCE_TOP_X_COUNT, SUM(CASE WHEN TOP_REACT_Y > 10 THEN 1 ELSE 0 END) AS HIGH_FORCE_TOP_Y_COUNT FROM SENSORDATA GROUP BY SENSOR_ID ), FORCEAVERAGES AS ( SELECT SENSOR_ID, AVG(BOT_REACT_X) AS AVG_BOT_REACT_X, AVG(BOT_REACT_Y) AS AVG_BOT_REACT_Y, AVG(TOP_REACT_X) AS AVG_TOP_REACT_X, AVG(TOP_REACT_Y) AS AVG_TOP_REACT_Y FROM SENSORDATA GROUP BY SENSOR_ID ) SELECT SD.SENSOR_ID, S.SENSOR_NAME, AD.TOTAL_DATA_ENTRIES, FA.AVG_BOT_REACT_X, FA.AVG_BOT_REACT_Y, FA.AVG_TOP_REACT_X, FA.AVG_TOP_REACT_Y, AD.HIGH_FORCE_BOT_X_COUNT + AD.HIGH_FORCE_BOT_Y_COUNT + AD.HIGH_FORCE_TOP_X_COUNT + AD.HIGH_FORCE_TOP_Y_COUNT AS HIGH_FORCE_DATA_COUNT FROM SENSOR_DATA SD JOIN SENSOR_TYPES S ON SD.SENSOR_ID = S.SENSOR_ID JOIN AGGREGATEDDATA AD ON SD.SENSOR_ID = AD.SENSOR_ID JOIN FORCEAVERAGES FA ON SD.SENSOR_ID = FA.SENSOR_ID WHERE S.SENSOR_TYPE = 'REACTION FORCE' GROUP BY SD.SENSOR_ID, S.SENSOR_NAME ORDER BY SD.SENSOR_ID;

