SELECT DISTINCT U.USER_NAME FROM USERS U JOIN USER_ROLE_ASSIGNMENTS URA ON U.USER_ID = URA.USER_ID JOIN LIKES L ON U.USER_ID = L.USER_ID JOIN TWEETS T ON L.TWEET_ID = T.TWEET_ID JOIN TREND_TWEETS TT ON T.TWEET_ID = TT.TWEET_ID JOIN TRENDS TR ON TT.TREND_ID = TR.TREND_ID WHERE U.VERIFIED = 1 AND URA.ROLE_ID IS NOT NULL AND URA.END_DATE IS NULL AND TR.LOCATION = 'NEW YORK, NY';
WITH VERIFIEDUSERS AS (
    SELECT USER_ID, USER_NAME
    FROM USERS
    WHERE VERIFIED = 1
),
ACTIVEROLES AS (
    SELECT USER_ID
    FROM USER_ROLE_ASSIGNMENTS
    WHERE END_DATE IS NULL
),
LIKEDTWEETS AS (
    SELECT USER_ID, TWEET_ID
    FROM LIKES
),
TRENDYTWEETS AS (
    SELECT TWEET_ID
    FROM TREND_TWEETS
    INNER JOIN TRENDS ON TREND_TWEETS.TREND_ID = TRENDS.TREND_ID
    INNER JOIN LOCATIONS ON TRENDS.LOCATION = LOCATIONS.LOCATION_ID
    WHERE LOCATIONS.LOCATION_NAME = 'NEW YORK, NY'
)
SELECT DISTINCT VU.USER_NAME
FROM VERIFIEDUSERS VU
INNER JOIN ACTIVEROLES AR ON VU.USER_ID = AR.USER_ID
INNER JOIN LIKEDTWEETS LT ON VU.USER_ID = LT.USER_ID
INNER JOIN TRENDYTWEETS TT ON LT.TWEET_ID = TT.TWEET_ID;

