WITH ACTIVEPARTICIPANTS AS ( SELECT P.STUDY_ID, P.PARTICIPANT_ID FROM PARTICIPANTS P WHERE P.PARTICIPANT_STATUS = 'ACTIVE' ), PARTICIPANTRESPONSECOUNTS AS ( SELECT SR.PARTICIPANT_ID, COUNT(SR.RESPONSE_ID) AS RESPONSE_COUNT FROM SURVEY_RESPONSES SR GROUP BY SR.PARTICIPANT_ID ) SELECT S.STUDY_NAME, COUNT(AP.PARTICIPANT_ID) AS ACTIVE_PARTICIPANTS, AVG(PRC.RESPONSE_COUNT) AS AVERAGE_RESPONSES_PER_PARTICIPANT, S.STUDY_STATUS FROM STUDIES S LEFT JOIN ACTIVEPARTICIPANTS AP ON S.STUDY_ID = AP.STUDY_ID LEFT JOIN PARTICIPANTRESPONSECOUNTS PRC ON AP.PARTICIPANT_ID = PRC.PARTICIPANT_ID GROUP BY S.STUDY_NAME, S.STUDY_STATUS ORDER BY ACTIVE_PARTICIPANTS DESC, AVERAGE_RESPONSES_PER_PARTICIPANT DESC;
WITH ACTIVEPARTICIPANTS AS ( SELECT P.STUDY_ID, P.PARTICIPANT_ID FROM PARTICIPANTS P WHERE P.PARTICIPANT_STATUS = 'ACTIVE' ), RESPONSESPERPARTICIPANT AS ( SELECT SR.PARTICIPANT_ID, COUNT(SR.RESPONSE_ID) AS RESPONSE_COUNT FROM SURVEY_RESPONSES SR JOIN ACTIVEPARTICIPANTS AP ON SR.PARTICIPANT_ID = AP.PARTICIPANT_ID AND SR.STUDY_ID = AP.STUDY_ID GROUP BY SR.PARTICIPANT_ID ), STUDYDATA AS ( SELECT S.STUDY_ID, S.STUDY_NAME, S.STUDY_STATUS, AP.PARTICIPANT_ID, COALESCE(RPP.RESPONSE_COUNT, 0) AS RESPONSE_COUNT FROM STUDIES S LEFT JOIN ACTIVEPARTICIPANTS AP ON S.STUDY_ID = AP.STUDY_ID LEFT JOIN RESPONSESPERPARTICIPANT RPP ON AP.PARTICIPANT_ID = RPP.PARTICIPANT_ID ) SELECT SD.STUDY_NAME, COUNT(DISTINCT SD.PARTICIPANT_ID) AS ACTIVE_PARTICIPANTS, AVG(SD.RESPONSE_COUNT) AS AVG_RESPONSES_PER_PARTICIPANT, SD.STUDY_STATUS FROM STUDYDATA SD GROUP BY SD.STUDY_ID, SD.STUDY_NAME, SD.STUDY_STATUS ORDER BY ACTIVE_PARTICIPANTS DESC, AVG_RESPONSES_PER_PARTICIPANT DESC;

