SELECT R.RECIPE_ID, ( COALESCE(N.TOTAL_CALORIES, 0) + COALESCE(N.TOTAL_FAT, 0) + COALESCE(N.TOTAL_CARBS, 0) + COALESCE(N.TOTAL_PROTEIN, 0) + COALESCE(N.TOTAL_SODIUM, 0) + COALESCE(RATINGS.AVG_RATING, 0) * 10 + COALESCE(RATINGS.TOTAL_RATINGS, 0) + COALESCE(REVIEWS.TOTAL_REVIEWS, 0) ) AS COMPOSITE_SCORE FROM RECIPES R LEFT JOIN ( SELECT RECIPE_ID, SUM(CPS) AS TOTAL_CALORIES, SUM(FAT) AS TOTAL_FAT, SUM(CARBOHYDRATES) AS TOTAL_CARBS, SUM(PROTEIN) AS TOTAL_PROTEIN, SUM(SODIUM) AS TOTAL_SODIUM FROM NUTRITIONAL_VALUES GROUP BY RECIPE_ID ) N ON R.RECIPE_ID = N.RECIPE_ID LEFT JOIN ( SELECT RECIPE_ID, AVG(RATING_VALUE) AS AVG_RATING, COUNT(RATING_ID) AS TOTAL_RATINGS FROM RECIPE_RATINGS GROUP BY RECIPE_ID ) RATINGS ON R.RECIPE_ID = RATINGS.RECIPE_ID LEFT JOIN ( SELECT RECIPE_ID, COUNT(REVIEW_ID) AS TOTAL_REVIEWS FROM RECIPE_REVIEWS GROUP BY RECIPE_ID ) REVIEWS ON R.RECIPE_ID = REVIEWS.RECIPE_ID ORDER BY COMPOSITE_SCORE DESC;
WITH NUTRITIONALTOTALS AS ( SELECT RECIPE_ID, SUM(CPS) AS TOTAL_CALORIES, SUM(FAT) AS TOTAL_FAT, SUM(CARBOHYDRATES) AS TOTAL_CARBS, SUM(PROTEIN) AS TOTAL_PROTEIN, SUM(SODIUM) AS TOTAL_SODIUM FROM NUTRITIONAL_VALUES GROUP BY RECIPE_ID ), RATINGSTATS AS ( SELECT RECIPE_ID, AVG(RATING_VALUE) AS AVG_RATING, COUNT(RATING_ID) AS TOTAL_RATINGS FROM RECIPE_RATINGS GROUP BY RECIPE_ID ), REVIEWCOUNTS AS ( SELECT RECIPE_ID, COUNT(REVIEW_ID) AS TOTAL_REVIEWS FROM RECIPE_REVIEWS GROUP BY RECIPE_ID ), RECIPEDATA AS ( SELECT NT.RECIPE_ID, NT.TOTAL_CALORIES, NT.TOTAL_FAT, NT.TOTAL_CARBS, NT.TOTAL_PROTEIN, NT.TOTAL_SODIUM, COALESCE(RS.AVG_RATING, 0) AS AVG_RATING, COALESCE(RS.TOTAL_RATINGS, 0) AS TOTAL_RATINGS, COALESCE(RC.TOTAL_REVIEWS, 0) AS TOTAL_REVIEWS FROM NUTRITIONALTOTALS NT LEFT JOIN RATINGSTATS RS ON NT.RECIPE_ID = RS.RECIPE_ID LEFT JOIN REVIEWCOUNTS RC ON NT.RECIPE_ID = RC.RECIPE_ID ) SELECT RECIPE_ID, (TOTAL_CALORIES + TOTAL_FAT + TOTAL_CARBS + TOTAL_PROTEIN + TOTAL_SODIUM + (AVG_RATING * 10) + TOTAL_RATINGS + TOTAL_REVIEWS) AS COMPOSITE_SCORE FROM RECIPEDATA ORDER BY COMPOSITE_SCORE DESC;

