WITH AVERAGEMETHODACCURACYCTE AS ( SELECT OP.OBJECT_ID, PEM.METHOD_ID, PEM.METHOD_ACCURACY FROM OBJECT_POSES OP INNER JOIN POSE_ESTIMATION_RESULTS PER ON OP.POSE_ID = PER.POSE_ID INNER JOIN POSE_ESTIMATION_METHODS PEM ON PER.METHOD_ID = PEM.METHOD_ID ) SELECT O.OBJECT_NAME, AVG(AM.METHOD_ACCURACY) AS AVG_METHOD_ACCURACY FROM OBJECTS O INNER JOIN AVERAGEMETHODACCURACYCTE AM ON O.OBJECT_ID = AM.OBJECT_ID GROUP BY O.OBJECT_ID HAVING AVG(AM.METHOD_ACCURACY) > 0.8 AND COUNT(DISTINCT AM.METHOD_ID) > 1 ORDER BY AVG_METHOD_ACCURACY DESC;
WITH METHODACCURACIES AS ( SELECT P.OBJECT_ID, AVG(R.ACCURACY) AS AVG_ACCURACY, COUNT(DISTINCT R.METHOD_ID) AS METHOD_COUNT FROM OBJECT_POSES P JOIN POSE_ESTIMATION_RESULTS R ON P.POSE_ID = R.POSE_ID GROUP BY P.OBJECT_ID ) SELECT O.OBJECT_NAME, MA.AVG_ACCURACY AS AVERAGE_METHOD_ACCURACY FROM METHODACCURACIES MA JOIN OBJECTS O ON MA.OBJECT_ID = O.OBJECT_ID WHERE MA.AVG_ACCURACY > 0.8 AND MA.METHOD_COUNT > 1 ORDER BY MA.AVG_ACCURACY DESC;

