WITH SERIES2CONTESTANTS AS ( SELECT C.CONTESTANT_ID, C.NAME, P.SCORE FROM CONTESTANTS C JOIN PERFORMANCES P ON C.CONTESTANT_ID = P.CONTESTANT_ID JOIN SERIES S ON P.SERIES_ID = S.SERIES_ID WHERE S.SERIES_NAME = 'SERIES 2' ), MENTOREDCONTESTANTS AS ( SELECT NAME, SCORE FROM SERIES2CONTESTANTS JOIN MENTORS M ON SERIES2CONTESTANTS.CONTESTANT_ID = M.MENTOR_ID WHERE M.MENTOR_NAME = 'MENTOR 1' ) SELECT NAME FROM MENTOREDCONTESTANTS ORDER BY SCORE DESC LIMIT 1;

