WITH TOTALFARES AS ( SELECT R.TRAIN_ID, SUM(R.FARE_AMOUNT) AS TOTAL_FARE FROM RESERVATIONS R GROUP BY R.TRAIN_ID ), PASSENGERCOUNTS AS ( SELECT R.TRAIN_ID, COUNT(R.PASSENGER_ID) AS PASSENGER_COUNT FROM RESERVATIONS R GROUP BY R.TRAIN_ID ), AVERAGEFARES AS ( SELECT T.TRAIN_ID, T.TRAIN_NAME, TF.TOTAL_FARE / PC.PASSENGER_COUNT AS AVERAGE_FARE FROM TRAINS T JOIN TOTALFARES TF ON T.TRAIN_ID = TF.TRAIN_ID JOIN PASSENGERCOUNTS PC ON T.TRAIN_ID = PC.TRAIN_ID ) SELECT TRAIN_NAME FROM AVERAGEFARES ORDER BY AVERAGE_FARE DESC LIMIT 1;
WITH TRAINTOTALS AS (
  SELECT
    R.TRAIN_ID,
    SUM(R.FARE_AMOUNT) AS TOTAL_FARE,
    COUNT(R.PASSENGER_ID) AS PASSENGER_COUNT
  FROM
    RESERVATIONS R
  GROUP BY
    R.TRAIN_ID
),
AVERAGEFARES AS (
  SELECT
    T.TRAIN_ID,
    T.TRAIN_NAME,
    TT.TOTAL_FARE / TT.PASSENGER_COUNT AS AVERAGE_FARE
  FROM
    TRAINTOTALS TT
  JOIN
    TRAINS T ON TT.TRAIN_ID = T.TRAIN_ID
)
SELECT
  TRAIN_NAME
FROM
  AVERAGEFARES
ORDER BY
  AVERAGE_FARE DESC
LIMIT 1;

