WITH AVERAGECOOKIES AS ( SELECT SITE_ID, AVG(NCOOKIES) AS AVG_COOKIES_PER_SITE FROM COOKIES GROUP BY SITE_ID ), AVERAGECOMPLIANCE AS ( SELECT SITE_ID, AVG(CASE WHEN IS_COMPLIANT = 1 THEN 1 ELSE 0 END) AS AVG_COMPLIANCE_STATUS FROM COOKIE_COMPLIANCE GROUP BY SITE_ID ) SELECT S.SITE_CATEGORY, AVG(AC.AVG_COOKIES_PER_SITE) AS AVG_COOKIES_PER_SITE, AVG(ACOM.AVG_COMPLIANCE_STATUS) AS AVG_COMPLIANCE_STATUS FROM SITES S JOIN AVERAGECOOKIES AC ON S.SITE_ID = AC.SITE_ID JOIN AVERAGECOMPLIANCE ACOM ON S.SITE_ID = ACOM.SITE_ID GROUP BY S.SITE_CATEGORY ORDER BY S.SITE_CATEGORY;
WITH SITECOOKIECOUNTS AS ( SELECT S.SITE_ID, S.SITE_CATEGORY, COUNT(C.COOKIE_ID) AS COOKIE_COUNT FROM SITES S LEFT JOIN COOKIES C ON S.SITE_ID = C.SITE_ID GROUP BY S.SITE_ID, S.SITE_CATEGORY ), SITECOMPLIANCESTATUS AS ( SELECT SC.SITE_ID, SC.SITE_CATEGORY, AVG(CC.IS_COMPLIANT) AS AVG_COMPLIANCE_STATUS FROM SITES SC JOIN COOKIE_COMPLIANCE CC ON SC.SITE_ID = CC.SITE_ID GROUP BY SC.SITE_ID, SC.SITE_CATEGORY ) SELECT CC.SITE_CATEGORY, AVG(CC.COOKIE_COUNT) AS AVG_COOKIES_PER_SITE, AVG(CS.AVG_COMPLIANCE_STATUS) AS AVG_COMPLIANCE_STATUS FROM SITECOOKIECOUNTS CC JOIN SITECOMPLIANCESTATUS CS ON CC.SITE_ID = CS.SITE_ID GROUP BY CC.SITE_CATEGORY;

