SELECT 
    C.COMPONENT_ID,
    C.COMPONENT_NAME,
    COUNT(AL.ACCESS_ID) AS ACCESS_COUNT,
    SUM(CASE WHEN AL.ACCESS_TYPE = 'VIEW' THEN 1 ELSE 0 END) AS VIEW_COUNT,
    SUM(CASE WHEN AL.ACCESS_TYPE = 'DOWNLOAD' THEN 1 ELSE 0 END) AS DOWNLOAD_COUNT
FROM 
    COMPONENTS C
LEFT JOIN 
    ACCESS_LOGS AL ON C.COMPONENT_ID = AL.COMPONENT_ID
WHERE 
    C.COMPONENT_TYPE = 'IC'
GROUP BY 
    C.COMPONENT_ID, C.COMPONENT_NAME
ORDER BY 
    VIEW_COUNT DESC;
WITH COMPONENT_ACCESS_STATS AS ( SELECT C.COMPONENT_ID, C.COMPONENT_NAME, COUNT(AL.ACCESS_ID) AS ACCESS_COUNT, SUM(CASE WHEN AL.ACCESS_TYPE = 'VIEW' THEN 1 ELSE 0 END) AS VIEW_COUNT, SUM(CASE WHEN AL.ACCESS_TYPE = 'DOWNLOAD' THEN 1 ELSE 0 END) AS DOWNLOAD_COUNT FROM COMPONENTS C LEFT JOIN ACCESS_LOGS AL ON C.COMPONENT_ID = AL.COMPONENT_ID WHERE C.COMPONENT_TYPE = 'IC' GROUP BY C.COMPONENT_ID, C.COMPONENT_NAME ) SELECT COMPONENT_ID, COMPONENT_NAME, ACCESS_COUNT, VIEW_COUNT, DOWNLOAD_COUNT FROM COMPONENT_ACCESS_STATS ORDER BY VIEW_COUNT DESC;

