WITH MODEL_PREDICTIONS AS ( SELECT M.ID AS MODEL_ID, COUNT(PR.ID) AS PREDICTION_COUNT FROM MODELS M LEFT JOIN PREDICTIONS PR ON M.ID = PR.MODEL_ID GROUP BY M.ID ), PROJECT_MODEL_DATA AS ( SELECT P.ID AS PROJECT_ID, P.NAME AS PROJECT_NAME, M.ID AS MODEL_ID, M.NAME AS MODEL_NAME, M.ALGORITHM FROM PROJECTS P JOIN MODELS M ON P.ID = M.PROJECT_ID ) SELECT PMD.PROJECT_NAME, PMD.MODEL_NAME, PMD.ALGORITHM, MP.PREDICTION_COUNT FROM PROJECT_MODEL_DATA PMD JOIN MODEL_PREDICTIONS MP ON PMD.MODEL_ID = MP.MODEL_ID ORDER BY PMD.PROJECT_NAME, PMD.MODEL_NAME;

