WITH AVGCOMBINEDMPG AS ( SELECT C.TYPE_ID, O.ORIGIN_ID, D.DRIVE_TRAIN_ID, AVG(F.COMBINED_MPG) AS AVG_COMBINED_MPG FROM CARS C JOIN ORIGIN O ON C.ORIGIN_ID = O.ORIGIN_ID JOIN DRIVE_TRAINS D ON C.DRIVE_TRAIN_ID = D.DRIVE_TRAIN_ID LEFT JOIN FUEL_EFFICIENCIES F ON C.CAR_ID = F.CAR_ID GROUP BY C.TYPE_ID, O.ORIGIN_ID, D.DRIVE_TRAIN_ID HAVING COUNT(C.CAR_ID) > 1 ) SELECT MIN(AVG_COMBINED_MPG) AS MINIMUM_AVG_COMBINED_MPG FROM AVGCOMBINEDMPG;
WITH TYPEAVG AS ( SELECT C.TYPE_ID, AVG(FE.COMBINED_MPG) AS AVG_MPG FROM CARS C JOIN FUEL_EFFICIENCIES FE ON C.CAR_ID = FE.CAR_ID GROUP BY C.TYPE_ID HAVING COUNT(*) > 1 ), ORIGINAVG AS ( SELECT C.ORIGIN_ID, AVG(FE.COMBINED_MPG) AS AVG_MPG FROM CARS C JOIN FUEL_EFFICIENCIES FE ON C.CAR_ID = FE.CAR_ID GROUP BY C.ORIGIN_ID HAVING COUNT(*) > 1 ), DRIVETRAINAVG AS ( SELECT C.DRIVE_TRAIN_ID, AVG(FE.COMBINED_MPG) AS AVG_MPG FROM CARS C JOIN FUEL_EFFICIENCIES FE ON C.CAR_ID = FE.CAR_ID GROUP BY C.DRIVE_TRAIN_ID HAVING COUNT(*) > 1 ) SELECT MIN(AVG_MPG) AS MIN_AVERAGE_COMBINED_MPG FROM ( SELECT AVG_MPG FROM TYPEAVG UNION ALL SELECT AVG_MPG FROM ORIGINAVG UNION ALL SELECT AVG_MPG FROM DRIVETRAINAVG ) AS ALL_AVERAGES;

