WITH PERMISSIONEDAPPLICATIONS AS ( SELECT APPLICATION_ID FROM APPLICATION_STATUSES WHERE PLANNING_STATUS = 'PERMISSIONED' ), PERMISSIONEDPERMISSIONS AS ( SELECT P.APPLICATION_ID, P.PERMISSION_TYPE FROM PLANNING_PERMISSIONS P INNER JOIN PERMISSIONEDAPPLICATIONS PA ON P.APPLICATION_ID = PA.APPLICATION_ID ), PERMISSIONEDLANDSIZES AS ( SELECT PP.APPLICATION_ID, PP.PERMISSION_TYPE, L.HECTARES FROM PERMISSIONEDPERMISSIONS PP INNER JOIN LAND_SIZES L ON PP.APPLICATION_ID = L.APPLICATION_ID ), APPLICATIONLANDCATEGORIES AS ( SELECT APPLICATION_ID, PERMISSION_TYPE, CASE WHEN HECTARES < 5 THEN 'SMALL' WHEN HECTARES BETWEEN 5 AND 10 THEN 'MEDIUM' ELSE 'LARGE' END AS LAND_SIZE_CATEGORY FROM PERMISSIONEDLANDSIZES ) SELECT PERMISSION_TYPE, COUNT(CASE WHEN LAND_SIZE_CATEGORY = 'SMALL' THEN APPLICATION_ID END) AS SMALL_LAND_COUNT, COUNT(CASE WHEN LAND_SIZE_CATEGORY = 'MEDIUM' THEN APPLICATION_ID END) AS MEDIUM_LAND_COUNT, COUNT(CASE WHEN LAND_SIZE_CATEGORY = 'LARGE' THEN APPLICATION_ID END) AS LARGE_LAND_COUNT, COUNT(APPLICATION_ID) AS TOTAL_APPLICATIONS FROM APPLICATIONLANDCATEGORIES GROUP BY PERMISSION_TYPE ORDER BY TOTAL_APPLICATIONS DESC;

