SELECT T1.TRIAL_ID, T1.AUTHORS, T1.COUNTRY, T1.INTERVENTION, T2.ACCESS_ID, T2.ACCESS_DATE, T2.ACCESS_TYPE, T2.ACCESS_DURATION, T2.ACCESS_REASON, T4.USER_NAME, T4.ROLE, T4.DEPARTMENT, T4.INSTITUTION, T4.LAST_LOGIN_DATE FROM TRIALS AS T1 INNER JOIN ACCESS_LOGS AS T2 ON T1.TRIAL_ID = T2.TRIAL_ID INNER JOIN USERS AS T4 ON T2.USER_ID = T4.USER_ID WHERE T1.COUNTRY = 'SPECIFIC_COUNTRY' AND T1.INTERVENTION = 'SPECIFIC_INTERVENTION' AND T4.ROLE = 'SPECIFIC_ROLE' GROUP BY T1.TRIAL_ID HAVING COUNT(T2.ACCESS_ID) > 1;
