WITH GET_REQUESTS AS ( SELECT USER_AGENT, RESPONSE_TIME, TIMESTAMP FROM SERVER_LOGS JOIN METHODS ON SERVER_LOGS.METHOD = METHODS.METHOD_ID JOIN STATUSES ON SERVER_LOGS.STATUS = STATUSES.STATUS_ID WHERE METHODS.METHOD_NAME = 'GET' AND STATUSES.STATUS_CODE = 200 ), CUMULATIVE_RESPONSE_TIME AS ( SELECT USER_AGENT, SUM(RESPONSE_TIME) AS CUMULATIVE_RESPONSE_TIME FROM GET_REQUESTS GROUP BY USER_AGENT, TIMESTAMP ) SELECT USER_AGENT, MAX(CUMULATIVE_RESPONSE_TIME) AS CUMULATIVE_RESPONSE_TIME FROM CUMULATIVE_RESPONSE_TIME GROUP BY USER_AGENT ORDER BY USER_AGENT, CUMULATIVE_RESPONSE_TIME;
WITH SUCCESSFULGETREQUESTS AS ( SELECT SL.USER_AGENT, SL.RESPONSE_TIME FROM SERVER_LOGS SL JOIN STATUSES S ON SL.STATUS = S.STATUS_ID JOIN METHODS M ON SL.METHOD = M.METHOD_ID WHERE S.STATUS_CODE = 200 AND M.METHOD_NAME = 'GET' ) SELECT USER_AGENT, SUM(RESPONSE_TIME) AS CUMULATIVE_RESPONSE_TIME FROM SUCCESSFULGETREQUESTS GROUP BY USER_AGENT ORDER BY USER_AGENT, CUMULATIVE_RESPONSE_TIME;

