SELECT L.BORROWER_ID, (SUM(CASE WHEN LT.TRANSACTION_TYPE = 'DISBURSAL' THEN LT.TRANSACTION_AMOUNT ELSE 0 END) - SUM(CASE WHEN LT.TRANSACTION_TYPE = 'REPAYMENT' THEN LT.TRANSACTION_AMOUNT ELSE 0 END)) AS NET_LOAN_BALANCE FROM BORROWERS L JOIN LOAN_TRANSACTIONS LT ON L.BORROWER_ID = LT.LOAN_ID GROUP BY L.BORROWER_ID ORDER BY NET_LOAN_BALANCE DESC;
WITH BORROWERLOANDETAILS AS ( SELECT L.BORROWER_ID, SUM(L.LOAN_AMOUNT) AS TOTAL_DISBURSED FROM LOANS L GROUP BY L.BORROWER_ID ), BORROWERREPAYMENTDETAILS AS ( SELECT R.LOAN_ID, SUM(R.REPAYMENT_AMOUNT) AS TOTAL_REPAYMENT FROM REPAYMENTS R GROUP BY R.LOAN_ID ), BORROWERTOTALREPAYMENT AS ( SELECT L.BORROWER_ID, COALESCE(SUM(BRD.TOTAL_REPAYMENT), 0) AS TOTAL_REPAYMENT FROM LOANS L LEFT JOIN BORROWERREPAYMENTDETAILS BRD ON L.LOAN_ID = BRD.LOAN_ID GROUP BY L.BORROWER_ID ), NETLOANBALANCE AS ( SELECT BLD.BORROWER_ID, BLD.TOTAL_DISBURSED - COALESCE(BR.TOTAL_REPAYMENT, 0) AS NET_LOAN_BALANCE FROM BORROWERLOANDETAILS BLD LEFT JOIN BORROWERTOTALREPAYMENT BR ON BLD.BORROWER_ID = BR.BORROWER_ID ) SELECT BL.BORROWER_ID, BL.NET_LOAN_BALANCE FROM NETLOANBALANCE BL ORDER BY BL.NET_LOAN_BALANCE DESC;

