WITH NFO_EXCHANGE_INSTRUMENTS AS ( SELECT I.INSTRUMENT_ID, I.PRODUCT_TYPE FROM INSTRUMENTS I JOIN EXCHANGES E ON I.EXCHANGE_ID = E.EXCHANGE_ID WHERE E.EXCHANGE_CODE = 'NFO' ), NEWS_FOR_NFO AS ( SELECT I.PRODUCT_TYPE, NA.NEWS_DATE, NA.NEWS_TEXT FROM NEWS_AND_ALERTS NA JOIN INSTRUMENTS I ON NA.INSTRUMENT_ID = I.INSTRUMENT_ID WHERE I.INSTRUMENT_ID IN (SELECT INSTRUMENT_ID FROM NFO_EXCHANGE_INSTRUMENTS) ), TRENDS_FOR_NFO AS ( SELECT I.PRODUCT_TYPE, MT.TREND_DATE, MT.TREND_TEXT FROM MARKET_TRENDS MT JOIN INSTRUMENTS I ON MT.INSTRUMENT_ID = I.INSTRUMENT_ID WHERE I.INSTRUMENT_ID IN (SELECT INSTRUMENT_ID FROM NFO_EXCHANGE_INSTRUMENTS) ) SELECT NFI.PRODUCT_TYPE, NF_NEWS.NEWS_TEXT, NF_TRENDS.TREND_TEXT FROM NFO_EXCHANGE_INSTRUMENTS NFI LEFT JOIN NEWS_FOR_NFO NF_NEWS ON NFI.PRODUCT_TYPE = NF_NEWS.PRODUCT_TYPE LEFT JOIN TRENDS_FOR_NFO NF_TRENDS ON NFI.PRODUCT_TYPE = NF_TRENDS.PRODUCT_TYPE ORDER BY NFI.PRODUCT_TYPE, NF_NEWS.NEWS_DATE DESC, NF_TRENDS.TREND_DATE DESC;

