WITH USER_PLAYLIST_COUNTS AS ( SELECT USER_ID, COUNT(*) AS PLAYLIST_COUNT FROM USER_PLAYLISTS GROUP BY USER_ID ), USER_TRACK_PLAY_COUNTS AS ( SELECT USER_ID, COUNT(*) AS TRACK_PLAY_COUNT FROM TRACK_PLAY_COUNTS GROUP BY USER_ID ), TOP_PLAYLIST_CREATOR AS ( SELECT USER_ID, PLAYLIST_COUNT FROM USER_PLAYLIST_COUNTS ORDER BY PLAYLIST_COUNT DESC LIMIT 1 ), TOP_TRACK_PLAYER AS ( SELECT USER_ID, TRACK_PLAY_COUNT FROM USER_TRACK_PLAY_COUNTS ORDER BY TRACK_PLAY_COUNT DESC LIMIT 1 ) SELECT TPC.USER_ID AS MOST_PLAYLISTS_AND_TRACKS_USER, TPC.PLAYLIST_COUNT AS MOST_PLAYLISTS, TTP.TRACK_PLAY_COUNT AS MOST_TRACKS FROM TOP_PLAYLIST_CREATOR TPC INNER JOIN TOP_TRACK_PLAYER TTP ON TPC.USER_ID = TTP.USER_ID;

