WITH MAXPOPULATIONSPECIES AS ( SELECT SR.SPECIES_ID, SR.REGION_ID, SR.POPULATION_SIZE FROM SPECIES_REGION SR INNER JOIN ( SELECT REGION_ID, MAX(POPULATION_SIZE) AS MAX_POPULATION_SIZE FROM SPECIES_REGION GROUP BY REGION_ID ) MAX_POP ON SR.REGION_ID = MAX_POP.REGION_ID AND SR.POPULATION_SIZE = MAX_POP.MAX_POPULATION_SIZE ) SELECT S.SCIENTIFIC_NAME, COUNT(DISTINCT CE.EFFORT_ID) AS CONSERVATION_EFFORTS FROM MAXPOPULATIONSPECIES MPS JOIN SPECIES S ON MPS.SPECIES_ID = S.SPECIES_ID LEFT JOIN CONSERVATION_EFFORTS CE ON S.SPECIES_ID = CE.SPECIES_ID GROUP BY S.SCIENTIFIC_NAME ORDER BY CONSERVATION_EFFORTS DESC;
WITH REGIONMAXPOP AS ( SELECT SR.REGION_ID, SR.SPECIES_ID, MAX(SR.POPULATION_SIZE) AS MAX_POPULATION FROM SPECIES_REGION SR GROUP BY SR.REGION_ID ), SPECIESMAXPOP AS ( SELECT RMP.REGION_ID, RMP.SPECIES_ID, S.SCIENTIFIC_NAME FROM REGIONMAXPOP RMP JOIN SPECIES S ON RMP.SPECIES_ID = S.SPECIES_ID ), EFFORTCOUNTS AS ( SELECT CE.SPECIES_ID, COUNT(CE.EFFORT_ID) AS EFFORT_COUNT FROM CONSERVATION_EFFORTS CE GROUP BY CE.SPECIES_ID ) SELECT SMP.SCIENTIFIC_NAME, COALESCE(EC.EFFORT_COUNT, 0) AS NUM_EFFORTS FROM SPECIESMAXPOP SMP LEFT JOIN EFFORTCOUNTS EC ON SMP.SPECIES_ID = EC.SPECIES_ID ORDER BY NUM_EFFORTS DESC;

