SELECT S.SONG_NAME, S.SONG_ARTIST FROM SONGS S JOIN ( SELECT PH.SONG_ID FROM PLAY_HISTORY PH JOIN ( SELECT DISTINCT SR.USER_ID FROM SONG_RATINGS SR WHERE SR.RATING >= 4 ) HR ON PH.USER_ID = HR.USER_ID GROUP BY PH.SONG_ID ) FREQUENT ON S.ID = FREQUENT.SONG_ID JOIN ( SELECT SR.SONG_ID, AVG(SR.RATING) AS AVG_RATING FROM SONG_RATINGS SR JOIN ( SELECT DISTINCT USER_ID FROM SONG_RATINGS WHERE RATING >= 4 ) HIGH_RATED ON SR.USER_ID = HIGH_RATED.USER_ID GROUP BY SR.SONG_ID ) AVG_RATINGS ON S.ID = AVG_RATINGS.SONG_ID ORDER BY ( SELECT COUNT(PLAY_ID) FROM PLAY_HISTORY PH JOIN ( SELECT DISTINCT USER_ID FROM SONG_RATINGS WHERE RATING >= 4 ) HR ON PH.USER_ID = HR.USER_ID WHERE PH.SONG_ID = S.ID ) DESC, AVG_RATINGS.AVG_RATING DESC LIMIT 10;
WITH HIGHRATEDUSERS AS ( SELECT DISTINCT USER_ID FROM SONG_RATINGS WHERE RATING >= 4 ), FREQUENTPLAYS AS ( SELECT SONG_ID, COUNT(PLAY_ID) AS PLAY_COUNT FROM PLAY_HISTORY WHERE USER_ID IN (SELECT USER_ID FROM HIGHRATEDUSERS) GROUP BY SONG_ID ), AVERAGERATINGS AS ( SELECT SONG_ID, AVG(RATING) AS AVG_RATING FROM SONG_RATINGS WHERE USER_ID IN (SELECT USER_ID FROM HIGHRATEDUSERS) GROUP BY SONG_ID ), SONGDETAILS AS ( SELECT S.ID AS SONG_ID, S.SONG_NAME, S.SONG_ARTIST, COALESCE(F.PLAY_COUNT, 0) AS PLAY_COUNT, COALESCE(A.AVG_RATING, 0) AS AVG_RATING FROM SONGS S LEFT JOIN FREQUENTPLAYS F ON S.ID = F.SONG_ID LEFT JOIN AVERAGERATINGS A ON S.ID = A.SONG_ID ) SELECT SD.SONG_NAME, SD.SONG_ARTIST FROM SONGDETAILS SD ORDER BY SD.PLAY_COUNT DESC, SD.AVG_RATING DESC LIMIT 10;

