WITH GENEACCESS AS ( SELECT G.GENE_ID, G.GENE_NAME, SUM(A.ACCESS_DURATION) AS TOTAL_ACCESS_DURATION FROM ACCESS_LOGS A JOIN GENES G ON A.GENE_ID = G.GENE_ID GROUP BY G.GENE_ID, G.GENE_NAME ), GENESTUDIES AS ( SELECT GENE_ID, COUNT(*) AS TOTAL_STUDIES FROM ( SELECT GENE_ID FROM GWASES UNION ALL SELECT GENE_ID FROM CGDS ) S GROUP BY GENE_ID ) SELECT GA.GENE_NAME, GS.TOTAL_STUDIES FROM GENEACCESS GA JOIN GENESTUDIES GS ON GA.GENE_ID = GS.GENE_ID WHERE GA.TOTAL_ACCESS_DURATION > 1000 ORDER BY GA.GENE_NAME;

