SELECT B.BRAND_NAME, COALESCE(C.COMMENT, 'NO COMMENT MADE ON BRAND') AS COMMENT FROM BRANDS B LEFT JOIN ( SELECT BRAND_ID, COUNT(STRENGTH_ID) AS STRENGTH_COUNT FROM STRENGTHS GROUP BY BRAND_ID HAVING STRENGTH_COUNT > 1 ) S ON B.BRAND_ID = S.BRAND_ID LEFT JOIN ( SELECT BRAND_ID, COUNT(THREAT_ID) AS THREAT_COUNT FROM THREATS GROUP BY BRAND_ID HAVING THREAT_COUNT > 1 ) T ON B.BRAND_ID = T.BRAND_ID LEFT JOIN USER_BRAND_ANALYSES UBA ON B.BRAND_ID = UBA.BRAND_ID LEFT JOIN ANALYSIS_COMMENTS C ON UBA.ANALYSIS_ID = C.ANALYSIS_ID;
WITH BRANDSTRENGTHS AS ( SELECT B.BRAND_ID, B.BRAND_NAME FROM BRANDS B JOIN STRENGTHS S ON B.BRAND_ID = S.BRAND_ID GROUP BY B.BRAND_ID, B.BRAND_NAME HAVING COUNT(S.STRENGTH_ID) > 1 ), BRANDTHREATS AS ( SELECT B.BRAND_ID, B.BRAND_NAME FROM BRANDS B JOIN THREATS T ON B.BRAND_ID = T.BRAND_ID GROUP BY B.BRAND_ID, B.BRAND_NAME HAVING COUNT(T.THREAT_ID) > 1 ), FILTEREDBRANDS AS ( SELECT BS.BRAND_ID, BS.BRAND_NAME FROM BRANDSTRENGTHS BS INTERSECT SELECT BT.BRAND_ID, BT.BRAND_NAME FROM BRANDTHREATS BT ), BRANDCOMMENTS AS ( SELECT FB.BRAND_ID, FB.BRAND_NAME, AC.COMMENT FROM FILTEREDBRANDS FB LEFT JOIN USER_BRAND_ANALYSES UBA ON FB.BRAND_ID = UBA.BRAND_ID LEFT JOIN ANALYSIS_COMMENTS AC ON UBA.ANALYSIS_ID = AC.ANALYSIS_ID ) SELECT BC.BRAND_NAME, CASE WHEN BC.COMMENT IS NULL THEN 'NO COMMENTS MADE ON THIS BRAND' ELSE BC.COMMENT END AS BRANDCOMMENT FROM BRANDCOMMENTS BC;

