SELECT AG.AGE_GROUP_NAME FROM AGE_GROUPS AG JOIN ( SELECT VA.AGE_GROUP_ID, SUM(VA.TOTAL_NUMBER_VACCINES_ADMINISTERED) AS TOTAL_VACCINES FROM VACCINE_ADMINISTRATION VA GROUP BY VA.AGE_GROUP_ID ) AS VACCINE_TOTALS ON AG.AGE_GROUP_ID = VACCINE_TOTALS.AGE_GROUP_ID ORDER BY ( CASE AG.VACCINATION_PRIORITY WHEN 'HIGH' THEN 1 WHEN 'MEDIUM' THEN 2 ELSE 3 END );
WITH AGE_PRIORITY_ORDER AS ( SELECT AG.AGE_GROUP_ID, AG.AGE_GROUP_NAME, AG.VACCINATION_PRIORITY, SUM(VA.TOTAL_NUMBER_VACCINES_ADMINISTERED) AS TOTAL_VACCINES FROM VACCINE_ADMINISTRATION VA INNER JOIN AGE_GROUPS AG ON VA.AGE_GROUP_ID = AG.AGE_GROUP_ID GROUP BY AG.AGE_GROUP_ID, AG.AGE_GROUP_NAME, AG.VACCINATION_PRIORITY ) SELECT AGE_GROUP_NAME FROM AGE_PRIORITY_ORDER ORDER BY CASE WHEN VACCINATION_PRIORITY = 'HIGH' THEN 1 WHEN VACCINATION_PRIORITY = 'MEDIUM' THEN 2 ELSE 3 END;

