SELECT 100.0 * (CASE WHEN CASH_FLOW.AMOUNT > RESTRICTED.AMOUNT THEN 1.0 ELSE 0.0 END) AS PERCENTAGE_EXCEEDING FROM ( SELECT SUM(AMOUNT) AS AMOUNT FROM CASH_FLOW_DISCLOSURES WHERE PERIOD_ID = 0 ) AS CASH_FLOW CROSS JOIN ( SELECT TOTAL_AMOUNT AS AMOUNT FROM RESTRICTED_CASH WHERE PERIOD_ID = 0 ) AS RESTRICTED;
WITH TOTALCASHFLOW AS ( SELECT EF.PERIOD_ID, SUM(CD.AMOUNT) AS TOTAL_CASH_FLOW FROM ENTITY_FINANCIAL_DATA EF JOIN CASH_FLOW_DISCLOSURES CD ON EF.CASH_FLOW_ID = CD.DISCLOSURE_ID WHERE EF.PERIOD_ID = 0 GROUP BY EF.PERIOD_ID ), TOTALRESTRICTEDCASH AS ( SELECT EF.PERIOD_ID, RC.TOTAL_AMOUNT AS TOTAL_RESTRICTED_CASH FROM ENTITY_FINANCIAL_DATA EF JOIN RESTRICTED_CASH RC ON EF.RESTRICTED_CASH_ID = RC.RESTRICTED_CASH_ID WHERE EF.PERIOD_ID = 0 ) SELECT (CASE WHEN TCF.TOTAL_CASH_FLOW > TRC.TOTAL_RESTRICTED_CASH THEN 1.0 ELSE 0.0 END) * 100 AS PERCENTAGE_POSITIVE_CASH_FLOW FROM TOTALCASHFLOW TCF JOIN TOTALRESTRICTEDCASH TRC ON TCF.PERIOD_ID = TRC.PERIOD_ID;
